window.__D("tolt-3",[[51,"וכמ\"ש לי הכסף ולי הזהב נאם ה' שהכסף והזהב הגשמיים הם נתגשמו בירידתם מטה מטה בהשתלשלות רבות ועצומות. אבל במקורם למעלה הם לי ובטלים אלי לפי ששרשם הוא מבחי' נאם ודבר ה'."],[51,"וכל מה שיעמיק בזה ויותר מזה לבבו יבין שלא לנטות ולא לימשך בלתי לה' לבדו. ויהיה רצונו רק אליו ית' לדבקה בו עד מיצוי הנפש. ואחר שיהיה כך ברצוא יהיה כך בשוב להיות והיו הדברים האלה אשר אנכי מצוך היום על לבבך ודברת בם בשבתך בביתך ובלכתך בדרך כו' כי אין לו להקב\"ה בעולמו אלא ד\"א של הלכה בלבד. פי' מאחר שהוא קדוש כו'. אין לו ⟦לו,ג⟧שייכות להיות שורה ומתלבש בעולם אלא ע\"י ד\"א של הלכה שעי\"ז נעשה דירתו ממש בתחתונים שהיא חכמתו ורצונו כו' וזה כל האדם להיות רץ לבך ושוב לאחד כו' כי בע\"כ אתה חי כו'."],[51,"ובזה תהיה כל הנשמה תהלל יה כי ע\"י אתעדל\"ת אתעדל\"ע. שע\"י בחי' רצוא שבעבודת האדם כך הוא למעלה בחי' הסתלקות וצמצום אוא\"ס ב\"ה. וע\"י בחי' שוב כך הוא בחי' המשכת אוא\"ס ב\"ה בהשתלשלות המדרגות למטה מטה כדי להאיר התגלות התענוג של הנשמות להתענג על ה'. וזהו ה' צלך כצל שהוא פונה אחרי האדם. כך הוא ית' כביכול צל שלך. והיינו על יד ימינך דהיינו ע\"י אהבה במס\"נ בבחי' רצוא כנ\"ל. וזהו נר הוי\"ה נשמת אדם שנשמת אדם שהוא בחי' נשימה ברו\"ש היא בחי' נר להאיר ולהמשיך אוא\"ס ב\"ה בג\"ע כו':"],[51,"<b>אך<\/b> כדי לבא למדרגת בחי' רו\"ש הנ\"ל א\"א לאדם להגיע ע\"י התבוננות בה' אחד ברוח בינתו לבד שמשכלו ובינתו לא תוליד אהבה כזו. הגם שע\"פ שכלו ותבונתו יבין שכך יאתה מ\"מ לא יגרום כח המושך בפו\"מ אלא עז\"נ כי אתה נרי הוי\"ה. אתה הוא בחי' תומ\"צ. כי א\"ת הם בחי' אותיות התורה מא' ועד תי\"ו."],[51,"וה' הוא בחי' המצות. ועי\"ז וה' יגיה חשכי שיש חשך המחשיך ומונע מלהאיר אור האהבה לה' הגם שיתבונן שכך יאתה. והוא חשך הגוף ונפש החיונית המלבישים את נפש האלקית. וצ\"ל תחלה סומוע\"ט ע\"י שיהי' ממארי דחושבנא ממעשים ודבורים ומחשבו' אשר לא לה' המה כל ימי חיי הבלו כל חד לפום מאי דידע בנפשו נגעי לבבו שהם המונעים ומעכבים את אור האהבה כי כל איש אשר בו מום לא יקרב לחם אלקיו לא יגש להקריב כו'."],[51,"וכדכתיב ותמימים ינחלו טוב ואין טוב כו'. משא\"כ בעלי מומין שבעלי מומין פסולין לגבי מזבח. ואף אם עלו ע\"ג מזבח מורידין אותן. וכשם שהוא בקרבנות כך הוא בכל אשר יקריב נפשו לה' כל איש אשר בו מום לא יוכל ליקרב בק\"ש להיות לו מס\"נ באמת ומורידים אותו מלמעלה ומפילים אותו למטה עד אשר ישוב אל ה' וירחמהו כו'. ואז נותנים לו סיוע מלמעלה להיות מעורר את האהבה לה' בק\"ש."],[51,"והנה בחי' זו נק' בת בחי' מקבל שאין נפשו בטילה לה' במס\"נ בטבע עד אשר יערה עלי' רוח ממרום ועז\"נ שמעי בת וראי והטי אזנך ושכחי עמך ובית אביך. פי' עמך ובית אביך. היינו מה שהורגלת בו ונמשכת אחריהם בהבלי העולם. עכ\"פ שכחי לפנות דעתך לקבל ע\"ע עומ\"ש שצריך להיות כלי לקבל את אור האהבה הבאה מלמעלה."],[51,"ואזי ויתאו המלך יפיך. יופי ההארה שיאיר את האהבה שהיא בחי' נר כנ\"ל. ועז\"נ תתן אמת ליעקב. כי נש\"י הם ב' בחי' יעקב וישראל. ישראל הוא בחי' כי שרית ותוכל שכבר גבר ונצח המלחמה משא\"כ יעקב יו\"ד עקב דהיינו שירד מטה בבחי' עקב אלא שיש לו בחי' יו\"ד בראשו שאליו יומשך ממטה למעלה. ועדיין אין לו בחי' אמת בנפשו בטבע ממש. רק שה' יתן אמת ע\"י סיוע מלמעלה. וחסד לאברהם פי' שיהיה בחי' אברהם הוא בחי' האהבה שהיא באה בתורת חסד מלמעלה. וכ\"ז הוא מימי קדם מבחי' תשובה שקדמה לעולם:"],[51,"<b>וביאור<\/b> ענין אחותי. הוא בחי' ומדרגת מארי תורה שתורתם אומנתם כי במעלת התורה איתא במדרש מצינו שויתר הקב\"ה על ג\"ע וש\"ד. ולא ויתר על בטול תורה. והענין כי הנה עסק התורה הוא המשכת דירתו ית' בתחתונים כי כל עניני התורה אסור ומותר. כשר ופסול. טמא וטהור. הוא רק הבדלה בין ⟦לו,ד⟧טוב לרע. וכמ\"ש להבדיל בין החיה הנאכלת ובין כו'."],[51,"והנה כתיב בי מלכים ימלכו. ואמרו מתניתין מלכתא שהיא כמלך שמצוה לעשות כך וכך כו' כמ\"ש במ\"א. והנה כתיב אם תגביה כנשר כו'. משם אורידך נאם ה' שנאם ה' ודבורו הוא המוריד ומשפיל הקליפות וס\"א למטה ויתפרדו כל פועלי און. וכך האדם ע\"י עסקו בתורה. ומבדיל בין איסור והיתר. ובין כשר לפסול כנ\"ל. הנה הוא מוריד האיסור והפסול ומדחהו למטה ע\"י דבר ה' אשר בפיו זו דבר הלכה נתקיים בו ועל ידו משם אורידך נאם ה' ולכן נק' ישראל אחים וריעים להקב\"ה. וכמ\"ש להנחיל אוהבי יש. למען אחי וריעי כו':"],[51,"<b>וזהו<\/b> הקל קול יעקב והידים ידי עשו. שבזמן שהקל קול יעקב אין ידי עשו שולטות בו. כי אין יניקה לחיצונים מאחר שמבדילים ומבררים. והיינו בזמן שהקל קול. פי' שהקול עליון הוא דבר ה' מתחבר בקול שלמטה להיות כמ\"ש ואשים דברי בפיך וכתיב ודברי אשר שמתי בפיך דברי ממש שאז הוא בחי' מתניתין מלכתא."],[51,"ובחי' זו נק' אחותי רעיתי יונתי תמתי. א\"ת תמתי אלא תאומתי שנעשו בחי' אחים תאומים ממש כביכול. אך כל האומר אין לי אלא תורה אפי' תורה אין לו. כי מעלת התורה היא משום דאורייתא וקוב\"ה כולא חד."],[51,"וצ\"ל גם באדם למס\"נ באחד שמשם מקור התורה ולהיות לו רק רצון א' כו' כנ\"ל. שעי\"ז הוא ממשיך גילוי התורה שמשם מקור חוצבה ושרשה דאורייתא מחכ' נפקת. וכתיב ויקם עדות ביעקב ותורה שם בישראל. פי' כי הנה יש ב' בחי' ישראל ויעקב."],[51,"וכנגד זה יש ב' בחי' בתורה עדות ותורה. ומבחי' יעקב נמשך בחי' עדות ומבחי' ישראל נמשך בחי' תורה. וכמ\"ש ועשיתם אתם אתם כתיב. וכתיב אשר יעשה אתם האדם. כי ע\"י האדם נמשך בחי' תומ\"צ. והיינו ע\"י מס\"נ באחד שאז כל הנשמה תהלל יה כו' כנ\"ל. ובחי' זו נקראת אמי שהוא בחי' אם הבנים. שהיא היא המוליד הגילוי אלקות אוא\"ס ב\"ה בג\"ע ותענוג הנשמות זו תורה ועבודה כו'. ולע\"ל כתיב רני ושמחי בת כו'. שבחי' בת תעלה ביתר שאת כנ\"ל. ולהיות אשת חיל עט\"ב כו' כמ\"ש במ\"א:"],[51,"קצת ביאור על זה"],[51,"<b>הנה<\/b> בת הוא בחי' המתברר. ואחותי שהוא בחי' מארי תורה הוא המברר. וכמ\"ש בת\"ז פקודא לאפרשא בין דכיא כו' (שהוא בחי' תורה להבדיל בין הטמא לטהור כו') ודברי אשר שמתי בפיך. והוא ענין כשר לפני המלך. משא\"כ בת בחי' מצות כעבד לפני המלך. והכל נרמז בנר חנוכה. (עיין פע\"ח שער חנוכה פ\"ד וכן בשער השבת בתחלת פ\"ד) ג' יחודים הוי' אהיה. הוי' אלקים. הוי' אדני. גימ' נר. יחוד הוי' אהיה שהוא יחוד או\"א הוא ע\"י מס\"נ בק\"ש הארת הכתר. ויחוד זו\"נ (היינו יחוד הוי\"ה אלקים) הוא ע\"י התורה ויחוד הג' (הוי' אדני) בחי' המצות הוא כשבאים כל האורות בבחי' חותם. והוא ענין תתן אמת ליעקב. כי תורת אמת הוא בז\"א ומלכות מקבלת בבחי' חותם. ולע\"ל יתעלה בחי' בת כי יהיה גדול כח המתברר שהוא משם ס\"ג כנודע כי נעוץ סופן כו' וסוף מעשה כו' ויהי' בבחי' תגא על רישיה (כמ\"ש ברע\"מ פ' תרומה ד' קנ\"ח א' ושאר דוכתי):"],[52,"<b>רני ושמחי בת ציון כי הנני בא.<\/b> להבין ענין רני ושמחי וגם מה ענין זה להפטורת חנוכה שמתחילין ברני ושמחי וגו' והיה ⟦לז,א⟧להתחיל מן ראיתי והנה מנורת זהב וגו' שבסוף הפרשה."],[52,"והענין הוא דכתיב עבדו את ה' בשמחה באו לפניו ברננה. ואיתא בזהר שמחה בצפרא ורננה ברמשא. וצריך להבין מהו צפרא ומהו רמשא מהו שמחה ומהו רננה. ויובן בהקדים כי מודעת זאת שעבודת המלאכים היא רנה וזמרה בשירות ותשבחות כנודע מענין פרק שירה שכל הברואים אומרים שירה."],[52,"וכן המלאכים שבכל עולם עד רום המעלות כולם אומרים שירות ותשבחות ברנה וזמרה. וענין רנה זו היא גילוי עוצם תשוקתם להיות נכספה וגם כלתה נפשם לדבקה בו ית' ולהתכלל באור א\"ס ב\"ה ותמיד כל ימיהם עומדים בתשוקה זו בלי הפסק מחמת שאין להם אהבה ותשוקה אחרת וגם אין להם עבודה אחרת כמו תומ\"צ שהם בחינת המשכה מלמעלה למטה רק עבודתם היא השתוקקות נפשם ממטה למעלה ותשוקה זו היא ברנה וזמרה כנודע מענין הניגון שהוא ענין התפעלות הלב (כי יש ניגון של שמחה ויש של מרירות כו') והנה זו היא בחי' חיצוניות כנודע ע\"ד משל מי שהוא עומד בפנים בבית המלך מה לו להגיד ולספר בשבחו רק כשיצא לחוץ ידבר ויספר בשבחו להפליא ולהגדיל גודל עוצם שבח המלך כמה הוא גדול ומתפעל כו' והוא ענין מ\"ש וצדקתך ירננו שהרנה היא בבחי' צדקתך כי צדק היא מלכותא קדישא (מאזני צדק פי' שיש בחינת מאזנים ששוקלים בחינת עומ\"ש שנמשך לכל חד וחד לפום שיעורא דיליה) וכתיב צדק מלאה ימינך כי מלכותך מלכות כל עולמים כתיב שאין ערך לבורא עם נברא להיות הנבראים מקבלים חיות מן הבורא ית' אלא ע\"י בחינת מלוכה שלפי שהוא ית' מלך עליהם הם חיים וקיימים."],[52,"וזהו מלכותך מלכות כל עולמים וממשלתך בכל דור ודור עולמים הם בחינת מקום ודור דור הוא בחי' זמן הכל נמשך מבחי' מלכותך שהרי הזמן והמקום הם נבראים ומחודשים מאין ליש. שקודם בריאת העולם לא היה בחי' זמן ומקום כלל ולא היו יכולים להיות נבראים שהם בעלי גבול בבחי' זמן ומקום אלא ע\"י בחי' מלכותו ית' שבה שייך בחי' זמן מלך מלך ימלוך כו' משא\"כ באוא\"ס ב\"ה עצמו שכשמו כן הוא אין לו סוף כו'."],[52,"ולפי שהחיות נמשך מבחי' מלכותו ית' היא בחי' צדק לכך מלאה ימינך בחי' ימין וחסד כמאמר מכלכל חיים בחסד וכתיב ואתה מחיה את כולם וצבא השמים לך משתחוים פי' כי לפי שאתה מחיה את כולם לכך וצבא השמים לך משתחוים בבחי' בטול והתכללות."],[52,"והנה בחי' בטול זה הוא באור א\"ס ב\"ה הנמשך ומתלבש בבחינת מלוכה להחיותם כי אליו ולא למדותיו כו' וזהו זכר רב טובך יביעו וצדקתך ירננו פי' טובך הוא השפעה וחיות שנמשך מעולם ועד עולם כמ\"ש אמרו צדיק כי טוב שהטוב הוא בחינת צדיק שהוא המקשר ומשפיע מעולם ועד עולם כמו שכתוב כי כל בשמים ובארץ ותרגומו דאחיד כו' ורב טובך היינו כמה רבוא רבבות מדרגות עד אין קץ שהן בבחינת השתלשלות וירידת המדרגות מעולם ועד עולם עד שיאיר אור א\"ס ב\"ה בבחינת מלכותו להוות ולהחיות נבראים עד אין קץ."],[52,"והנה פי' זכר רב טובך היינו שרק בחי' זכר והארה מבחינת רב טובך יביעו ולכך ירננו שמשתוקקים ונכספים להתכלל באור א\"ס ב\"ה שאומרים איה מקום כבודו כו' רק שאין להם השגה באור א\"ס ב\"ה עצמו אלא ע\"י בחינת מלוכה ובחינת צדקתך."],[52,"וזהו רננה ברמשא רמשא היא מדת לילה היא בחינת מלכותו ית' מלכותך מלכות כל עולמים מלשון העלם כו' וע\"ז רמזו בגמרא שצריך להזכיר מדת לילה ביום דהיינו כמו שמבואר בזוהר לאכללא כו' שע\"י שמשיגים החשך וההעלם של אא\"ס ב\"ה ישת חשך סתרו לכך הם ⟦לז,ב⟧משתוקקים ונכספים אליו ית' וכמ\"ש נפשי אויתיך בלילה פי' שאומר להקב\"ה הרי נפשי אתה לכך אויתיך. מפני שהחיות הזה הוא מוסתר בבחינת לילה והעלם ולכך תגדל התשוקה והכוסף להיות אויתיך וכנודע שלא שייך אהבה ותשוקה להתאות תאוה אלא במי שחסר לנפשו הדבר שמתאוה אליו."],[52,"וזהו ענין בואו לפניו ברננה ממטה למעלה לצאת מנרתק הגוף ולבושי נפש הבהמית לדבקה בו ית' ע\"י רננה בבחינת רמשא ומדת לילה היא בחינה שמוסתר ומלובש בה אור א\"ס ב\"ה בבחינת העלם והסתר."],[52,"וזהו ענין בשכמל\"ו ואהבת וגו' דהיינו שלבבו יבין איך שברוך ונמשך שם הארה מאור א\"ס ב\"ה להיות כבוד מלכותו והארה ההיא היא לעולם ועד למטה עד אין קץ כו' שעי\"ז יבוא לאהבה את הוי\"ה הוא אור א\"ס ב\"ה ממש להיות אלהיך בכל לבבך ובכל נפשך וגו' לאדבקא רוחא ברוחא. אך כל זה הוא בבחינת ממטה למעלה בואו לפניו שאזי הוא ברננה וכך צריך להיות תחילת עבודת האדם כברייתו של עולם בריש' חשוכא והדר נהורא מדת יום היינו המשכת אור א\"ס ב\"ה מלמעלה למטה להתלבש בעולמו' אבי\"ע בחינת עבדו את ה' בשמחה שזהו יתרון ומעלת הנשמות על המלאכים שהמלאכים אין להם רק בחינת רנה בלבד שהיא בחי' העלאה והתכללות ממטה למעלה משא\"כ נשמת ישראל יש להם עבודה נוספת בבחי' המשכה מלמעלה למטה מההעלם אל הגילוי שכל שמחה היא התגלות הפנימיות וכו' כנודע שבחי' שמחה זו היא מהמשכת אור א\"ס ב\"ה בתומ\"צ (שנתנו לישראל דוקא משא\"כ המלאכים בקשו תורה תנה הודך על השמים ולא ניתן כו'). וכמ\"ש והיו הדברים האלה אשר אנכי מצוך היום וגו' אנכי מי שאנכי כו' כי הגם שממטה למעלה כתיב בואו לפניו ברננה שא\"א להיות בחי' העלאה והתכללות כ\"א בבחי' צדקתך ובחי' רננה ברמשא אבל מלמעלה למטה אור א\"ס ב\"ה מאליו וממילא נמשך גם מבחי' אנכי מי שאנכי כי לפניו ית' כחשיכה כאורה."],[52,"וכמ\"ש המשפילי לראות בשמים ובארץ שמים וארץ רוחניות וגשמיות הכל שוה לפניו ית' השוה ומשוה קטן וגדול. והמשכה זו היא ע\"י תומ\"צ הדברים האלה אשר אנכי וגו' רמ\"ח מצות הם רמ\"ח איברין דמלכא דהיינו כמשל האיברים שבהם מלובשת הנשמה ובהמשכת האברים נמשכת גם הנשמה המלובשת בהם. ודרך כלל נחלקים לג' קוין חסד דרוע' ימינא היא בחי' צדקה כו' ותורה היא קו הממוצע (וכנודע שהתורה היא בחינת אברים הפנימיי' ושאר מצות הם אברי' החיצונים כו'). וזהו עבדו את ה' הוא א\"ס ב\"ה הנמשך אורו מלמעלה למטה בתורה ועבודה כו' בשמחה היא שמחה של מצוה ואמרו רז\"ל וכן לדבר הלכה והשמחה היא מבחי' גילוי אוא\"ס ב\"ה ממש על נפשם כו'. והיינו ע\"י כי באו לפניו ברננה תחלה כנ\"ל והכתוב מדבר מלמעלה למטה עבדו את ה' בשמחה והיאך תבואו למדרגה זו כשתבאו לפניו ברננה:"],[52,"<b>ובזה<\/b> יובן מ\"ש רני ושמחי בת ציון כי כנ\"י בגלות נק' בת ציון. וביאור ענין ציון יובן בהקדי' להבין מ\"ש ימלוך ה' לעולם אלהיך ציון לדור ודור הללו יה. וביאור הענין כי להיות ימלוך ה' לעולם בחינת מקום לדור ודור בחינת זמן היינו ע\"י בחינת ציון. כי הנה כתיב בצלמנו כדמותנו הן רמ\"ח פקודין רמ\"ח אברין דמלכא והיינו רוחניות המצות ורוחניות התורה כמן שהן למעלה באור א\"ס ב\"ה שהן הן בצלמנו ממש. אך גשמיות המצות כמו שנתלבשו בענינים גשמיים ציצית של צמר ותפלין על הקלף הם רק בחינת ציון מלשון סימן כמו ציון המצוינת דהיינו שהמצות הגשמיות ⟦לז,ג⟧הם רומזים להרוחניות שבהם ועל ידם נמשך רוחניות אור א\"ס ב\"ה כמו טלית וציצית של צמר בבחינת עטה אור כשלמה לבושיה כתלג חיור ושער רישיה כעמר נקא כי ציצית הן בחינת שערות כו'."],[52,"וע\"ד זה כל המצות וכן התורה ע\"י עסק התורה בגשמיות שנתלבשה בענינים גשמיים נמשך אור תורה העליונה הרוחנית שמדברת בענינים רוחניים. והרי התורה והמצות גשמיות הם סימנים וציונים להרוחניות. ובהן ועל ידן נמשך אור התורה והמצות מרוחניות לגשמיות והן הן בחי' מקור להיות בחי' מקום וזמן."],[52,"וע\"ד זה תקנו רז\"ל ברכות המצות לפני כל מצוה ברוך אתה וכו' כי ברוך מלשון המבריך הגפן שכופף ראש הזמורה לארץ ומשם צומח גפן אחר והיינו בחי' השפעה והברכה מעולם ועד עולם לכן כתיב גבי יוסף ויקראו לפניו אברך לפי שהיה צדיק המקשר ומשפיע ומבריח מעולם ועד עולם."],[52,"וענין ברכה זו הוא להיות המשכה והברכה מעולם ועד עולם כדי להיות גילוי מלך העולם להיות בחינת עולם בבחינת מלך דהיינו שיהא גילוי מלכותו ית' נראה לעין כל העולם שלא יהא העולם בבחינת העלם והסתר על בחינת מלוכה. וכדי להיות גילוי זה אומרים ברוך שיהא ברוך ונמשך בחינת הוי\"ה בבחינת אלקינו ומשם יצמח גילוי בחינת מלוכה כמו ענין הברכת הגפן הנ\"ל."],[52,"והנה כשיש אתערותא דלתתא אזי נק' כנסת ישראל בבחי' ציון וסימן לאור הרוחני הנשפע ונמשך בה. אבל בגלות נקרא' בת ציון שהיא רק בחינת מקבל מבחי' ציון וכנודע בזוהר מענין איש מזריע תחילה יולדת נקבה דהיינו כשאין אתערותא דלתתא שאזי היא בחינת בת משא\"כ ולציון יאמר איש ואיש וגו' אשה מזרעת תחלה יולדת זכר בחי' חסדים דהיינו בהקדים בחינת רינה ושמחה כנ\"ל להיות בואו לפניו ברננה בבחי' רננה ברמשא ממטה למעלה."],[52,"וע\"ד זה תקנו פסוקי דזמרה להקדים שבחו של מקום כדי שיתפעל הלב. וכן יוצר אור וענין קדושת המלאכים איך כי והאופנים ברעש גדול כו' הכל הוא בבחי' ממטה למעלה בבחינת רינה לצאת מנרתק הגוף ולבושי נפש הבהמית כו' ואח\"כ היא עבודת השמחה בגילוי אוא\"ס ב\"ה ממש על נפשו בק\"ש וכו' משא\"כ כשלא תוקדם בחי' הרינה אזי לא תשכון גלוי השמחה רק היא בחינת נקבה ומקבל מאתערותא דלעילא שהרי מ\"מ מאתערותא דלעילא יורד ונמשך אוא\"ס ב\"ה בכל מצוה שעשה וכדכתיב למעני למעני אעשה אלא שאינו כ\"א בבחי' חיצוניות משא\"כ בואו לפניו להיות נכלל בבחי' פנימיות אינו אלא ברננה."],[52,"וזהו שבא הנביא לנחם את בני ישראל אפי' בזמן הגלות שנק' בת ציון ולא ציון שאעפ\"כ רני ושמחי והיינו מפני כי הנני בא כו' כי הנה יש אתערותא דלעילא שהיא לעילא לעילא מקום שאין אתערותא דלתתא מגעת שם כלל הוא בחי' סובב כל עלמין ומשם יומשך גילוי שפע ואוא\"ס ב\"ה גם בבחינת בת וזה יהיה לעתיד לבא שנא' הנה ישכיל עבדי ירום ונשא וגבה מאד ונחה עליו רוח ה' וגו' והריחו וגו'."],[52,"וזהו ולציון יאמר איש ואיש יולד בה פי' שיהא הכל בבחי' איש אפי' בחי' בת והיינו מפני כי הוא יכוננה עליון שהמכון יהיה אור עליון מאד נעלה. וזהו כי הנני בא ושכנתי בתוכך. הנני אני בעצמי כביכול אוא\"ס ב\"ה ממש."],[52,"וזהו ענין נר חנוכה שתקנו על פתח הבית מבחוץ והוא כענין פתחו לי שערי צדק פי' שערי צדק הם בחי' מבוא להיות בחי' צדקתך ירננו שע\"ד זה תקנו פסוקי דזמרה אך מי שהוא מבחוץ לפתח שאין לו בחי' רננה והתפעלות הלב לא מפני זה יאבד ח\"ו גלוי אוא\"ס ב\"ה על נפשו אלא תקנו להדליק אור ושמן על הפתח מבחוץ שגם מבחוץ לפתח יומשך אוא\"ס ב\"ה בכל מצוה שעוש' ⟦לז,ד⟧ותורה שלומד. ולא עוד אלא שתקנת חכמים היתה להדליק על הפתח הסמוך לרשות הרבי' מבחוץ דהיינו ברשות הרבים ממש מקום הקליפות לאהפכא חשוכא לנהורא כו' וזהו ונלוו גוים רבים אל ה':"],[53,"ביאור על הנ\"ל"],[53,"<b>ביאור<\/b> ענין רני ושמחי בת ציון. הנה ציון לשון זכר ול' נקבה שהוא בחינת דכר ונוקבא דהיינו יסוד דנוק' (וירושלים הוא מל' שבמל' היא בחי' חותם כו' ובת ציון היינו כשיורדת לבי\"ע לברר כו'. ורני היינו שיומשך בחי' גבורות דאימא שהן בחינת רשפי אש והסתלקות מחמת התבוננו' בא\"ס כו'. ושמחי חסדים דאימא שהיא בחי' שמחה וגילוי אם הבנים שמחה כו'. וביאור ענין זה יובן בהקדים לבאר ההפרש שבין מלאכים לנשמות. הנה המלאכים אין להם רק בחי' רינה ולא שמחה שהרי אין להם עבודת ההמשכה מלמעלה למטה ע\"י תומ\"צ כו') הוא בחי' גבורות והסתלקות כל בעלי השיר יוצאין בשיר כו' יוצאין מן הכלי. אך המלאכים אין להם בטול כלי שהגוף על עמדו עומד אלא שמתפעל כו'. וזו היא בחי' רנה שהיא בחי' חיצוניות שהרנה הוא ספור שבחו של מקום."],[53,"ועד\"מ מי שעומד לפני המלך מה לו להגיד ולספר רק כשיצא לחוץ ידבר כדי להלהיב ולהלהיט כו' ויציאתם בשיר ותענוג שמתענגין במה שמרבין לספר בגדולת א\"ס ב\"ה ויוצאים ממקומם מעולם לעולם ומהיכל להיכל ומתכללין בהיכלות כו' ומרנני' בניגונים כי הניגון הוא ענין התפעלות הלב שהוא רק המשכת קול בלא דבור שהקול הוא שיוצא מן הלב בלבד קודם שמתחלק בדבור הפה ויש כמה מיני נגון הכל לפי האהבה יש אהבה בתענוגים ויש אהבה במרירות (שמתמרמר על ריחוקו מחמת האהבה הגדולה) ויש אשר נגעה עד הנפש כו' וכיוצא בזה. ודרך כלל היא בחי' אהבה שהאהב' כוללת כל הבחי' יומם דאזיל עם כולהו יומין עננא דאהרן כו'. וכמו שלא היה רק ענן א' בזכות אהרן ואעפ\"כ הם ז' ימי סכות ז' מקיפים שמתחלקים חסד שבחסד גבורה שבחסד כו'."],[53,"והנה רנה זו היא בחי' גבורות דאימא שהיא האהבה מחמת ריחוק כי לפי הריחוק כך תגדל האהבה וההמשכה ממטה למעלה ביתר שאת להיות נכספה וגם כלתה נפשי לחצרות כו'. ונפשי אויתיך בלילה. בלילה דוקא שלא שייך להיות מתאוה אא\"כ חסר לנפשו הדבר ההוא שמתאוה אליו והשגת' ריחוק זה הוא מ\"ש וצדקתך ירננו וזכר רב טובך יביעו. כי זכר והארה מרב טובך כו'."],[53,"וכמה צמצומים עד שנמשך בבחי' צדק מלכותא קדישא. ואי לזאת נכספה וגם כלתה נפשם ובטלה לאוא\"ס השוכן ומתלבש בבחינת מל' כי אליו ולא למדותיו. רק שאין השגתם באור א\"ס אלא במה שנתלבש בבחי' מל' להיות מלך שמו נק' עליהם שזהו חיותם וקיומם כו'."],[53,"ובזה יובן ענין רננא ברמשא מדת לילה שהמל' כשיורדת לבי\"ע ובוקעת המסך כו' הנה מחמת ריחוקה כתיב אלקים אל דמי לך אל תחרש ואל תשקוט כו'. ואזי היא בבחי' רינה וזמרה. וכמ\"ש נתן זמירות בלילה. וזמרה זו היא התשוקה להתכלל למעלה מתרפקת על דודה כו'. ולכן עבודת המלאכים ג\"כ ברינה שהרי נמשכים מבחי' מל' ומל' דבריאה הוא מקור וחיות המלאכים דבריאה. ומל' דיצירה וכו'. אך המלאכים אין להם אלא בחי' רינה בלבד לפי שאין מקורם אלא בחי' מל' בלבד. משא\"כ נש\"י הם כלולים מכל הפרצופים (נעשה אדם בצלמנו) או\"א זו\"נ. ולכן יש להם ג\"כ בחי' שמחה היא בחי' המשכה מלמעלה למטה בתומ\"צ רמ\"ח איברין דמלכא ט\"ס דז\"א כי טפ\"ט הם פ\"א וג\"פ פ\"א שבכל ספי' יש ג' כלים פנימי ⟦לח,א⟧חיצון תיכון הם רמ\"ג וה\"ח (דאימא) המגדילים הם רמ\"ח. והמשכה זו בז\"א אורייתא מחכמה נפקת ושרשה למעלה מן החכמה תר\"ך עמודי אור שבכתר היא גלגלתא ומו\"ס דא\"א. וכל האורות נמשכין בז\"א כל ארחות הוי\"ה כו'. פי' ארחות להיות הוי\"ה כו' הם בחי' תרי\"ג ארחין מחיוורתי כו'. ונש\"י הם המקבלים כל האורות הנמשכי' בז\"א מלמעלה מעלה מכל הבחי' לפי שהם כלולים מהכל כו' כנ\"ל. וזהו עבדו את ה' בשמחה להיות נמשך הוי\"ה מלמעלמ\"ט. אך מ\"מ באו לפניו ברננה. שא\"א לבא אל המלך דהיינו להתכלל ממטלמ\"ע אלא בבחי' רננה ברמשא מדת לילה. וצדקתך ירננו בחי' צדק בלבד (שאין העלאת מ\"ן של התחתונים מגיע רק עד המל') אבל המשכה מלמעלמ\"ט (הוא עד\"מ שיבא המלך לכאן) הנה מאליו וממילא נמשך אור א\"ס שלמעלה מעלה והיו הדברים האלה אשר אנכי מי שאנכי מצוך כו':"],[53,"<b>ועתה<\/b> נבא לביאור וטעם הפסוק הנה כשהמל' במקומה באצי' היא נק' ציון. כי ציון מל' סימן וחותם לפי שאז היא מקבלת כל האורות שלמעל' ממש הנמשכים בז\"א בבחי' יסוד דילה נקודת ציון כו'. דהיינו בחי' תומ\"צ. כי עיקר בחי' מצוה הוא במל' שהרי על ידה בא לידי גילוי בפו\"מ כו' שביאור המצוה איך ומה היא הוא בז\"א וקיום המצוה היא במל'."],[53,"וכגון ענין קדש לי כל בכור שהביאור הוא ענין התלבשות חכמה כו'. והקיום בפו\"מ הוא ע\"י קלף הגשמי והנחה על היד והראש כו'. ולכן הוא בחי' ציון וחותם שנחקקים בה כל האורות עליונים בחי' חכמה שבקדש לי כל בכור כו' נמשך ע\"י הקיום בפו\"מ. וזהו ענין מצות צריכות כוונה שהמצוה היא הקיום בפו\"מ והכוונה הוא בחי' האורות עליונים הנמשכין כו' (וכשמקבלת כל האורות אזי היא בבחי' שמחה) אך כשיורדת לבי\"ע (שהוא בבחי' רנה וזמירות בלילה רננא ברמשא כנ\"ל) אזי נק' בת ציון שאז היא יורדת ובוקעת המסך להתלבש בע' שרים כדי להכניעם כענין ומלכותו בכל משלה. והנה עיקר ירידתה הוא בזמן הגלות גלו לאדום שכינה עמהם שאז הוא בבחי' דבור הנפרד מהקול."],[53,"ועי\"כ נפשי אויתיך בלילה בגלות ומתרפקת על דודה כו'. אבל בזמן בהמ\"ק ותרב חכמת שלמה דקיימא סיהרא באשלמותא. לא היתה המלכות יורדת בעצמה לבי\"ע לברר כו' רק הבירורין נעשו ע\"י ישראל בקרבנות שהיה העשן כו'. והקרבנות היו אשה ריח ניחוח כו' ונעשה יחוד עליון באצילות. וממילא היו מוכנעים וכפופים להקדושה כו'. ותמיד היו מיחדים השכינה למעלה כו'. ולכן לא נק' בת ציון אלא בזמן הגלות. וע\"כ בא הנביא לנחם שאעפ\"כ לע\"ל תהי' רני ושמחי (ולא עוד אלא שתתעלה בעילוי רב עד שתהיה בב' הבחינות יחד). והענין כי הנה יש אתעדל\"ע גם בלא אתעדל\"ת. למעני למעני אעשה שהרי אתעדל\"ת הוא בפסוד\"ז וק\"ש כו' ויש המשכת המצות קודם לכן כמו טלית כו'. רק שההפרש הוא שאינו יורד ונמשך מלמעלה אלא בבחי' חיצוניות. אבל בבחי' פנימיות באו לפניו. לפניו היינו פנימית ברננה דייקא."],[53,"ולע\"ל הנני בא ושכנתי בתוכך ממש. והיינו בחי' נאם ה' בחי' דבור כענין שכינה מדברת מתוך גרונו של משה. וכענין ונתתי מטר ארצכם כו'. ונתתי עשב כו' שאומר כל אדם בק\"ש ע\"י שבא לבחי' מס\"נ באחד ובכל מאדך הרי נעשה ודברי אשר שמתי בפיך כו'."],[53,"ועז\"נ האלהים יעננו בקול בקולו ש\"מ כו'. הנני בא מלמעלה למטה מאתעדל\"ע הנני אני בעצמי למעלה מעלה. ישכיל עבדי ירום ונשא וגבה מאד. דהיינו מפנימית עתיק שהיא פנימית א\"א כו' שם יהי' מעלת משיח כו'."],[53,"ועי\"ז ולציון יאמר איש ואיש יולד בה איש סתם. אשה מזרעת תחלה יולדת זכר. ואיש המשכה בוי\"ו מאיש העליון כו'. ⟦לח,ב⟧כי והוא יכוננה עליון דהיינו כי ונחה עליו רוח ה' כו'. והריחו כו'. חוטמא דפרדשקין כו'. ולפי שהוא יכוננה עליון לפיכך יהי' הכל בחינת איש. איש ואיש יולד כו'. ולכן תהי' רנה ושמחה אפי' בת ציון בחי' שנק' בת. איש מזריע תחלה יולדת בת נקבה (שבחינת בת שמקבלת מאתעדל\"ע תתעלה מאד שתקבל מאתעדל\"ע העליונה כי והוא יכוננה עליון כו' כנ\"ל. וע\"כ תהי' רני ושמחי ביחד שהן בחי' העלאה והמשכה בבחי' א' שגם בבחי' שמחה היא ההמשכה שמלמעלה תהי' רנה כו'). וזהו ענין נ\"ח שמצותה על פתח הבית מבחוץ ברה\"ר. כי הפתח הוא פתחו לי שערי צדק וצדקתך ירננו ומחוץ לפתח הוא בי\"ע והדליקו נרות בחצרות קדשך כו'. ואפי' ברה\"ר כו'. ושם ממשיכין הנ\"ח שהוא ענין יחוד אור ושמן ופתילה וגוונין שבאור פנימיים ומקיפים כו' הכל ממשיכים גם למטה מטה והיינו בחי' אתעדל\"ע בלבד:"],[54,"<b>מי כה' אלקינו המגביהי לשבת המשפילי לראות בשמים ובארץ.<\/b> הנה כתיב כי נר מצוה ותורה אור. הרי שהמשיל הכתוב את המצוה לנר וכתיב נר הוי\"ה נשמת אדם שהנשמה נמשלה לנר. וצריך להבין מהו ענין הנר של מצוה ומהו הנר של הנשמה."],[54,"והנה ענין הנר הוא שקרוי ע\"ש הפתילה כי היא עיקר הנר. אך אין נר בלא שמן. שהשמן הוא הגורם להיות הדלקת הנר בנחת שיהא שוהה ומתעכב זמן מה. ואילולי השמן הי' דולק מהר ובמרוצה. והיינו ע\"י שהשמן נמשך אחר הפתילה. והוא נשרף ונכלה באור הנאחז בפתילה עד שהוא כלה לגמרי ולא נשאר ממנו כלום מפני שהוא עולה כולו באש. ומ\"מ הפתילה היא עיקר הנר. לפי שהאור הדולק הוא ע\"י שנאחז בפתילה. ואלו היה האור נטבע בשמן היה כבה רק שהפתילה היא המחברת את האור אל השמן כשהשמן נמשך אחר הפתילה:"],[54,"<b>ולהבין<\/b> משל זה בנמשל בנר מצוה ונר הוי\"ה נשמת אדם. צריך להקדי' ענין ואהבת וגו' בכל לבבך בב' יצריך ביצ\"ט וביצה\"ר שלכאורה אינו מובן איך ישוב היצה\"ר לאהבה את הוי\"ה ע\"י האדם והלא לא ישמע אליו. אך הענין הוא כי הנה ביאור ענין יצ\"ט ויצה\"ר הוא כי נודע שיש בכל אדם ב' נפשות נפש אלהית ונה\"ב וכל נפש מתחלקת לשנים. שהם שכל ומדות."],[54,"והנה עיקר הנפש הוא השכל. כי נה\"א עיקרה היא נפש המשכלת ומתבוננת תמיד ומשגת באוא\"ס ב\"ה. ואין לה השכלה אחרת. והמדות אהוי\"ר הנולדות מן השכל והשגה זו הן הנקראות בשם יצ\"ט."],[54,"וכן עיקר נה\"ב היא המשכלת ומשגת גשמיות עוה\"ז וחומריותן שהוא זלעו\"ז לעומת נה\"א. שהשכל המלובש בענינים גשמיי' הוא הפך ממש מן השכל שבנה\"א. שהיא בחי' חכמה עליונה בחי' חכים ולא בחכמה ידיעא. למעלה מן השכל המושכל ומושג בגשמיות."],[54,"והשכל המושכל ומושג בגשמיות ע\"פ שכל אנושי הוא שקר והפך ממש מחכמת אלהות שהיא חכמת אמת והמדות הנולדות משכל הגשמי הן הנק' בשם יצה\"ר וצריך האדם לאכפייא לון שלא יתנהג ע\"פ מדות שנולדו מן השכל הגשמי. רק ואהבת את הוי\"ה אלקיך בכל לבבך. היינו בהגביר כח נה\"א המשכלת."],[54,"ומתבונן באוא\"ס בפסוק ראשון דק\"ש שמע ישראל. שמע לשון הבנה כי הוי\"ה הוא אלהינו פי' אלהינו הוא ענין ההתהוות בחי' ממכ\"ע וסוכ\"ע הוא נמשך מבחי' הוי\"ה היה הוה ויהיה שהוא אוא\"ס ב\"ה שהוא בחי' אין והתהוות היש הוא מאין ממש."],[54,"והתהוות זו נמשך תמיד יש מאין כמאמר ובטובו מחדש בכל יום תמיד כו'. והוא הוי\"ה אחד אתה הוא קודם שנבה\"ע ואתה הוא כו'. שאין התהוות העולמות פועלים בו שום שינוי ח\"ו. לפי שאינו דומה מעשה הקב\"ה ⟦לח,ג⟧למעשה בו\"ד. שמעשה אנוש הנה כח הפועל ממש הוא בנפעל. כמו עד\"מ כשעושה דבר פונה א\"ע ומעמיק שכלו בדבר שהוא עושה."],[54,"וע\"כ הדבר שעושה פועל בו שינוי בכח שכלו. אבל התהוות העולמות מאוא\"ס ב\"ה אין פועלים בו שום שינוי ח\"ו. וה' אחד כמו קודם שנבה\"ע. לפי שבשכמל\"ו שכל התהוות העולמות וקיומם וחיותן אינן אלא מבחי' מלכותו ית' שבמה שהוא מלך עליהם מחיה ומהוה אותם דהיינו בחי' שמו ית' בלבד."],[54,"ושם שייך כח הפועל בדבר ה' שמים נעשו כי דבר מלך שלטון כתיב מלכותך מלכות כ\"ע. יחיד חי העולמים מלך כנודע. וכאשר יעמיק האדם שכלו ומחשבתו בזה בעומק בינתו ובעומקא דלבא. אזי תבטל הנפש החיונית מהשכלתה בגשמיות בתגבורת הנפש האלהית המשכלת ומתבוננת בגדולת א\"ס ב\"ה להוליד מרוח בינתה והתבוננותה אהבה עזה כרשפי אש לדבקה בו ית' בדביקה וחשיקה וחפיצה בהתלהבות עצומה עד כלות הנפש כמ\"ש נכספה וגם כלתה נפשי וגו'."],[54,"ועמך לא חפצתי בארץ כלה שארי ולבבי וגו'. ואזי תהיה החכמה שבנפש החיונית כשמן הנמשך אחר הפתילה שהיא נר ה' נשמת אדם שהנשמה היא הפתילה המחברת אור האהבה עזה ורשפי אש להאיר בנה\"ב עד שתכלה ותכסוף ג\"כ לדבקה בו בדביקה חשיקה כו'. ולהיות ואהבת וגו' בכל לבבך וגדול יהי' כח כלות הנפש הבהמית ביתר שאת בבחי' שמן הנכלה ועולה עד שנעשה ממנו כולו אש של אור הנר ע\"י בחי' צעק לבם והוא התהפכות בחי' האש שבה. ורשפי אש אהבה עזה כו'. וזהו נר של הנשמה שהיא מהתבוננות נפש האלהית עצמה:"],[54,"<b>וענין<\/b> נר של המצוה היא שהמצוה יש לה סגולה פרטית להעלות את נה\"ב ולקשרה באוא\"ס ב\"ה כמא' אק\"ב בקדש העליון שהוא למעלה מן ההשתלשלות. כי המצות הם לבושין ונק' לבוש מלכות שהם בחי' מקיפים שמקיפים ומלבישים את הנפש מראשה ועד רגלה להיות צרורה בצרור החיים את ה' ממש שעי\"ז מעלה את הנפש כמו האדם כשהוא לבוש יכולין להמשיך אותו ע\"י לבושו."],[54,"וכן כצרור אבן במרגמה. שע\"י שצרור בחרט זורקין אותו למעלה יותר. הכלל שכל בחי' מקיף הוא העלאה למעלה. ולכן לובשין טלית ותפלין קודם התפלה להמשיך בחי' מקיף למעלה להעלות את נה\"ב בתפלה כנודע שאין התחתון עולה למעלה עד שיורדת תחלה הארה מלמעלה. והתפלה היא עליית נה\"ב. ולכן התפלה היא נוסחא אחת בכל יום כל ימי חייו של אדם הקצובים לו ימי שנותינו בהם שבעים שנה הם כפי נצוצות נפש הבהמיית שצריכין להעלות (משא\"כ נפש האלהית היא נצחית) וכל יום נעשה בחי' חדשה. וצריך להעלות גם אותו נצוץ שמתחדש והכל היא העלאה אחת (משא\"כ לימוד התורה צריך דוקא ללמוד בכל יום דבר חדש) ולכן כל המצות נקראות בשם צדקה כי צדקה תרומם גוי שע\"י הצדקה וחסד שעושין למטה להחיות רוח שפלים ועני חשוב כמת. כן ויותר מכן לאין קץ נמשך רוח חיים מלמעלה מחיי החיים ב\"ה להחיות מתים ממש בבחי' ימין מקרבת וימינו תחבקני ממש באור המקיף שמלמעלה לרומם ולהעלות את הנפש למעלה מעלה באוא\"ס ב\"ה ממש וזהו ענין נר מצוה:"],[54,"<b>אך<\/b> התורה אור הוא המשכת אוא\"ס ב\"ה מלמעלמ\"ט. והיא אור וגילוי אוא\"ס ב\"ה ממש שלמעלה מעלה מהשתלשלות שירידת והדרגת סדר השתלשלות היא בחי' העלם והתלבשות אוא\"ס ב\"ה להיות התהוות מהות אחר מהות באופנים ומינים שונים."],[54,"וכמ\"ש ישת חשך סתרו שהוא חשך והעלם ולא אור וגילוי. ועל התורה נאמר מגלה עמקות מני חשך. וממעמקים קראתיך הוי\"ה. וזהו תכלית בריאת האדם להמשיך על נפשו אוא\"ס ב\"ה שלמעלה מן ההשתלשלות. להיות ⟦לח,ד⟧אור א\"ס ב\"ה שורה למטה כמו למעלה כמ\"ש אני ראשון ואני אחרון ומבלעדי אין אלהים. כלומר כשם שאני ראשון קודם שנבה\"ע."],[54,"ואחרון לאחר שנברא העולם. כן מבלעדי דהיינו באמצעות בשעת בריאת העולם יהי' אור א\"ס ב\"ה נמשך למטה שיהי' בטול העולם במציאות כמו קודם שנברא ואחר שנברא והיינו ע\"י התורה כי אורייתא מחכמה נפקת."],[54,"וכמ\"ש לכבודי בראתיו. כבו\"ד בגימטריא ל\"ב הם ל\"ב נתיבות חכמה. בראתיו בחי' תלמוד. יצרתיו בחי' משנה. ועשיתיו בחי' מקרא. שכולם הם בבחי' חכמה ואור א\"ס ב\"ה שורה ומתגלה בחכמה שאין שם שום הסתר פנים."],[54,"ושם הוא בחי' אני ה' לא שניתי כמו קודם שנברא העולם. ולכן רב יהודא דכולי תנויי' בנזיקין הוה לזכות את הזכאי. ולחייב את החייב. להפריד ביניהם. בכדי להפריד החיצונים מהקדושה ויתפרדו כל פועלי און כו'. ולכן היה פטור מן התפלה לפי שהיתה תורתו אומנתו כר' שמעון בן יוחאי וחביריו. והיינו מפני שרב יהודא היה אדם גדול מאד עד שאמר עליו שמואל אין זה ילוד אשה דאימתא דמאריה עליה שהי' בחינת ביטול לאוא\"ס ב\"ה שהמשיך עליו בק\"ש. (כי מן הק\"ש לא היה פטור ואפילו ר' שמעון בן יוחאי וחביריו אלא מן התפלה) והיתה תורתו ג\"כ בבחי' בטול ממש בבחי' ואשים דברי בפיך. ודברי אשר שמתי בפיך וכמארז\"ל מתניתין מלכתא. בחי' מלך שמצוה וגוזר שיהי' הפסק כך כי מלך במשפט יעמיד ארץ לזכות את הזכאי כו'. שיש ב' בחי'. בחי' עבד שלומד כדי שידע רצון המלך."],[54,"ובחי' מלך שבעת לימודו הוא הגוזר ומצוה לעצמו כו' וז\"ש ויהי בישרון מלך לפי ששכינה היתה מדברת מתוך גרונו של משה. וכך ר' שמעון בן יוחאי וחביריו ורב יהודא לפי מדרגתו. שכפי ערך בטול נפשו לאור א\"ס ב\"ה. ככה היתה המשכת אור א\"ס ב\"ה בתורתם ועבודתם. והמשנה המדברת בפיהם היא דבר ה' ממש. ועי\"ז נמשך בטול העולם במציאות למטה כמו למעלה:"],[54,"<b>והנה<\/b> אור התורה הזה נאחז ומתחבר במצוה כי כל התורה שלפנינו הן תושב\"כ ושבע\"פ עיקרן ויסודותן היא במצות שע\"ז נאמר ותמלא כדה ותעל. כ\"ד ספרין דאורייתא כו' שהן בחי' כד שנשאב מים העליון חכמה עלאה של א\"ס ב\"ה שהוא עד אין קץ ותכלית וע\"ז נאמר והיו הדברים האלה אשר אנכי מצוך. אנכי דייקא."],[54,"והמצוה היא הפתילה שמתלבשת בנפש השכלית והחיונית להעלות' ולקשרה באור התורה שהיא בחי' חכים ולא בחכמה ידיעא הפך שכל אנושי ובה שורה א\"ס ב\"ה כמ\"ש ה' בחכמה יסד ארץ. אך צריך להקדים התבוננות של נפש האלקית היא נר ה' נשמת אדם כדי להיות ואהבת וגו' בכל לבבך כי רוח אייתי רוח ואמשיך רוח וכמ\"ש אם ישים אליו לבו וגו' עד שתהיה חכמה שבנפש החיונית בחי' השמן הנמשך אחר הפתילה של מצוה להתכלל ממש באור התורה שתתהפך ממש מהפוך אל הפוך משכל אנושי המושג לשכל חכמת התורה חכמת אלהית בחי' חכים ולא בחכמה ידיעא כו' שלכן נתלבשה בענינים גשמיים וכל ענינים גשמיים כלולים בה כמו כל צמח האדמה ופרי העץ בסדר זרעים. וכל בעלי חיים בסדר קדשים. כדי לברר ולהפך הכל בקדושה. וימלא כבוד ה' את כל הארץ הלזו הגשמית כו':"],[54,"<b>וזהו<\/b> המגביהי לשבת. פי' המגביה י' הוא י' שבה' שהדל\"ת הוא בחי' דלית. דלית ליה מגרמיה כלום נעשה ה' ע\"י היו\"ד שבתוכה והיינו בחי' המצוה שמצדק נעשה צדקה. וצדקה תרומם גוי ע\"י שמגביה את בחי' היו\"ד שבה' למעלה מעלה באוא\"ס ב\"ה ממש. לשבת להיות בחי' מכון לשבתך דהיינו שתהא שם השראת אוא\"ס ב\"ה ממש שהיא בחי' ישיבה דהיינו בחי' ירידה והשפלה אצלו כביכול ⟦לט,א⟧וכמ\"ש וישב ה' מלך לעולם. כי להיות מלך לעולם היא בחי' ישיבה והשפלה כי על מי ימלוך כו'."],[54,"וזו היא העלאה שע\"י המצות ממטה למעלה. אבל התורה אור היא המשכה מלמעלה למטה המשפילי לראות בשמים תושב\"כ. ובארץ תושבע\"פ. ושם הוא לראות בחי' ראיה והתגלות אוא\"ס ב\"ה למטה כמו למעלה. ולא בחי' שמע ישראל דהיינו התבוננות שבנפש האלהית שהיא בחי' שמיעה בלבד אלא כמ\"ש כי עין בעין יראו וגו':"],[55,"ביאור על הנ\"ל"],[55,"<b>להבין<\/b> ביאור הדברים ע\"פ המגביהי לשבת כו'. הנה צריך להקדים שני הקדמות. הא' מ\"ש בפרדס הטעם שמכל הדברים נוכל להוציא שמן. כמו שעושין בתקון הרפואות. הוא לפי שכולם בחכמה עשית ונמצא בכל הדברים מלובש בחינת חכמה זהו בחינת השמן שהוא בחי' חכמה כמ\"ש בזוהר דיין הוא בינה ושמן חכמה. ולכן כתיב אשה חכמה מתקוע כי תקוע אלפא לשמן."],[55,"והנה שמן הטוב ושמן המשחה הוא בחכמה דקדושה שבע\"ס עליונות. וע\"ז נאמר כשמן הטוב כו' זקן אהרן כו' וכמ\"ש בזוהר ויקרא ופ' אמור. אבל שאר כל השמנים הם מנוגה ובנוגה הוא בחי' חכמה שבשכל אנושי."],[55,"והקדמה השנית הוא פי' מ\"ש ותורה אור. כי הנה פי' אוא\"ס הוא מל' דא\"ס שבה כל הצמצום הנז' בתחלת ספר עה\"ח. שנעשה בחי' צמצום בהאור להיות נעשה מקום פנוי וחלל שהכל הוא באוא\"ס בהאור דוקא."],[55,"ולא במהו\"ע ממש ח\"ו. והכוונה בצמצום זה הוא כדי שאח\"כ ע\"י עבודת האדם בעוה\"ז שיתהוה ע\"י צמצום זה יומשך להיות גלוי מל' דא\"ס כמו קודם שנברא. פי' כמו שהאור הוא קודם הצמצום כך יהיה ממש הגלוי למטה שלא יסתיר הצמצום כלל."],[55,"וכמ\"ש אני ראשון ואני אחרון ומבלעדי וגו'. פי' אני ראשון כמו שהיה קודם הצמצום ואני אחרון היינו כמ\"ש ונשגב ה' לבדו כו'. ומבלעדי היינו באמצעות שנעשה בחי' הצמצום וההסתר יהיה ג\"כ אין לנו מלך אלא אתה שיהיה גלוי הבטול שלא יהיה הסתר והעלם. והמשכה זו היא ע\"י התורה. וזהו ותורה אור שממשיך בחי' גילוי אוא\"ס כמו קודם הצמצום גם לאחר הצמצום. (וזהו מתניתין מלכתא המשכת גלוי מלכות דא\"ס האור שלמעלה מהצמצום). וזהו ענין רב יהודא כולי תנויי' בנזיקין הוה והי' פטור מן התפלה כו' לפי שההשתלשלות הם בחי' העלם והסתר כמ\"ש ישת חשך סתרו דזה קאי על התהוות בחי' הכתר כי החכמ' נק' אור שהוא בחי' גלוי כמ\"ש ראשית חכמ' ראשית הגלוי והכתר שלמעלה מן החכמה ואינו מאיר ומתגלה נק' אצלנו בשם חשך לפי שאינו מושג. וכמ\"ש בזהר פ' בראשית (דל\"ב ע\"א) (ועמ\"ש ע\"פ שחורה אני כו' בענין שהתורה ניתנה אש שחורה ע\"ג אש לבנה). וגם לכן נק' הכתר חשך שהוא העלם לאוא\"ס והחכמה היא העלם הכתר שאינו מאיר כ\"א ע\"י החכמה נמצא החכמה מעלים ומסתיר על הכתר. ולכן נק' קו המדה בוצינא דקרדוניתא מלשון חטי קרדנייתא שהוא ענין קדרות ושחרות לפי שצ\"ל מדה וגבול עד כאן בחי' חכמה."],[55,"וע\"כ בחי' בינה כו'. שכ\"ז הוא חשך ולא אור. אבל אור הוא גלוי הבטול להיות אוא\"ס למטה כמו למעלה מהצמצום כו'. וכמו שהוא קמיה ית' שהצמצום אינו אלא לגבי העולמות כנודע. והיינו דוקא ע\"י התורה מגלה עמקות מני חשך ממעמקים קראתיך הוי\"ה כי התורה היא בחי' חכמה שנמשכה ממלכות דא\"ס (שהיא בחי' מו\"ס דעתיקא שבחי' כתר ועתיק נק' מל' דא\"ס. וכנודע שמבחי' מל' דא\"ק נעשה כתר לאצי') ושם שורה אור א\"ס ב\"ה בבחי' לא שניתי ממש שאין שם העלם והסתר כלל. וכמ\"ש יהי אור זו חכמה והכתר נק' אויר. ורב יהודה שהיה אדם גדול מאד היה יכול להמשיך בטול עליון ע\"י שהיה בטל בעצמו בק\"ש כי מן הק\"ש לא היה פטור רק מן התפלה."],[55,"ורצה להמשיך גם בנזיקין מקום הקליפות שהם ארבעה אבות נזיקין שיהיה בלע המות לנצח וכמו שיהי' לע\"ל בעת תח\"ה שיחיו העצמות ויקרם עליהם עור ובשר כמ\"ש גבי עצמות דיחזקאל שיהיה גשמיות ממש ואעפ\"כ יהיו נהנין מזיו השכינה בלי אכילה ושתיה לפי שיומשך בטול עליון גם בגשמיות ממש וכמארז\"ל עתידים צדיקים שיאמרו לפניהם קדוש שיהא קודש שורה למטה."],[55,"ועל דרך זה היתה תורתו של רב יהודא ושל רבי שמעון בן יוחאי שהיתה תורתם אומנתם שהיתה תורתם בבחינת בטול ממש לאור אין סוף ולא הם המדברים ד\"ת אלא דבר ה' בפיהם כו'."],[55,"וזהו ענין מתניתין מלכתא כמלך שמצוה כו'. שיש בחי' עבד שלומד כדי שידע רצון וגזירת המלך. ויש בחינת מלך שהוא הגוזר עצמו כו'. ולכן במרע\"ה נאמר ויהי בישרון מלך כו'. נמצא היוצא מהקדמה זו השניה דפי' ותורה אור הוא שע\"י עסק התורה בבטול ממשיכים בחינת אוא\"ס ממש שלמעלה מהצמצום שיהי' מתגלה למט' בעשי' כמו שהיה רב יהודה תנויי' בנזיקין להפך חשוכא דוקא לנהור' [ועמ\"ש בפ' בראשית ע\"פ צאנה וראנה."],[55,"ועפ\"ז יובן ענין הנר והאור דרך כלל. כי הנה הפתילה זהו חוט ועליו נמשך האור ובחי' החוט רומז לבחי' צמצום האור שע\"י הצמצום נמשך רק קו וחוט לבד ואח\"כ נמשך קו זה להאיר במדה ומשקל ונק' קו המדה ויש בזה כמה בחי' בענין הקו המדה ונק' ג\"כ פתיל (וכמ\"ש בזוהר פקודי דף רל\"ג ע\"א) ע\"פ ופתיל פשתים בידו וקנה המדה כו'. ולזמנין קנה המדה ולזמנין קו המדה ועל דא פתיל וקנה כו' דקנה המדה זהו ענין המדידה דעלמא דאתכסייא שנק' ים שמדה זו הוא ע\"י הקנה שגדל אצל המים."],[55,"ומדידו דעלמא דאתגליא הנק' יבשה הוא ע\"י פתיל כו'. ועכ\"פ בחי' הפתילה זהו בחי' קו המדה. אך האור הנתלה בפתילה זהו בחי' תורה אור שהוא המשכת אוא\"ס שלמעלה מהצמצום והמדה וכמ\"ש ארוכה מארץ מדה וכמ\"ש במ\"א שזהו ענין הברכות דיעקב ע\"י יצחק דוקא כי יצחק הוא בחי' גבור' דע\"י שרש ומקור קו המדה לכן נתברך יעקב על ידו. שהברכה היא מטל השמים זו מקרא ומשמני הארץ זו משנה. שעי\"ז יומשך תוספת אור יותר לאין שיעור על עיקר האור שע\"פ המדה כו'. ועיקר אחיזת האור בפתילה הוא ע\"י כליון השמן שהוא בירור חכמה דק\"נ שכל אנושי כנ\"ל בהקדמה ראשונה. והיינו כשהוא נכלל באור שבטל לגמרי לבחי' ותורה אור]:"],[55,"<b>ועתה<\/b> נבא לביאור הענין. לבאר ענין שני הבחי' נר. האחד מ\"ש נר הוי\"ה נשמת אדם שהנשמה לבדה היא בחי' נר. ובנר יש השלשה בחי' הנ\"ל. אור ופתילה ושמן. א\"כ יש כ\"ז בהנשמה עצמה. הנר הב' הוא כמ\"ש כי נר מצוה ותורה אור. ויש בזה ג\"כ ג' בחינות הנ\"ל. והענין כי הנה נר הוי\"ה נשמת אדם היא נה\"א (ולא הנה\"ב שעדיין צריכה להתברר ואינה נק' בשם נר הוי\"ה דהא לא כתיב נר אלקים) שהיא א\"צ תקון לעצמה והיא הפתילה שממשכת האור הוא הבטול העליון אוא\"ס מל' דא\"ס ששם הוא התחלת הקו וחוט המתלבש בע\"ס דאצי' מקור ושרש נה\"א. ונקראת הנה\"א ג\"כ פתילה יעקב חבל נחלתו. על כן בכח הנה\"א להמשיך ⟦לט,ג⟧האור והבטול עד שהשמן הוא חכמה שבשכל אנושי שבנפש השכלית דנוגה נמשך אחר הפתילה."],[55,"והנה השמן הנמשך אחר הפתילה הוא השורף ונכלה הכל עד שנעשה ממנו אש גמור שהוא הגורם הדלקת האש הרבה לפי שהוא הוא הדולק עד שנתהפך ממש להיות כאש משא\"כ הפתילה. והכח הזה בשמן דק\"נ יותר מבנה\"א הפתילה הוא לפי שעיקרו מעולם התהו שהוא למעלה מעלה (כי בתהו היה רבוי האור שזהו יותר מבחי' המדה דקו המדה דתקון) אלא לפי שהיו זת\"ז נשברו. דהיינו לפי שלא הי' התכללות וההתכללות הוא התקון שנמשך דרך קוים כמ\"ש באילן. וזהו ענין נשמת אדם א' דם כמו שהדם סובב והולך בכל האברים נעוץ תחלתן בסופן עד שלכאב הראש מקיז דם ברגל כו'. כך הוא המשכת הנשמה נפש אלקית."],[55,"והכל הוא רק כדי לברר הנפש השכלית שתתהפך ממש באש שלמעלה שיהי' מאיר בה אור א\"ס ממש כמו למעלה כי מתהו ממש נעשה תקון שמעקודים נקודים נעשה ברודים. וזאת היא בחי' נר הנשמה שהיא נפש אלקית שהיא הפתילה שעיקר הנר היא הפתילה והשמן הוא בירור הנפש השכלית. ומזה נעשה אור הוא הבטול העליון כו' כנ\"ל."],[55,"והנה הטעם שנק' הבטול הזה בשם אור. וגם מה שנמשך ע\"י כליון השמן דוקא שהוא הוא שנעשה אש ואור גמור. משא\"כ הפתילה. וכבר מילתא אמורה שהוא מפני ששרשה מעולם התהו. אך ביאור הענין הוא ע\"פ המבואר בדוכתי טובא. איך שיש ב' בחי' אהבה ויראה. האחת האהבה והיראה שהיא מוגבלת לפי שיעור השגת הנפש כו'."],[55,"והב' הוא האה\"ר ויראה עצומה למעלה מכדי אשר תוכל הנפש שאת בהשגתה כו'. והיא הבאה מבחי' ההתבוננות בסוכ\"ע המקיף לכל העולמות בשוה. ובחי' הראשונה נק' בכל נפשך. ועד\"ז הי' אהוי\"ר של הנשמה בג\"ע לפ\"ע ההשגה."],[55,"והשנית נק' בכל מאדך. כי מאד פי' בלי גבול. היינו שאין כלי הלב מכיל האהבה ויראה העצומ' עד שנעשה בחי' אור מקיף. וזהו בחי' תשובה בחילא יתיר. פי' יתיר על הכלי. ולזה היה תכלית ירידת אור הנשמה מג\"ע לעוה\"ז בכדי שתבא לבחי' בכל מאדך שהתשובה אינה רק בעוה\"ז כי ע\"י אהוי\"ר זו שבלי גבול עי\"ז ממשיך אוא\"ס הבלי גבול שלמעלה מהצמצום משא\"כ ג\"ע נק' זיו השכינה ע\"י צמצום. ביו\"ד נברא עוה\"ב כו'. ולכן יפה שעה א' בתשובה כו'."],[55,"והנה בחי' אה\"ר זו דמאדך נק' או\"ח. והטעם שנק' בשם אור הוא כי הנה אנו רואים ההפרש בין אש ואור למים אשר מן האש יוכלו להדליק זמ\"ז עד אין קץ וגבול משא\"כ במים שיש גבול להשפעתם שאפי' יהיו מים הרבה יכלו או יחסרו כשישתו מהן עם רב. משא\"כ באש שאפי' מאור נר אחד יוכלו להדליק נר מנר עד שלא יהיה כלה כלל לעולם ונמצא שאע\"פ שהאש הדולק מצד עצם הרי הוא בע\"ג כמו המים אבל מ\"מ יש בו בחי' כח בלתי מוגבל מה שיוכלו להמשיכו מנר לנר בלי שיכלה לעולם משא\"כ במים שהם מוגבלים ולכן נמשל הקב\"ה לאש דוקא כמ\"ש אש אוכלה הוא כי אני הוי\"ה לא שניתי בין קודם שנבה\"ע וכו' לפי שההמשכה היא רק הארה בעלמא שאינו נוגע למהו\"ע."],[55,"וזה כמשל האש שהמדליק נר מנר אינו מחסר בנר הראשון ולכן אין לו קץ. משא\"כ במים שנעשה חסרון כו' ע\"כ יהיו כלים לגמרי ברבוי המשכות משא\"כ האש אינו כלה ע\"י רבוי הדלקות ממנו לפי שאין נעשה שום חסרון בו כלל רק ע\"ד הארה:"],[55,"<b>והנה<\/b> ע\"פ משל זה באש הגשמי דאע\"פ שהוא בע\"ג ממש מ\"מ יהיה ממנו המשכה בלי גבול כמו\"כ יובן הנמשל בענין אהבה דבכל מאדך. דפי' מאד היינו בלי גבול למעלה מהגבלת כלי ⟦לט,ד⟧הנפש."],[55,"והנה ודאי מובן לכל דאין ר\"ל שהיא אהוי\"ר שבלי גבול וקץ ממש כי איך שייך זה שבאדם יהיה אהוי\"ר שבלי גבול ממש. אלא הכוונה שהיא יותר מהגבלת הכלי השכל ומדות שבאדם. שאין כח בכלים אלו להכיל ולהגביל אהוי\"ר זו בתוכן כ\"א היא יתיר יותר מכלים אלו ולכן נק' בכל מאדך מאד שלך פי' לגבי כלי שלך נק' אהבה רבה זו מאד ובלי גבול אבל באמת היא בגבול."],[55,"ואעפ\"כ כיון שלגבי האדם היא בחי' בכל מאדך ובחי' בחילא יתיר לכן עי\"ז ממשיך ממש אוא\"ס ב\"ה שלמעלה מהצמצום שהוא הבלי גבול אמיתי נמצא עם היות אה\"ר זו מצד עצם בעלת גבול מ\"מ להיותה יותר מגבול וכלי של הנפש ע\"כ פועלת המשכה מבחי' בלי גבול ממש דהיינו אוא\"ס ממש ולכן נק' אה\"ר זו בשם אור שהוא ממש כמשל האור והאש אע\"פ שהוא בע\"ג יש ממנו המשכה בלי גבול משא\"כ במים וכו'. ועד\"ז יובן מעלת אהבת רשפי אש בכל מאדך על בחי' אהבה הנמשכת כמים שהוא בחי' בכל נפשך."],[55,"והנה אה\"ר זו נתהוה בהנשמה דוקא ע\"י התלבשות' בגוף ונה\"ב שאז תבא לבחי' תשובה בחילא יתיר משא\"כ אהבת הנה\"א קודם התלבשותה בגוף היה בבחי' גבול וכלי כפי השגת הנפש כו'. ולכן נק' הנה\"א פתילה שהפתיל' זהו דבר מוגבל בעצם וכמו פתיל וקו המדה אבל ע\"י התלבשותה בנה\"ב ואז השמן דבירור הנפש השכלית שמנוגה ששרשה מעולם התהו הוא נמשך אחר הפתילה דנה\"א עי\"ז דוקא יתהפך השמן לאור שהוא בחי' אה\"ר דבכל מאדך ובטול עליון יותר מהכלי וכמו רב יהודה דאימתא דמאריה עליה. לכן נק' אה\"ר זו בשם או\"ח שהוא אור הנמשך מהבירור דק\"נ ששרשן מעקודי' נקודים כנ\"ל אלא שעי\"ז נמשך אח\"כ מלמעלה למטה אוא\"ס ממש והוא בחי' ותורה אור."],[55,"וכ\"ז הוא בחי' נר הנשמה אך אין נשמה בלא מצוה כי לא ע\"ה חסיד ולא בור ירא חטא. וגם מצוה בלא נשמה אינה כלום כי כל האומר אין לי אלא תורה אפילו תורה אין לו."],[55,"ולכן צריך להיות גם שניהם. והענין כי נר מצוה שהמצוה היא נר והיינו פתילה. והענין כי הדברים שנעשה בהן המצוה הן ג\"כ מעולם התהו. אך המצוה היא ג\"כ בחי' מקיף שנמשך ע\"י קיום המצוה מקיף עליון ולכן המצות הן לבושים ובגדי מלכות להיות עי\"ז הנשמה צרורה בצרור החיים שמלבשת ומקפת את הנשמה להעלותה כי כל דבר שצריך לעלות מקיפין אותו סביב."],[55,"וע\"י זה המקיף המקיפו הוא עולה כמו שזורקין את האבן ע\"י קירטא כו' מה שלא היה עולה כלל מעצמו ולהפך בעבירה ג\"כ מלפפתו כו' ולכן לובשים הטלית ותפילין קודם התפלה כנודע שכל דבר שצריך להעלותו מלמטה יורד מתחלה אור העליון והוא אור המקיף שהוא המעלה כנ\"ל. ובזה תתהפך הנפש השכלית באור שלמעלה בתפלה ולכן מתפללין בכל יום נוסח אחד (משא\"כ תורה היא צריכה דוקא התחדשות ע' זוהר בראשית בהקדמה )(די\"ב ע\"ב) ולאפשא לה בכל יומא שבכל יום מעלה ניצוץ מנפש החיוני' כי כל ימי שנותינו בהם שבעים שנה הם כ\"כ נצוצות מנפש החיונית שצריך לברר משא\"כ נה\"א היא נצחית. נמצא המצוה היא בחי' פתילה שבה וע\"י נכלה השמן באור כך ע\"י המצוה היא עליית נפש השכלי' דק\"נ וגם קלף התפלין דק\"נ ומעות הצדקה ליכלל באוא\"ס ב\"ה כי שרש המצות הם במל' דאצי' כי תורה היא בחי' ז\"א."],[55,"ומצות הן במל' מצות המלך. אך לפי שנעוץ סופן בתחלתן הרי המל' דאצי' עולה עד מל' דא\"ס ממש. ולכן עי\"ז עולה נפש השכלית באוא\"ס ממש כנודע שאחר הבירור משם ב\"ן נעשה שם ס\"ג כו':"],[55,"⟦מ,א⟧<b>וזהו<\/b> המגביהי דהיו\"ד אחר הה\"א הוא יתיר אלא דר\"ל שעלייה זו דמל' דאצי' הנק' ה' שיהיה עולה כ\"כ למעלה במל' דא\"ס הוא ע\"י היו\"ד והוא היו\"ד שבתוך הה\"א. כי מל' דאצי' היא בחי' דל\"ת דלית לה מגרמה כלום ובהמשכת המצוה נעשה בתוכה יו\"ד ונעשית עי\"ז בחי' ה' וע\"י היו\"ד שבתוכה היא עולה למעלה באוא\"ס מל' דא\"ס וזהו פי' המגביהי שעליית הה' היא מל' דאצי' במל' דא\"ס הוא ע\"י היו\"ד שבתוך הה' שהוא הנמשך ע\"י קיום המצוה. ובו וע\"י היא העלייה הזאת [וביאור זה עפמ\"ש בזוהר פ' ויחי (דרל\"ב סע\"ב) בפי' יהי שם כו' מאי שנא דקאמר יהי אלא יהי רזא דאמשכותא מההוא אתר עילאה דאיהו סתים דקאמרן דאיהו י\"ה עד רזא דברית דאיהו יו\"ד תתאה כגוונא דיו\"ד עלאה שירותא כסופא ובגין כך יהי רזא דאמשכותא מטמירא דכל טמירין עד דרגא תתאה ובמלה דא אתקיים כל עובדא דבראשית כד\"א יהי רקיע כו' עכ\"ל. וכ\"ה בזוהר בראשית (די\"ו ע\"ב) והפי' הוא כי י\"ה הם חו\"ב שהחכמה נק' יו\"ד שהיא בחי' נקודה והיינו לפי כי ראשית חכמה דהיינו ראשית הגילוי מא\"ס ב\"ה וראשית הגילוי א\"א להיות רק בחי' נקודה כדי שיוכלו לסבול ולהכיל כמו המעיין בתחלת יציאתו מהמקור הוא קטן רק אח\"כ בהתרחקו מהמקור מתרחב ונעשה נהר. וזהו ה' ראשונה שהיא בחי' רחובות הנהר אבל החכמה שהיא קרובה יותר לא\"ס והיא בחי' מעיין הוא רק נקודה. והיינו ג\"כ בחי' בטול."],[55,"והנה כשצ\"ל אח\"כ המשכה לבחי' מל' דאצי' שהיא עלמא דאתגלייא מקור דבי\"ע והיא בחי' שם ה' שם דוקא שהוא הגלוי לזולתו הנה המשכה זו ע\"י יסוד ז\"א והוא ג\"כ בחי' יו\"ד."],[55,"וזהו ענין יו\"ד תתאה רזא דברית. וזהו יהי שם ה' מבורך כו' שלהיות הגלוי בבחי' מל' הנק' שם הוא ע\"י יהי חו\"ב ביסוד. וע\"פ כהאריז\"ל הוא כי יסוד אבא מסתיים ביסוד ז\"א. נמצא בחי' יו\"ד עלאה שהוא אבא ממש מאיר ביסוד ז\"א. ולכן נק' יסוד ז\"א ג\"כ יו\"ד. וזהו ג\"כ ענין היו\"ד שנתוסף בפינחס בן אלעזר הכהן עבור שקינא על פגם הברית כמ\"ש בזוהר ר\"פ פנחס (דרי\"ג ע\"ב ודרט\"ו ע\"ב ורל\"ו ב') (ומזה ראייה דלא כפי' המק\"מ פ' ויחי )(דרל\"ב) בפי' יהי ע\"ש וע\"ש בהרמ\"ז שהוא יו\"ד של מילוי ה\"י אחרונה דשם ע\"ב שהוא בחי' יסוד אבא כו'. וע' באד\"ר (דקמ\"ב):"],[55,"<b>וביאור<\/b> הדברים הוא כמו שאנו רואים שהראיה מתפשטת ונמשכת למטה יותר מן חוש השמיעה. שחוש השמיעה אינו מתפשט רק עד בחי' קול ודבור ששומע קול ודבור של חבירו אבל לא יתפוס בחוש השמיעה את העשייה גשמית. משא\"כ בראי' תופס ומשיג העשייה גשמי'."],[55,"והיינו דלפי שהראיה שרשה מבחי' חכמה כמו שנק' החכמים עיני העדה. שהיא למעלה מבחי' הבינה שמשם שרש השמיעה ע\"כ נשפלת למטה יותר. משא\"כ בכח השמיעה הנמשך מבינה להיות נשפל כ\"כ למטה. שכל הגבוה יותר יכול להשפיל א\"ע למטה יותר ולכן יסוד אימא מסתיים בחזה ואינו נמשך בנה\"י דז\"א. אבל יסוד אבא נמשך עד יסוד ז\"א כי נה\"י דז\"א זהו בחי' עשיי' שבאצי' והמשכה זו א\"א להיות כ\"א ע\"י יסוד אבא בחי' ראיה וכו'."],[55,"וזהו ענין יהי שם כו' שלהיות ההשפעה בבחי' מל' הנק' שם ונק' ג\"כ עשיי' שבאצי' הוא ג\"כ ע\"י יו\"ד דוקא שהוא בחי' יסוד ז\"א שבו מאיר יסוד אבא. וזהו פי' יהי י\"ה הם חו\"ב והיו\"ד השני זהו צדיק יסוד עולם. ועיין עוד בזוהר ח\"ג (דרל\"ו ע\"ב) מענין בחי' זו דיו\"ד זה:"],[55,"<b>והנה<\/b> כשהמל' מקבלת גילוי זה דבחי' יו\"ד. אז נעשית מדל\"ת ⟦מ,ב⟧ה'. ולכן לפ\"ז מובן ג\"כ פי' המגביהי שעליית המל' במל' דא\"ס הוא ג\"כ ע\"י יו\"ד שבתוך הה\"א שהוא מה שנמשך לה הארה מאוא\"ס וכמבו\"ל שכל עלייה הוא ע\"י המשכה תחלה מלמעלה והנה בחי' יו\"ד זה שבתוך ה' שנמשך ע\"י המצוה זהו בחי' פתילה הנמשך לתוך הנר כמ\"ש בזוהר פ' פנחס (דרי\"ט ע\"א) ובמק\"מ כיון דאתאחד פתילה כו' וע\"י המשכה זו נעשה כח עליי' המל' לשרשה. וע' בזהר ר\"פ צו ע\"פ זאת תורת העולה כו'. וזהו פי' המגביהי שהמצוה היא בחי' פתילה ונר המעלה נפש השכלית כמו שלמעלה עליית שם ב\"ן ע\"י היו\"ד דע\"ב הנמשך ע\"י המצוה כנ\"ל."],[55,"ועמ\"ש בפ' שלח ע\"פ והיה לכם לציצית בענין אש יו\"ד ואש ה\"א]. וענין לשבת פי' שעלייה זו של המל' דאצי' במל' דא\"ס הוא כדי להמשיך אור וחיות להיות התהוות בחי' מל' בבחי' ישיבה וישב ה' מלך לעולם. כי ישיבה ומלכות הכל בחי' אחת כי אין ישיבה בעזרה אלא למלכות בית דוד בלבד."],[55,"וכן ארז\"ל באשה קראו מושב כי ישיבה היא ירידה והשפלה בבחי' אחוריים. וכן תפלה ש\"י שהיא מל' היא מיושב. והיו\"ד שברצועת תפלה ש\"י זהו ענין יו\"ד הנ\"ל. ועוי\"ל פי' המגביהי לשבת כי המלך עומד על הלוח ואגוסטוס יושב."],[55,"ופי' אגוסטוס היינו מלך המלכים. והיינו כשהמל' מקבלת ממל' דא\"ס בחי' ממ\"ה ע\"ז ארז\"ל המשל אגוסטוס יושב כו'. וזהו המגביהי דוקא לשבת שע\"י עלייה הנ\"ל נעשה בחי' וישב ה' מלך לעולם כו' וישיבה זו היא שלא יהיו רגליה יורדות כו'. כי היושב על הכסא משפיל גופו אבל מגביה רגליו מן הארץ וזהו והארץ הדום רגלי כו'."],[55,"וביאור הדברים מבואר במ\"א ע\"פ אז ישיר. ואח\"כ המשפילי לראות זהו בחי' ותורה אור והוא המשכת אוא\"ס ממל' דא\"ס בשמים תושב\"כ. ובארץ תושבע\"פ דכמו דארץ מקבלת משמים כמ\"ש למטר השמים תשתה מים. כך תושבע\"פ מקבלת מתושב\"כ כדאמרינן מנא הני מילי דאמר קרא כו' לראות היינו ליראות ר\"ל שיהא גילוי אוא\"ס ממש בשמים ובארץ שהן תושב\"כ ותושבע\"פ דבר ה' למעלה מגלוי בחי' אור האהבה מנפש אלקית שנק' ג\"כ אור כנ\"ל. אך שהוא נמשך מבחי' שמיעה והתבוננות בלבד כמ\"ש שמע ישראל כו' ואהבת כו' ובכל מאדך. אבל בחי' ותורה אור זהו בחי' המשפילי לראות. פי' ליראות בבחי' ראיה וגלוי ממש עין בעין יראו וגו':"],[56,"<b>כי אתה נרי ה' והוי\"ה יגיה חשכי.<\/b> להבין הכפל ב\"פ הוי' הא' הוי' והב' והוי' בתוספת וי\"ו. הנה כתיב נר ה' נשמת אדם. פי' שנשמת אדם המלובשת בגוף הוא בחי' נר של שם הוי'. לפי שכל הארבעה אותיות דשם הוי' מרומזות בנר."],[56,"והיינו בארבעה דברים שבנר שהם השמן והפתילה וב' גווני אור נהורא אוכמא הנאחז בפתילה ונהורא חיורא למעלה ממנה. ולכן הנשמה קרויה נר שיש בה ג\"כ ד' בחינות הללו שמן ופתילה וב' גווני אור המרומזות בד' אותיות הוי'."],[56,"ולהבין ד' בחינות הללו בנשמה. וגם להבין ענין הנרות שהיו במקדש שארז\"ל וכי לאורה הוא צריך כו'. אלא עדות היא לבאי עולם שהשכינה שורה בישראל. וצ\"ל למה הנרות דוקא עדות להשראת השכינה. אך הענין הוא כי הנה אור המאיר הוא בשביל שנאחז האור בפתילה ומכלה אותה. אך הפתילה לבדה היתה כבה וכלה במהרה וגם לא היתה הארת האור טובה כ\"כ רק ע\"י השמן שהוא הגורם התחברות האור בפתילה."],[56,"והוא הגורם להיות האור טוב ובהיר שע\"י השמן נעשה גוון נהורא חיורא. וע\"י הפתילה גוונא אוכמא. וככל המשל הזה כך הוא בהתלבשות הנשמה ⟦מ,ג⟧בגוף ונה\"ב שאור הנאחז ונתלבש בנפש הבהמית הוא כמשל האור שנאחז בפתילה. כי הנה הנה\"ב נלקחה מבחי' ק\"נ וכלולה מע\"ס דנוגה שכל ומדות. כי זלעו\"ז עשה. כמו שיש ע\"ס בנשמה היא נה\"א שהם בקדושה. כך יש עשר בחי' בנה\"ב שהן לגרמיה כו'. אשר שלט האדם באדם."],[56,"ולאם מלאם יאמץ. וע\"ס דנה\"א נאחזות ומתלבשות בע\"ס דנה\"ב שהן לעומת זה. והכוונה הוא בכדי להפך נה\"ב ולכלות אותה באור הנשמה. ולהיות אתכפייא ואתהפכא כו' דוגמת כליון הפתילה באור הנאחז בה. וכמו שהפתילה עצמה נהפכת לאור ואש. כך נה\"ב עצמה היא אתהפכא כו':"],[56,"<b>אך<\/b> להבין ענין זה כיצד תהיה התהפכות נה\"ב החיונית להיות עולה במדרגה גדולה כ\"כ להיות ממנה אור וגילוי אלקות. הנה כתיב ארוממך אלקי המלך. ויש בזה ב' פירושים הא' ארוממך ממטלמ\"ע והב' ארוממך היינו להיות המשכת הרוממות מלמעלמ\"ט."],[56,"וביאור הענין כי הנה פי' אלקי מלשון אלי הארץ שהוא ל' כח שזה אמר דהע\"ה בעבור כללות העולם שהכח והחיות הנמשך בהם מאוא\"ס ב\"ה הממכ\"ע הוא בבחי' המלך שלהיותו מלך על כל העולם הם חיים וקיימים ונתהוו מאין ליש מבחי' זו דמלכותו ית'."],[56,"ונודע שהמלוכה והממשלה שבמלך אינה רק בחי' הארה והתפשטות לזולתו ואינו נוגע למלך עצמו כמו שאר מעלות ומדות שבו שהוא חכם כו'. וזהו מלכותך מכ\"ע. שהתהוות כל עולמים עליונים ותחתונים והכח והחיות המלובש בהן ומהוה אותן נמשך מבחי' מדת מלכותך שהוא ענין מהות המלוכה והממשלה ולא ממהות המלך עצמו רק מבחי' מלכותו כו'."],[56,"והנה להיות התפשטות אוא\"ס ב\"ה בבחי' מלכותו ית' היו כמה צמצומים. וכמ\"ש להודיע לבני האדם גבורותיו וכבוד הדר מלכותו. גבורותיו הן הן הצמצומים להיות כבוד הדר מלכותו. ואין זה אלא בחי' זיו להיות כבוד והדר. וכמאמר בשכמל\"ו בחי' שם בלבד. ואי לזאת ארוממך שעי\"ז יבא לקיום ואהבת את ה' אלקיך הוא אוא\"ס ב\"ה ממש בכל לבבך בשני יצריך שעי\"ז אתכפייא כו' שלא יהי' חפץ ורצון אחר זולתו וכמ\"ש מי לי בשמים וכו'. וזהו ארוממך ממטה למעלה. (ועי' בזהר וארא דכ\"ח סוף ע\"ב) וגם ארוממך המשכת הרוממו' מלמעלמ\"ט. והענין כי הנה פעם אומרים יחיד חי העולמים מלך ופעם אומרים מלך יחיד חי העולמים. ופי' כי יחיד חי העולמים מלך היינו שהוא יחיד ומיוחד לבדו ית' וקדוש ומובדל כו'."],[56,"וחי העולמים הוא ע\"י כמה צמצומים להיות בבחינת מלך לעולם שעי\"ז ארוממך מלמעלה למטה כו' ומלך יחיד חי העולמים היינו שלהיות חי העולמים הוא מתצמצם בבחי' מלך ובחינת מלך זה הגם שהוא בחי' אחרונה לגבי א\"ס ב\"ה עצמו מ\"מ הוא בבחי' יחיד ומיוחד קדוש ומובדל כו' לגבי התהוות עלמין ואי לזאת נמשך בחינת מלכותו לבחי' יחיד חי העולמים להיות התלבשות מלך יחיד קדוש ומובדל כו' בבחינת עלמין והיינו בעוה\"ז הגשמי דוקא כי נעוץ תחלתן בסופן דייקא."],[56,"וזהו והיו הדברים האלה אשר אנכי מצוך היום כו' היום לעשותם כי הוא המשכת אור א\"ס ב\"ה ממש מצוך מלשון התקשרות בבחי' היום לעשותם דוקא שהוא בעולם הזה עולם המעשה ולא בעולמות עליונים שהם ע\"י השתלשלות בירידת סתר המדרגות מעילה לעלול כו' ורחוקים מאור א\"ס ב\"ה ממש. משא\"כ בסוף מעשה מתגלה אוא\"ס ב\"ה ממש שלא כדרך ירידת והשתלשלות העולמות אלא כמשל האור הנאחז בפתילה שקודם שנאחז בפתילה אינו עולה בשם אור כלל."],[56,"וע\"י התאחזותו בדבר גשמי נתהווה גילוי אור. אך אור זה צריך להמשיך ⟦מ,ד⟧על ידי עבודת האדם ורוח אייתי רוח ואמשיך רוח. אם ישים אליו לבו רוחו ונשמתו אליו יאסוף."],[56,"וזהו ענין הדלקת הנרות להדליק ולהמשיך האור שיהא נאחז בפתילה. וזהו קרוב ה' לכל קראיו לכל אשר יקראהו באמת. דהיינו להיות אמת ה' לעולם. ואמתות ה' הוא שמעלה ומטה שוים לפניו ית' כחשיכ' כאורה וסדר ההשתלשלות הוא רק בערכנו ובערך כל העולמות הברואים מאין ליש שלא יבטלו במציאות ונק' כדמותנו דמות כבוד ה'. אבל בצלמנו בצלם אלקים היינו אמתות יחודו יתברך בעליונים ובתחתונים בשוה."],[56,"וכיצד נמשך אמת ה' לעולם אמר הכתוב כי גבר עלינו חסדו. מחמת תגבורת חסד ואור עליון יותר מערך השתלשלות. והיינו ע\"י נה\"ב כד אתהפכא ואתכפייא כי נה\"ב הגם שלמטה בעוה\"ז היא במדרגה שפלה מ\"מ שרשה ומקורה העליון היא הגבה למעלה במאד שהיא מבחי' לפני מלך מלך. וכמ\"ש במ\"א מענין המאכל שעליו יחיה האדם מפני ששרשו ממקום גבוה כו'. ולכך ע\"י התהפכות נה\"ב בהתגברות הטוב על הרע מעורר כך למעלה בשרשה תגבורת אור וחסד עליון להיות גילוי אמת ה' לעולם אמתות ה' ממש. (והוא בחי' חסד עליון הממתיק הגבורות. פי' דהרי מבואר לעיל שכדי להיות התפשטות האור בבחי' מל' הוא ע\"י גבורות וצמצומים כמ\"ש להודיע לבני האדם גבורותיו כו'. אבל בחי' כי אתה נרי הוי' הוא בחי' כי גבר עלינו חסדו להיות תוספת אור בלי צמצומים כו'. ונק' בחי' מיתוק זה יחוד קובה\"ו כמ\"ש בתניא פמ\"א בהג\"ה) אך הנה כמו במשל אור הנר הנ\"ל שע\"י כליון הפתילה לבדה אינה מאיר כ\"כ כ\"א ע\"י השמן. כך צ\"ל בחי' שמן בעבודת האדם בהתלבשות הנשמה בגוף. והוא ענין שמן משחת קדש ורומז על התורה כי קדש הוא בבחי' חכמה ואורייתא מחכמה נפקת והשמן היא פנימיות החיות שבכל הדברים שמוציאים מהן השמן."],[56,"ולכן בכל הדברים יש שמן ואפי' באבנים כי כולם בחכמה עשית ויש בכולם פנימית החיות בבחי' שמן. והשמן הנמשך מקדש שהיא ח\"ע היא ג\"כ המתלבשת אפי' בדברים גשמיים כמו זרעים מועד כו'."],[56,"ושמן זה הוא הגורם הארה רבה להיות האור טוב להאיר. והיינו להיות גלוי אוא\"ס ב\"ה בנפש האדם בגלוי ממש כאלו רואה כו' ולא בדמיונות הנולדים מן המחשבה לבדה שהן חולפות ועוברות ואינן קבועות בנפש באמת לאמתו רק שיהא הגלוי בלב באמת לאמתו קבוע ותקוע בחיזוק כיתד שלא תמוט להיות נגדו תמיד וגלוי זה הוא להיות יראת ה' על פניו יראה עלאה בבחי' בטול ממש הנרמזת באות יו\"ד של שם הוי' כנודע כי שם הוי' הוא דחילו ורחימו רחימו ודחילו. נמצא שאות יו\"ד הרומזת לחכמה הוא בחי' דחילו שהיא בחי' יראה עלאה אם אין חכמה אין יראה. לכן ארז\"ל מה להלן באימה וביראה אף כאן כו'."],[56,"והיינו מפני התלבשות ח\"ע ששם שורה ומתגלה אוא\"ס ב\"ה ממש בבחי' בטול אפי' בדברים גשמיים הנאמרים בתורה אשר לפנינו. והלכה זו היא דבר ה' ממש. וכן האדם כשעוסק בתורה דבר ה' ממש ורוח פיו מדבר בו."],[56,"וכמ\"ש ודברי אשר שמתי בפיך ועז\"נ ודברת בם להיות המשכ' חכמה ויראה עילאה בם בד\"ת. ומזה נמשך תפלת י\"ח בלחש ובחשאי בחי' שמן שהוא בחי' בטול. וע\"ז רומזים כריעות והשתחואות שבתפלה שהם המשכות הבטול."],[56,"ולכן כתיב בעמדם תרפינה כנפיהם בבחי' לחש וחשאי. ויראה הנרמזת בה\"א אחרונה של שם הוי' היא יראה תתאה שלא למרוד בממה\"מ הקב\"ה ולא למרות עיני כבודו. והוא בחי' הפתילה ששולט בה אור האש להפך ולכלות ⟦מא,א⟧אותה."],[56,"וב' גווני אור הם ב\"פ רחימו שבשם הוי' כי ואהבת בגימט' ב\"פ אור היינו האהבה הרמוזה בה' ראשונה של הוי' היא בחי' אה\"ר הבאה מלמעלה אהבה בתענוגים שהיא בחי' מתנה כו' והיא בחי' נהורא חיוורא ואהבה הרמוזה בוי\"ו של שם הוי' היא האהבה הנולדה בנפש המשכלת ומתבוננת בגדולת א\"ס ב\"ה והיא בחי' נהורא אוכמא הקרובה אל הפתילה ומתאחזת בה:"],[56,"<b>וזהו<\/b> כי אתה נרי הוי' שבחי' הוי' היא בבחי' נר בשמן ופתילה. וב' גווני אור הרמוזות בד' אותיות של הוי' נעשה נרי שמתלבש בנר הוי' נשמת אדם כנ\"ל:"],[56,"<b>והוי\"ה<\/b> יגיה חשכי. והוי' בתוספת וי\"ו רומזת על בחי' הוי' ביותר עליונה. וכמ\"ש הוי\"ה הוי\"ה אל רחום וחנון כו'. ופסיק טעמא בגווייהו שיש ב' בחי' הוי'. והענין כי פעם כתיב הוי' רחום וחנון ופעם כתיב חנון ורחום הוי'."],[56,"ופי' הוי' רחום וחנון שכדי להיות התגלות מדות רחום וחנון מאוא\"ס ב\"ה דלאו מכל אלין מדות איהו כלל. הוצרך להיות בחי' הוי' שהוא צמצום והתפשטות המשכה והתפשטות. אך פי' חנון ורחום הוי' היינו שמבחי' חנון ורחום דהיינו מפני כי חפץ חסד הוא נמשך בחי' הוי' שהוא צמצום והתפשטות כו' שבסדר ההשתלשלות משא\"כ הוי' שקודם רחום וחנון היא ההוי' שלמעלה מגדר ההשתלשלות. ושם נעשה ג\"כ בחי' הוי' שהוא צמצום והתפשטו' כו' כדי להמשיך מדת רחום וחנון בהוי' שבסדר ההשתלשלות. (ועמ\"ש ע\"פ ואתחנן אל הוי' וע\"פ וירא ישראל את היד הגדולה כו' מענין ב' שמות הוי'):"],[56,"<b>והנה<\/b> בדורות הראשונים כמו בנביאים ושופטים מצינו דור שכולו זכאי או כולו חייב. ומי שהיה זכאי הי' זכאי במדרגת צדיק גדול או נביא ומי שהיה חייב היה רשע גמור ועי\"ז לא היו ממוצעים. אך דורות האחרונים דור אחר דור אין בהם רשעים כ\"כ ולא צדיקים כ\"כ טובים."],[56,"והענין שבדורות הראשוני' היו נשמות עליונות ממדרגות גבוהות ומצד נשמתם בעצמם היו יכולים לשלוט על הרע שבנפשם ומיד כשיתבונן בגדולת א\"ס ב\"ה יגיע אליו היראה כו' רק רשע גמור שמגביר הרע שבנפשו בשאט בנפש. אבל דורות האחרונים עיקבא דמשיחא בחי' עקביים אין כח בנשמתם עצמם לשלוט על הרע וצריך יגיעה רבה יגיעת נפש ויגיעת בשר."],[56,"וזהו והוי\"ה יגיה חשכי היינו בחי' חשך שבדורות אחרונים. כי דהע\"ה אמר זה בעד כללות ישראל שיש בהם בחי' חשך בדורות אחרונים עיקבא דמשיחא שאין אתה נרי הוי\"ה כלומר שאין נר הוי\"ה נשמת אדם מ\"מ והוי\"ה היא בחי' הוי\"ה עליונה שלמעלה מההשתלשלות יגיה חשכי ולמענו למענו יעשה כי חפץ חסד הוא באתעדל\"ע בלי אתעדל\"ת:"],[56,"<b>וזהו<\/b> ענין נס דחנוכה שנכנסו יונים להיכל. היכל הוא בחי' מח' ה\"י כ\"ל בגימטריא נש\"ב. והיונים הנ\"ל הם בחי' חכמה דקליפה חכמות חיצוניות כמו פילסופיא. שבזמן ההוא היו פילסופים המכחישי' בנבואה."],[56,"ולכן טמאו כל השמנים של בחי' חכמה שבקדושה שרצו להשכיחם תורתך כו' ונעשה נס ע\"י פך של שמן שהי' מונח בחותמו של כה\"ג דיקנא דכהנא רבא חסד עליון בהעלות אהרן את הנרות אהרן שושבינא דמטרוניתא שהיא אהבה הבאה מלמעלה באתעדל\"ע וממנו הדליקו כל הח' ימים שהם המחשבה וז' המדות שתהיינה מאירות באור האהבה הבאה מלמעלה בלי אתעדל\"ת והיא מבחי' וי\"ו בתוספת וי\"ו העליונה שלמעלה מעלה מן ההשתלשלות:"],[57,"<b>ביאור<\/b> על פסוק כי אתה נרי הנה בארוממך לשון נוכח יש ב' פירושים. הא' מלמעלמ\"ט ⟦מא,ב⟧הרוממות שלמעלה יומשך למטה יחיד חי העולמים מלך שהוא לבדו יחיד ומיוחד וחי העולמים נמשך להיות במל' ריבו רבבות עלמין."],[57,"ובכהאריז\"ל כ' שע\"י צמצום ומקום חלל כו' כי א\"א להיות עולמות וברואים כלל מבחי' א\"ס בעצמו וכל המשכות עליונות נמשכו במל' כנודע כי י\"ג ת\"ד נמשכו למטה במל' לפי שרגליה יורדות כו'."],[57,"ולכן נק' המל' בשם עטרה בספרי המקובלים כי המלכות היא בחי' כ\"ע שנמשך במל'. וגם ארוממך לרומם המל' מלך יחיד חי העולמים כנודע כי מל' דאצי' נעשה עתיק לבריא' בחי' יחיד כדי להיות חי העולמי' וצריך לרומם המל' בבחי' יחיד עד מל' דא\"ס ממטה למעלה."],[57,"וב' בחי' אלו הן שבת וחנוכה. כי שבת העלאה ממטה למעלה וחנוכה המשכה מלמעלה למטה. והעלאה זו היא ענין הבירורים מצמיח חציר לבהמה אלף טורין כו' שהם מבחי' אל שדי במילואו כו'."],[57,"והיינו שנכלל בבהמה להיות אין כי ענין הבירורים הוא להיות מיש אין כי בהמשכה נעשה מאין יש שם ב\"ן ס\"ג גס שהוא ישות והבירור הוא לאהפכא מיש לאין והיינו ע\"י שם מ\"ה בחי' בטול."],[57,"ולמטה הנה בחי' זו היא בנפש הבהמית כד אתכפייא כו' שעי\"ז מגביה למעלה מאד כי נה\"ב שרשה מעולם התהו כמו כל המאכלים הגשמיים שירדו בשבה\"כ מעולם התהו. ולכן אמרו חמרא וריחנא פקחין. ואמרו לא אכילנא בישר' דתורא כו' שהם משרש עליון. וכן נה\"ב שבאדם שרשה משם כי היא נלקחה משמרי האופנים והחיות שבמרכבה פני ארי' ממנו נמשך חיות כל החיות. ומפני שור חיות הבהמות. ומפני נשר חיות העופות כו'. וכולם שרשם מעולם התהו שירדו בבריאה בשבה\"כ."],[57,"והנה ענין עולם התהו הוא שלא היה התכללות מחמת רבוי אור ומיעוט כלים שהי' תגבורת האור כמו בלע בן בעור ושם עירו דנהבה דין הבה דין גמור בלי התכללות לפי שהוא דין חזק."],[57,"וכן יובב חסד כו' ולכן א\"א להיות התכללות כו'. משא\"כ שם מ\"ה בחי' בטול עולם התיקון רבוי כלים ומיעוט האור ונעשה חלישות האור. ולכן הגם שיש בו דין מ\"מ אינו חזק כ\"כ ויוכל להיות התכללות כו'."],[57,"ונה\"ב שרשה מתהו משא\"כ נה\"א היא מבחי' תקון. ולכן היא המבררת כו'. ונה\"ב כד אתכפיא היא הגבה למעלה כו'. וזהו צעק לבם דקאי על נה\"ב שהיא בחי' לב וצעקה היא העלאה ממטלמ\"ע במאד."],[57,"וזו היא העלאה לבחי' המל' ארוממך למעלה מעלה עד הכתר כי הכל נעשה ממותרי מוחין בחי' שערות כו' כי לגבי א\"ס ב\"ה בעצמות אין לו שייכות וערך ויחוס עם בריאת העולמות. אלא ע\"י שערות מותרי מוחין הארה בעלמא שאינו נוגע לעצמותו כמו אם יחתוך השער לא יכאב כו' רק שמקבל יניקה דרך שערה מצומצמת מאד ממותרי מוחין כו'."],[57,"וכאשר ישים האדם אל לבו שאין זה רק הארה בעלמא להיות ממכ\"ע וסוכ\"ע אי לזאת תגדל הצעקה בלב כו'. וזהו בחי' רצוא בחי' הפתילה. אך אם רץ לבך שוב לאחד המשכה מלמעלמ\"ט בחי' חנוכה כי הפתילה היא כבה מהר וגם אינה מאירה כ\"כ והיינו ע\"י השמן."],[57,"וענין השמן הנה בכל הדברים יש שמן כו' כי יש חכמה דאצי' וחכמה דבריאה כו' עד שנעשה חכמה דעשיה היא התורה שלפנינו המלובשת בגשמיות ויש תורה דבריאה שע\"ז אמרו קיים אאע\"ה את התורה עד שלא ניתנה דהיינו קודם התלבשותה בעוה\"ז הגשמי."],[57,"ולכן קיים מצות תפלין הגם שלא נכתב עדיין קדש לי כל בכור שלא היה יצ\"מ כלל. וכן מילה קיים ג\"כ קודם שמל א\"ע בגשמיות כי ענין מילה היא הסרת הערלה שלא יהיה יניקת החיצונים וקיים אאע\"ה מצוה זו למעלה שהסיר יניקת החיצוני' אך שלא היתה מצוה זו מלובשת בגשמיות מעשה המילה ⟦מא,ג⟧ממש וזהו עד שלא ניתנה ועיקר המשכת השמן הוא להיות המשכת ח\"ע כי יש ח\"ע וח\"ת. חכמה תתאה שנלקחה מן המדות."],[57,"וח\"ע למעלה מן המדות דו\"ר רו\"ד יראה תתאה מיחודא תתאה במל' משא\"כ יראה עילאה בחכמה עלאה ושרשה מו\"ס שהיא מגבורה דעתיק שמשם נמשך השערות בבחי' י\"ג ת\"ד. אבל מקורם ושרשם הוא במו\"ס ולא אבא דאצי'."],[57,"והיינו בחי' חכמה שבכתר ע\"פ קבלת מהרמ\"ק וע\"פ קבלת האריז\"ל היא הגבה למעלה במל' דא\"ס ומקור זה נמשך בתורה שלפנינו בגשמיות נתב\"ס דייקא אשר אנכי מצוך הוא בהיום לעשותם דייקא משא\"כ למעלה היא דרך השתלשלות מעילה לעלול בכמה רבבות מדרגות. וא\"כ רחוקה היא מאד בחי' מל' מבחי' מו\"ס חכמה שבכתר. אבל בעשיה גשמיות נמשך שלא כדרך ההשתלשלות:"],[57,"<b>וזהו<\/b> ענין נס דחנוכה שטמאו היונים כל השמנים כי הם מבחי' חכמה דקליפה. כי בבל נק' רישא דדהבא ופרס ומדי ב' זרועות כו' ולא נשאר אלא פך א' בחותמו של כה\"ג. חותם הוא יסוד וכה\"ג הוא כהנא רבא רב חסד שהוא בי\"ג ת\"ד דיקנא דכהנא רבא. וכהנא רבא המקור הוא מו\"ס הנ\"ל. וזהו ענין הוי' הוי' אל רחום וחנון כו' שלהיות אל רחום וחנון כו' שהן הי\"ג ת\"ד שראשיתם היא מבחי' אל צ\"ל המשכה מבחי' הוי' הוי' ב' פיאות כו'. שהוא המקור הנמשך ממ\"ס כו'."],[57,"והנה בתורה כתיב הוי' הוי' ופסיק טעמא בגווייהו. ובנביאים כתיב כי אתה נרי הוי' והוי' יגיה חשכי. הוי' והוי' בתוס' וי\"ו המחבר ואינו פסיק כו'. הענין הוא כי הנה כתיב חנון ורחום ה'. וכתיב ה' רחום וחנון. שיש ב' הויות א' בז\"א להיות עולמות הברואים כו'. והא' בא\"א להיות חנון ורחום."],[57,"והנה ה' רחום וחנון הוא בא\"א המשכת הוי' דא\"א ב' פאות כו'. להמשיך י\"ג ת\"ד בז\"א אבל חנון ורחום ה' היינו המשכת חנון ורחום י\"ג ת\"ד בז\"א להיות הז\"א בשם הוי' כו'."],[57,"וזהו כי אתה נרי ה' היינו הוי' דז\"א שהוא בבחי' השתלשלו' מי\"ג ת\"ד והוא נגד דורות הראשונים שהיתה נשמתם בעצם במעלה עליונה. משא\"כ והוי' יגיה חשכי. חשכי עקבות משיחא נמשך משם הוי' דא\"א שלא כדרך ההשתלשלות וצ\"ל וי\"ו החבור להמשיך ממקום עליון כזה."],[57,"והיינו ע\"י צדקה וכמאמר רז\"ל אין ישראל נגאלין אלא בצדקה. כי על צדקה נאמר זורע צדקות שהיא בבחי' זריעה כמו הגרעין הנזרע בארץ שמצמיח הרבה מחמת כח הצומח אשר בארץ שהיא בהעלם ויש בו בחי' א\"ס להצמיח עד אין קץ. כך הצדקה היא בבחי' זריעה שיש בה בחי' כח א\"ס בהעלם שהוא מבחי' א\"א סתימא דכל סתימין."],[57,"ועי\"ז מתרבה גלוי אור א\"ס עצמו שהי' בהעלם במ\"ס קודם שירד לימשך בי\"ג ת\"ד וזה הי' ג\"כ בחנוכה שטמאו כל השמנים למטה ולא היה אפשר להמשיך כ\"א ע\"י הפך של שמן שבחותמו של כה\"ג כהנא רבא הנ\"ל. וענין השמן הוא ההעלם שהרי השמן נבלע בפתילה. ומשם מאיר ביתר שאת כאשר השמן נמשך אחר הפתילה."],[57,"והנה ע\"י בחי' השמן והפתילה נעשה ב' גווני אור נהורא תכלא ע\"י הפתילה שהוא רק שיהא האור נאחז אבל אינו מאיר כ\"כ אלא ע\"י השמן שהוא המאיר אור צח ובהיר. נהורא חיורא דהיינו שיהא בגלוי לנוכח כאילו רואה ולא בדמיונות במחשבה לבדה שנק' העלם ולא גלוי כדמותנו כו'."],[57,"וענין ב' נהורין נהורא תכלא ונהורא חיורא הן ב\"פ רחימו שבאמצע ב\"פ דחילו כי יו\"ד דחילו וה\"א רחימו והוי\"ו רחימו והה' דחילו. והענין כי יש יראה עילאה בחכמה בחי' בטול ממש. משא\"כ יראה תתאה בחי' פחד במלכות שלא למרוד במלך זעות מחיל כסא."],[57,"וכולם משמיעים ביראה ופחד כו'. והיא פחד מבחי' חיצונית. ⟦מא,ד⟧אבל יראה עלאה היא בחי' בטול ממש מאחר שאין עוד מלבדו. והוא ענין תפלת י\"ח כריעות והשתחוואות המשכת הבטול. ושני פעמים רחימו היינו ה' עלאה בינה היא אהבה בתענוגים והיא אהבה הבאה מלמעלה ורחימו בוי\"ו הוא ז\"א אהבה שע\"י ההתבוננות נפש המשכלת ממטה למעלה וזהו ואהבת ב\"פ אור כו' וד\"ל:"],[58,"<b>נר<\/b> חנוכה מצוה להניחה כו' משמאל, כדי שתהא מזוזה מימין ונ\"ח משמאל. וצ\"ל הטעם שאין הנ\"ח ג\"כ מימין כמו המזוזה. אך יובן בהקדים ביאור מ\"ש כל אשר חפץ ה' עשה. וכתיב בדבר ה' שמים נעשו."],[58,"ובע\"מ נברא העולם שהיו מאמר ודבור. ולא נברא בחפץ ורצון בלבד. והענין כי הנה נודע שלכל הדברים יש חומר וצורה שהחומר הוא ענין הדבר ההוא בכללות דהיינו להיות שמים או ארץ או שמש וירח. והצורה הוא כל ציור וכל תמונה במראה ושטח שיש לכל דבר בדמותו בצלמו על איזה אופן נעשה כמו השמים והארץ הם כדורים ומן הארץ לרקיע כו' והשמש והירח הם גלגלים מאירים כו'. וכן עד\"ז בכל דבר נברא."],[58,"והנה החומר נברא בדבר ה' ובע\"מ שבמאמר יהי אור נתהווה בחי' האור מאין ליש. וכן במאמר יהי רקיע נתהווה הרקיע מאין ליש. אבל אופן צורת הרקיע בדמותו בצלמו הוא נעשה בחפץ ה' שלא בא לכלל גילוי בדבור או מאמר."],[58,"והנה מה שנברא החומר במאמר ודבור ולא נברא הכל בחפץ ה' ורצונו בלבד היא מפני שאז לא הי' גילוי מאין ליש רק שהיה העולם בטל במציאות ממש רק עיקר גילוי היש הוא ע\"י דבר ה' כי הוא צוה ונבראו פי' צוה מלשון מצות המלך כי מלכותך מכ\"ע אין מלך בלא עם שבחי' מלכות היא בחי' התנשאות והסתלקות שלא יאיר ויתגלה אלא בבחי' שם בלבד."],[58,"וזהו יהללו את שם ה' כי הוא צוה ונבראו כמו עד\"מ מלך ב\"ו שמלכותו היא שמו לבד אשר נקרא על מדינתו אבל לא בבחי' התלבשות כח הפועל בנפעל ממש והתלבשות כח הפועל בנפעל הוא למטה בע' שרים שר של מים שר של כו' שהם משמרי האופנים."],[58,"ויש גבוה מעל גבוה שמקבלים ג\"כ דרך עילה ועלול עד המלאכים שהם שכלים נבדלים. שהם פני ארי' פני שור שבמרכבה. אבל החיות של פני שור פני ארי' הוא יש מאין ממש. דהיינו שהמשכת החיות אשר להם הוא בבחי' אין והארה בעלמא שהוא בחי' שם בלבד ומזה נעשה גילוי היש. אך תכלית בריאת יש מאין הוא כדי להיות היש בטל לאין ונגלה כבוד ה' למטה כמו למעלה."],[58,"וכמו שיהיה לע\"ל כי עין בעין יראו כו' וזה תלוי בעבודתנו כל ימינו היום לעשותם. וכל ישראל יש להם חלק לעוה\"ב. וצריך כ\"א להמשיך בחלקו גילוי זה להיות בטול היש והוא מחמת ההתבוננות בגדולת א\"ס ב\"ה שאתה הוא קודם שנבה\"ע ואתה הוא כו' בלי שום שינוי כי אני הוי' לא שניתי שאין העולם מעלים לפניו ית' וכחשיכה כאורה שאין ההעלם וההסתר אלא לעיני בשר שלנו. אבל קמיה כולא כלא חשיב ממש ומעלה ומטה שוין לפניו שנמצא למטה כמו למעלה ממש."],[58,"וא\"כ גם בחי' היש בטל אליו ית'. וזהו כי גדול ה' ואדונינו מכל אלקים. ופי' מכל אלקים הם ק\"ך צירופי אלקים המעלימים ומסתירים אור ה' וקדושתו לבלתי יתגלה אוא\"ס ב\"ה כמו שהוא שלא יתבטלו העולמות במציאות. אלא שיהא נראה העולם ליש ודבר נפרד. אבל אור הוי' הוא גדול על כולם ומושל על כולם להיות היש בטל. (וזהו כי אני ידעתי כי גדול כו'. אני זו כנס\"י. אבל העכו\"ם אומרים עזב הוי' את הארץ. ופרעה אמר לא ידעתי את הוי' כו'. ולכן נאמר ביתרו אחר שנתגייר עתה ידעתי כי גדול הוי' כו') והיינו לפי שכל אשר חפץ הוי' נמשך ועשה גם בשמים ובארץ שכולם יש להם ציור ותמונה מבחי' חפץ ⟦מב,א⟧ורצון הוי' שלא בא לידי גילוי בדבור ומאמר שהוא הפועל הישות."],[58,"וזהו ענין שיתף מדה\"ר. שבכל מע\"ב כתיב ויאמר אלקים ואח\"כ שיתף מדה\"ר דכתיב ביום עשות ה' אלקים כו'. וזהו למה יאמרו הגוים איה נא אלהיהם שבחי' אלקות הוא בבחי' איה דהיינו בבחי' הסתלקות לפי שאומרים עזב הוי\"ה את הארץ ואין העולם מתנהג אלא בבחי' אלקים שהוא שם הצמצום והסתלקות להיות העולם יש ודבר נפרד אבל באמת כל אשר חפץ הוי\"ה עשה."],[58,"ועל ענין זה מדבר כל המזמור שלמעלה מזה הים ראה וינוס כו'. ההופכי הצור כו'. שמספר בשבח מעלת שם הוי\"ה המושל על שם אלקי' ומשנה הטבע מצור החלמיש שהוא מיסוד האש וממנו מוציא מים והיינו לפי ששם אלקים שהוא הצמצום ומעלים להיות בבחי' יש ע\"פ הטבע המוטבע בכל דבר לפי מזגו ותכונתו הוא בטל לגבי שם הוי\"ה המושל עליו שהוא ענין גילוי אוא\"ס ב\"ה שכשמו כן הוא. ולכן גם הים ראה וינוס כו':"],[58,"<b>והנה<\/b> כאשר יתבונן וישכיל כל זה האדם. אזי תכלה ותכסוף נפשו ליבטל אליו ית' עד שתחפץ להתפשט מתענוגי עוה\"ז ולהפך לבו לגמרי ולדבקה בו וכמ\"ש מי לי בשמים כו'. ובזוהר אמרו מאן דלא טעים מרירו למיתקו ומהפך חשוכא לנהורא לית ליה חולקא הכא שצריך להפוך טעם מרירו למיתקא."],[58,"ומרירו הן תאוות עוה\"ז ותענוגים שמושפעים מהיכלות הקליפות. שאין לך דבר למטה שאין לו היכל למעלה כנגדו שממנו בא תוצאת הדבר ההוא והשפעתו. וכל תענוגי עוה\"ז אפי' דבר קל ואפי' המסלסל בשערו הנה החיות ההוא נמשך מהיכלות הטומאה."],[58,"ולכן נענש יוסף בשבתו בבית האסורים י\"ב שנה על שהיה מסלסל בשערו כדאיתא בגמרא ע\"פ ויהי יוסף יפה תואר ויפה מראה מיד ותשא אשת אדוניו כו'. וצריך להפוך לבו לטעום ממש למיתקא טעמו וראו כי טוב ה'. אז תתענג על הוי\"ה."],[58,"וזה הי' ענין הקרבנות שנהפך חלב מנפש בהמה ועולה ונכלל באש שלמעלה אשר תאכל על המזבח להיות אשה ריח ניחוח לה'. וכמו\"כ תהיה התפלה שהיא במקום הקרבנות להלהיב נפשו באש שלמעלה ולהתענג על הוי\"ה."],[58,"וענין אתהפכא חשוכא לנהורא. הוא שחשך הגשמי של עוה\"ז מעשה שמים וארץ שנראים ליש ודבר גשמי יתהפך לנהורא להיות בו גילוי אוא\"ס ב\"ה להיות היש בטל אליו ית' ונגלה כבוד ה' למטה כמו למעלה."],[58,"והיינו שע\"י בחי' טעים מרירו למיתקא שהוא ממטה למעלה להפוך לבו ותאוות עוה\"ז לדבקה בו ית' בתשוקה וצמאון כו' יאיר אור ה' מלמעלמ\"ט במקום החשך של העוה\"ז שלא יהיה העולם מעלים אור ה' וקדושתו וזהו ג\"כ ענין נר מצוה ותורה אור נר מצוה היא בחי' העלא' מלמטלמ\"ע ותורה אור היא בחי' ההמשכה מלמעלמ\"ט וע\"י בחי' נר מצוה בא אור התורה:"],[58,"<b>וביאור<\/b> הדבר. הנה צ\"ל ענין אותיות מה ענינם. כי הנה האותיות נחלקות במבטא ע\"י ה' מוצאות הפה. אחה\"ע מהגרון כו'. והנה אין המוצאות כלי המבטא דומים לכנור שהוא כלי הנגון שבנגן המנגן עליו מוציא קול שהקול ההוא בא מן תנועת הכנור שמוציא את הקול. משא\"כ האותיות אינן באות מחמת תנועות כלי המבטא שהן ה' מוצאות הפה שהרי מאליהן ומעצמן יוצאות תנועות האותיות בלי שום הכנה וכוונה מכוונת באדם להניע הלשון לאותיות דטלנ\"ת. או השפתים לאותיות בומ\"ף. אלא אדרבה האותיות מניעות את הלשון לאותיות דטלנ\"ת והשפתים לאותיות בומ\"ף והאותיות מצד עצמן הן מושרשות בנפש עצמה."],[58,"והנפש היא המוציאה אותן מההעלם אל הגילוי מתחלה באותיות ⟦מב,ב⟧המחשבה ואח\"כ באותיות הדבור. וז\"ש ויהי האדם לנפש חיה. ות\"א לרוח ממללא שבחינת האותיות הן בבחי' חיה. כי יש באדם נפש רוח נשמה חיה. נפש הוא בחי' אותיות מחשבה ודבור."],[58,"ורוח הוא הבל הלב שהוא קול כלול מאש רוח ומים כנודע ונשמה היא בחי' השגת השכל ונשמת שדי תבינם. וחיה היא בחי' חכמה דהיינו מקור החכמה שלמעלה מן ההשגה ושם הוא שרש האותיות אלא שקבען בפה ולא שבראן שם בפה כי בריאותם והתהוותם בשרשם הוא למעלה בבחינת חיה ומשם נמשכו ונתחלקו לכ\"ב אותיות לדבר בם איש ואיש כלשונו."],[58,"ובזה יובן ענין מארז\"ל שמט\"ט קושר קשרים לקונו מתפלותיהן של ישראל. כי הנה המלאכים מעלים התפלות לפי שדבור האדם הוא גשמי והמלאכים הם רוחני' שהדבור שלהם הוא כמו מחשבה שלנו וע\"י המלאך המקבל התפלה מזדככת התפלה מגשמיות לרוחניות ע\"י המלאך ההוא."],[58,"והנה גבוה מעל גבוה עד עולם העליון שבו משכן מט\"ט והוא קושר כתרים שלמעלה מן הראש ומוחין. וע\"י זה ממשיך אותיות חדשות. כי הנה התפלה היא בקשת יה\"ר שיתהווה בחינת רצון שכמו שכבר נמשך רצה\"ע בחכמה. הנה החכמה מחייבת ע\"פ התורה אין יסורים בלא עון שהעון גורם יסורים ח\"ו אבל ע\"י התפלה יה\"ר נמשך רצה\"ע שלמעלה מבחינת חכמה ושם הוא רחמים פשוטים ורבו פשעיך כו'."],[58,"וזהו שארז\"ל כשישראל אומרים יהא שמו הגדול מבורך כו' הקב\"ה מנענע בראשו. פי' שמנענע וממשיך בראשו הוא רצה\"ע ב\"ה כי אותו מבקשים יהא שמו הגדול מבורך שיהא ברוך ונמשך שמו הגדול שלמעלה מבחינת השתלשלות שהוא גדול ומהולל מאד."],[58,"והמשכת רצה\"ע הזה הוא ע\"י העלאת אותיות התפלה לשרשן ומקורן כתר העליון ע\"י מט\"ט. והיינו לפי ששרש האותיות היא בכתר העליון למעלה מבחי' חכמה ומוחין אלא שראשית הגלוי היא בחכמה שא\"א להשכיל ולהשיג כל דבר מושכל כ\"א ע\"י אותיות. אבל האותיות עצמן אינן בחי' שכל שא\"א לשכל המושג להשיג ענין מהות האותיות בעצמותם אלא שהן לבוש השכל והלבוש הזה הוא מבחי' חיצוניות עליון שירד ונתפשט למטה להלביש את השכל. ומשם יורד עוד להיות אותיות מחשבה ודבור:"],[58,"<b>והנה<\/b> התורה נתלבשה באותיות ג\"כ עד\"ז שאותיות התורה שרשן למעלה מעלה מבחי' התורה. דאורייתא מחכמה נפקת והאותיות שרשן למעלה בבחי' כתר. ואותיות מלשון אתא שהוא לשון המשכה. שהאותיות הן המשכות שבהן ועל ידן נמשך להיות התורה."],[58,"והענין כי הנה כתיב כאשר יאמר משל הקדמוני והוא התורה שהתורה נקראת בשם משל הקדמוני. וביאור הדבר ההוא כי הנה ענין המשל הוא להמשיל את הנמשל באופן שיובן מתוך המשל. והרי המשל הוא ענין אחר שאינו מהות הנמשל. אלא שהנמשל מובן מתוכו ע\"י שדומה לו בצד מה."],[58,"וז\"ש וביד הנביאים אדמה. וחז\"ל המשילו מראה הנבואה לאספקלריא שכמו שרואין באספקלריא הגם שנראית דמות הצורה בתמונתה ובצלמה ממש מ\"מ אין זאת גוף הצורה עצמה ממש אלא דמותה ותמונתה. כך כל השגת הנביאים באלקותו ית' אין זה אלא בחי' דמות ודמיון."],[58,"והיינו כמו בחי' משל שממנו מובן הנמשל. אבל באלקותו ית' ממש כתיב כי לא יראני כו' וכמשארז\"ל. וז\"ש בשלמה וידבר שלשת אלפים משל על כל דבר מד\"ת כו' דהיינו שאמר על כל דבר מד\"ת רוחניות הענין כמו מצות קרבנות מן הבהמה. ומקריבים חלב ודם ע\"ג המזבח בכהן ובגדי כהונה והיה אומר ענין הקרבנות ברוחניות ומהו נקרא חלב ודם ברוחניות ומהו כהן ומהו בגדי כהונה."],[58,"והנה גבוה מעל ⟦מב,ג⟧גבוה כמה מדרגות רוחניות זו למעלה מזו. והשיג שלמה בחכמתו שלשת אלפים משל. דהיינו שלשת אלפים מדרגות זו למעלה מזו. וכולם אינן רק בחינת משל לגבי בחינת אלקות ממש השורה ומתלבש בתורה."],[58,"והנה שלמה לא השיג אלא שלשת אלפים משל. אבל באמת כך הוא עד רום המעלות לאין קץ שכולם אינן רק בחינת משל לקדמונו של עולם. דהיינו אור א\"ס ב\"ה ממש שלמעלה מעלה מבחי' וגדר השתלשלות לא בבחי' ממלא ולא בבחינת סובב רק שהתורה נמשכה משם ע\"י בחינת אותיות והמשכות."],[58,"וע\"ז ארז\"ל דוד הע\"ה היה מחבר תורה של מעלה בהקב\"ה. דהיינו שהמשיך אותיות התורה מאוא\"ס ב\"ה ממש. ועז\"נ אשר יעשה אתם האדם כו'. לעשות אותם. שעשיית התורה היא ע\"י האדם. וכמארז\"ל מעלה אני עליכם כאלו עשאוני. וזהו ותורה אור שהתורה מאירה אוא\"ס ב\"ה ממש. אך אין אור התורה עולה בשם אור אלא ע\"י נר מצוה:"],[58,"<b>והענין<\/b> שהארת אור הנר הוא ע\"י שיש אויר סביב האור. משא\"כ בלא אויר יכבה ולא יאיר כלל. ולכן אין כופין כלי ע\"ג הנר בשבת שלא יכבה שמחמת כפיית הכלי מונע האויר שסביב האור."],[58,"והיינו כי האויר גורם להיות הארת אור הנר לפי שאויר הוא אותיות אור י' שהאויר הוא מקור האור. כי היו\"ד שבהעלם אותיות אויר הוא העלם האור ובו ועל ידו נמשך ויוצא האור מההעלם אל הגילוי."],[58,"והיינו כמו בחינת אותיות שלמעלה מהתורה ושם הוא שרש ומקור המצות שהן מושרשות ברצה\"ע ב\"ה שלמעלה מהחכמה בחי' דאורייתא מחכמה נפקת. ולכן בעשיית המצות שהן בבחינת העלאה מלמטה למעלה למקורן ושרשן בחי' אוי\"ר אור י' גורם להאיר אור התורה כי כל המצות נק' בשם צדקה. כמ\"ש וצדקה תהיה לנו כי נשמור לעשות את כל המצוה הזאת כו'."],[58,"וצדקה לדלים ואביונים היא המשכה והשפעה להחיות רוח שפלים. וכך מעוררים למעלה בחי' המשכות להחיות רוח שפלים דקמיה כולא כלא חשיב והכל נק' שפלים ודלים אצלו ית'. וההמשכות וההשפעות הן הן אור התורה. כי אור ושפע הכל א'."],[58,"וזהו שארז\"ל כל האומר אין לי אלא תורה אפילו תורה אין לו רק צ\"ל תורה וגמ\"ח כי בלא גמ\"ח זו צדקה אין אור התורה מאיר לו. וזהו אפי' תורה אין לו. פי' שאין התורה שייכה ומתייחסת אליו רק התורה היא בחי' אותיות הנ\"ל. וזהו אמשיך רוח ואייתי רוח. פי' רוח היינו בחינת אוי\"ר הנ\"ל ומתחלה אמשיך מקור בחי' אותיות. ואח\"כ אייתי וממשיך המשכת אור א\"ס ב\"ה בחכמה ראשית גילוי האותיות להיות התורה אור:"],[58,"<b>ובזה<\/b> יובן ענין מזוזה מימין ונר חנוכה משמאל כי מזוזה היא בחי' העלאה ממטה למעלה כמו בחי' המצות. וענין המזוזה הוא שכותבין פ' שמע והיה אם שמוע שכתוב שם אחד ואהבת בכל לבבך ובכל נפשך ובכל מאדך בחי' העלאה."],[58,"וקובעין בפתח הבית להעלות הבית וכל אשר בו כל רכושו וקנינו בכל התיבות להיות בטלים לאהבת ה' בכל מאדך בכל ממונך. ולכן קובעין המזוזה בימין כי וימינו תחבקני כאדם החובק את חבירו שמקרבו אצלו כך נמשך ימין מקרבת להעלות אליו ית' כל הבא לקרב אליו ית'. אבל נ\"ח הוא המשכת אור התורה. כי היונים רצו להשכיחם תורתך ולכן הוא משמאל. כי מימינו אש דת למו שהתורה נמשלה לאש כנודע."],[58,"ובפרט שעיקר מצות נ\"ח להאיר בחוץ ברה\"ר ובחי' רבים היינו טורא דפרודא מבחי' ז' אומות שגם שם יאיר אור ה' וקדושתו שלא יהא העלם והסתר כמו שהיה בימי חשמונאי שרצו ⟦מב,ד⟧היונים להשכיחם תורתך. וכשגברה מלכות בית חשמונאי תקנו להמשיך אור התורה גם במקום הרבים טורי דפרודא:"],[58,"<b>והנה<\/b> שרש הז' אומות רישיה דעשו בעטפא דיצחק שהוא מבחי' גבורות שהן בחי' שמאל. אך הגורם להיות המשכת נר חנוכה בשמאל היינו בחי' המזוזה שבימין שהיא בחי' ההעלאה שע\"י העלאה זו נעשה בחי' ההמשכה הנ\"ל ונמשך גם במקום החשך בחינת טורי דפרודא. כי עיקר הדבר הוא להיות החשך דוקא מאיר דהיינו בחי' אתהפכא חשוכא לנהורא. וזהו שארז\"ל (סוטה מ\"ט) עלמא אמאי קא מקיים אאיש\"ר דאגדתא. כי אגדתא הוא בחי' תרגום שכל התלמוד הוא בל' תרגום. ותרגום הוא בחי' אחוריים דקדושה כנודע. וכשנמשך להיות שמיה רבא מברך ונמשך גם בבחי' תרגום שהוא בבחי' אחוריים אזי אתהפכא חשוכא לנהורא וזהו עיקר קיום העולם:"],[59,"ביאור על הנ\"ל"],[59,"<b>ביאור<\/b> הדברים על ענין נ\"ח משמאל ומזוזה מימין. הנה המצות הן מלמטה למעלה והתורה מלמעלה למטה. והיחוד שביניהם הוא כמשל העומד למעלה ורוצה להתקרב עם העומד למטה זה עולה בסולם וזה יורד עד שנפגשין זה בזה."],[59,"וביאור הענין הנה כתיב כל אשר חפץ ה' עשה. וכתיב בדבר ה' שמים נעשו. והענין שהחומר נברא בדבר ה' והתמונה והציור באיזה אופן שנברא הוא מחפץ ה' מה רבו מעשיך ה' כולם בחכמה עשית. שבחי' החכמה היא בחי' גבורות. דהיינו התחלקות לעשות כל ציור וכל תמונה לכל הפרטים למיניהם."],[59,"ושרש החכמה למעלה הוא בחי' בוצינא דקרדוניתא קו המדה מדוד משחת'. מי מדד בשעלו מים כו'. והגילוי הוא בחכמה דאצי' אור אבא ושם מה רבו מעשיך שרבו מאד פרטיים רבים. אך שהיו כלולים בחכמה וכמשל השכל הגשמי שתופס ומקיף הרבה ענינים בבת אחת וברגע אחת וכדי להוציא מהעלם אל הגילוי צריך לפרט בדבורים רבים ושונים בשעה ושתים. כך בחכמה כלולים מה רבו מעשיך בכל ציור וכל תמונה ונפרטו בע\"מ שנברא העולם. אך המאמרות הן עשרה בלבד כי לא נפרט הכל בדבור רק דרך כלל ולא דרך פרט:"],[59,"<b>והטעם<\/b> כי מה שנפרט בדבור הוא בכדי להיות בחי' יש כי מבחי' חכמה דאצי' לא היה יכול להיות בחי' יש ואפי' מה שנתלבש בז\"א שהוא בחי' הוי\"ה הכל נק' בחי' א\"ס דאיהו וחיוהי חד."],[59,"ולא היה יכול להיות בחי' פירוד רק במל' דאצי' בדבר מלך שלטון. והיינו ע\"י כי מל' דאצי' נעשה עתיק דבריאה וכו'. אך מ\"מ בחי' הוי\"ה מושל בבחי' מל' להיות בטול היש וכענין וצבא השמים לך משתחוים דהיינו בחי' בטול המלאכים בכלות הנפש. והשמש והירח משתחוים אפי' בגופם שסובבים והולכים ובטול זה הוא ע\"י כל אשר חפץ הוי\"ה שבחי' חפץ זה מתלבש בחכמה דאצי' וחכמה דאצי' מתלבשת בחכמה דמל' דאצי' המתלבשת בבי\"ע כי גבוה מעל גבוה שומר. וכל מה שלמטה מקבל ממה שלמעלה הימנו עד רום המעלות. (ואפי' הפילסופים מודים בזה רק שאין משיגים רק עשר בחי' התחתונות ח' גלגלים וגלגל היומי. וע' בפרדס שער ששי ספ\"ג וכבר הסכימו החוקרים כו' וגלגל השכל העשירי כו' ויותר מזה אין משיגים אבל יכול להיות גם לפי דעתם שיש למעלה מהם ג\"כ) רק העכו\"ם אומרים מאחר שכבר נשתלשל בהעלם אחר העלם בבחי' שם אלקים המצמצם כו' מוכרח להיות נשאר כך אבל כי אני ידעתי (אני בחי' מל' וכנ\"י) כי גדול הוי\"ה ⟦מג,א⟧ששם הוי\"ה מושל על כל בחי' אלקים משא\"כ פרעה אמר לא ידעתי את הוי\"ה שלא ידע רק שם אלקים. ואמר עזב ה' את הארץ (ובאמת לא בדעת ידבר כמ\"ש בתניא ח\"ב שהרי נס של בריאת שמים וארץ גדול מנס של קי\"ס כו' ע\"ש) ולכן אומרים איה אלקיהם. אבל באמת כל אשר חפץ הוי\"ה עשה. שזהו ענין יחוד שם הוי\"ה עם שם אלקים ויחוד קוב\"ה ושכינתיה שיחוד זה היינו בחי' המשכה שנמשך שם הוי\"ה ומשתלב בשם אלקים להיות בטול היש כו'."],[59,"והנה בבחי' יחוד זה והמשכה זו יש ב' דרכים. הא' ששם הוי\"ה יורד למטה לבחי' אלקים ונק' שילוב הוי\"ה באלקים. ואזי האל\"ף קודם לי' ששם אלקים מלביש את שם הוי\"ה. ושם הוי\"ה מלובש בתוכו. והב' ששם אלקים עולה למעלה. ונכלל בשם הוי\"ה ואזי היו\"ד קודם לאל\"ף כו' והנה היתרון והמעלה הוא כששם אלקים עולה למעלה כי כשהשם של הוי\"ה יורד לבחי' שם אלקים להתלבש בו הנה הוא ע\"י כמה צמצומים להיות התלבשות בבחי' יש אבל כשהשם אלקים עולה ונכלל בבחי' הוי\"ה ה\"ז עולה לבחי' אין כו':"],[59,"<b>והנה<\/b> נר מצוה הוא בחי' העלאה. ותורה אור הוא בחי' המשכה וביאור הענין הוא בהקדים להבין ענין האותיות. והוא כי האותיות היוצאות בה' מוצאות הפה. אחה\"ע מן הגרון כו'. אין המוצאות עושים ומפעילים את האותיות כמו כנור המנגן שמוציא הקול ע\"י האדם המנגן שאז נולד ונתהוה הקול ונגון. אבל האותיות שבה' מוצאות הפה אינו כן אלא שהאותיות כבר היו בנפש שכל נפש מליאה אותיות ובבואם לה' מוצאות הפה הם המניעים את המוצאות ולא מתנועעים ע\"י המוצאות."],[59,"והנה יש כמה בחי' אותיות. אותיו' המחשבה ואותיו' הדבור. אותיות המחשבה בבינה ואותיות הדיבור במל' ובחי' דבור שלמעל' הוא בבחי' המחשבה למטה שהוא דבור המלאכי' וקרא זא\"ז וגבוה מעל גבוה שמקבלי' דין מן דין עד רום המעלות מה שלמטה הוא בבחי' מחשבה נק' לגבי שלמעלה בחי' דבור ובחי' מחשבה שלמעלה יותר נעלמה."],[59,"והנה שרש גלוי האותיות הוא בחכמה ויהי האדם לנפש חיה. בחי' חיה היא בחכמה. אך אין זה רק בבחי' גלוי אבל שרשם הנעלם הוא למעלה מעלה בבחי' כתר כמ\"ש בזוהר אינון כתרין עילאין כו' ונחתא כ\"ף מעל כורסייא דיקריה כו' כי מהות האותיות אינן בחי' שכל רק הם למעלה מן השכל שא\"א להשיג בשכל מהות האותיות ומוצאן במבטא אב\"ג שהם יוצאות מכלי השכל. רק עיקרם נלקחים מבחי' שלמעלה מהשכל והן נעשות בחי' לבוש להשכל להשכיל כל דבר בכל לשון מע' לשון. שכל דבר שכל אינו נתפס אלא באותיות אבל אין האותיות מהות השכל ועצמותו אלא בחי' לבושו כנודע שהשכל מתלבש לפעמים באותיות אלו."],[59,"ולפעמים באותיות אלו. כמו דבור התוספות והר\"ן שמלבישים כל א' השכל באותיות אחרים ונלקחים מלמעלה מן השכל רק שאין מתגלים אלא בשכל. והמשל בזה כח ההולדה שבמוח שנתהווה באדם אחרי היותו בן י\"ג או ט' (סנהדרין רפ\"ח) ואף שכבר הי' לו מוחין בשלימות מ\"מ כח ההולדה לא נגמר עד היותו בן י\"ג או ט' וגמר כח זה תלוי במאכל אשר יאכל. וכנודע ממה שאין מאכילין את הכה\"ג בעיוה\"כ דברים שמרבי' הזרע. שיש מאכלים מרבים הזרע. ויש מאכלים ממעיטים."],[59,"והנה במאכלים ההם עצמן אין בהם כח ההולדה רק כשבאים להמוח. והמוח מתחזק על ידם אזי נתהוה ונגמר כח ההולדה. כך האותיו' באים מלמעלה מהשכל שאינו נתפס באותיות כלל. ומ\"מ כשבאים לבחי' השכל נעשה גילוי השכל ע\"י אותיות."],[59,"ולכן אמרו על מט\"ט שקושר כתרי' לקונו מתפלותיהם של ישראל. והענין כי אותיות התפלה עולות למעלה ע\"י המלאכים כנודע שכמה מלאכים ממונים ⟦מג,ב⟧בכל היכל לקבל התפלות. ואיתא בזוהר שהמלאך נשיק לה."],[59,"וביאור ענין זה הוא כמו הנושק עד\"מ מכניס רוחו והבלו בדבר שנושק. כך המלאך מכניס רוחו והבלו באותיות התפלה להעלותם מבחי' דבור האדם לבחי' דבור המלאכי' שהיא בחי' מחשב' שלמט' וכך עולה התפלה למעל' מעולם ועד עולם. עד עולם העליון שם הוא מט\"ט שעושה בחי' כתר זה. פי' שמעלה האותיו' עד מקורן ושרשן שהוא בכתר."],[59,"והיינו כדי להמשיך אותיות כי התפלה היא יהי רצון שיהי' המשכת רצון אחר מבתחלה שנמשך בחכ' וחכמה היא בחי' דין. וכן התורה דמחכ' נפקת מימינו אש דת למו שהיא בחי' אש וגבורות וע\"פ התורה אין יסורים בלא עון. אבל בכתר שם הם רחמים פשוטים ונושא עון כו' ומשם נמשך אותיות חדשות כו':"],[59,"<b>והנה<\/b> ככל הענין הזה באותיות כך הוא בבחי' המצות כי נר מצוה. והענין שאין אור הנר מאיר אלא כשיש אויר סביב האור משא\"כ כשאין שם אויר יכבה ולא יאיר כלל והנה האויר הוא בבחי' אותיות. כי הרי רואין שיסוד האויר הוא תחת יסוד האש."],[59,"ואעפ\"כ הרי יש בו דקות הרבה מיסוד האש. והטעם כי האויר אע\"פ שהוא למטה מיסוד האש. מ\"מ שרשו הוא למעלה. וביאור הדבר כי הנה יעקב אמר מה נורא. ולכן מה שאומרים הגדול הגבור והנורא. נורא הוא מדתו של יעקב."],[59,"ולכאורה לא שייך בחי' נורא ליעקב כ\"א לפחד יצחק. אלא לפי שיעקב היה הממוצע בין האבות. ונודע שא\"א שיחוברו ב' הפכים עד שיערה רוח מלמעלה משניהם. כענין עושה שלום במרומיו כו'."],[59,"ולכן מאחר שיעקב היה המחבר לכך היה בו גילוי בחי' נורא שהוא למעלה משניהם. וכך הוא בבחי' אויר שהדקות הוא לפי שהוא בחי' ממוצע שהוא בקו האמצעי חח\"ן מימין. ובג\"ה משמאל."],[59,"וכדת\"י באמצע הוא בחי' אויר שהוא בחי' ז\"א שהוא בקו הממוצע בחי' [ת\"ת] ולכן נק' אויר אור יו\"ד. שהיו\"ד הוא בחי' העלם של האור שמוריד וממשיך להיות האור מאיר. כמו האותיות שהן בבחי' ההעלם."],[59,"ובהן ועל ידן נתפס השכל ובא לידי גילוי כי א\"א לכל שכל בלי אותיות כנ\"ל. כך האויר שהוא בבחי' העלם בו ועל ידו נתפס האור להאיר לבא לידי גילוי. וזהו כי נר מצוה ותורה אור. שע\"י נר מצוה נעשה התורה אור כי המצות עולות עד הכתר ששם שרש המצות תר\"ך עמודי אור עמוד שמחבר מעלה למטה."],[59,"וכענין יעקב חבל נחלתו כשמתנועע החבל למטה כו'. וכך ע\"י המצות שהן במל' עולות בכתר ונמשך משם בחי' אותיות חדשים דהיינו תוס' אור להיות אור התורה מאיר. כי הנה התורה נקראת משל הקדמוני."],[59,"וענין המשל הוא כמ\"ש וידבר שלשת אלפים משל. כי הנה חכמת שלמה היא חכמה תתאה שהיא בחי' מל' דאצי'. והיינו בחי' מל' המאירה בבי\"ע כי מל' דאצי' עצמה היא רוה\"ק ונו\"ה דאצי' היא בחי' נבואה ובאצילות איהו וחיוהי חד. ולכן יש ס\"ר פירושים על כל פסוק מד\"ת ונבואה. וגם משלי ושה\"ש שאמר שלמה ברוה\"ק הן במל' דאצילות עצמה למעלה מחכמת שלמה אבל מה שנתן חכמה לשלמה היא בחי' חכמה תתאה דבריאה ובחכמה זו דיבר על כל דבר מד\"ת שלשת אלפים משל דהיינו רוחניות שבד\"ת מכל הג' עולמות בי\"ע (שכל מה שיש למטה יש למעלה כנודע מאתרוג שלמטה שמעורר למעלה שדוקא אתרוג ולא תפוח. ולקרב אל השכל הוא כמו דבר גשמי המצוייר בדמיון האדם. אך דמיון מחשבת האדם אינה פועלת כלום. אבל למעלה כי לא מחשבותי כו') שהשיג ממדרגה התחתונה דעשיה עד מדרגה הראשונה שבבריאה. וכל עולם יש בו י\"ס וי' כלול מי' עד אלף וזהו שלשת אלפים. אבל באצי' דאיהו וחיוהי חד לא השיג. אבל באמת גם התורה דאצי' היא בחי' משל לגבי המאציל העליון ב\"ה. ⟦מג,ג⟧דאוריית' מתקשרא בקוב\"ה כמו דישראל מתקשראן באוריית' שאין להם ערך לגבי התורה אלא דמתקשראן בה."],[59,"וכך התורה מתקשראת בקוב\"ה כו'. וכדי שיומשך ויתפשט אוא\"ס ב\"ה המאציל בהתורה הוא ע\"י נר מצוה שהיא בחי' אוי\"ר אור י' שהמצות הן בחי' העלאה כמו קרבנות שנעשו מן הבהמות להיות אשה ריח ניחוח. וכן תפלין של קלף מעור הבהמות. וציצית של צמר. והרי זו בחי' העלאה מדבר גשמי להיות התכללות ברוחניות אק\"ב (וגם הם המשכות אך מפני שנעשות ע\"י מעשה האדם בפו\"מ הרי הן העלאות שהאדם מעלה ומקשר אותן לאוא\"ס הנמשך בתוכן משא\"כ התורה היא המשכה לבדה קורא בתורה שקורא וממשיך מה שכבר היה כאדם הקורא לחברו כו') וע\"י העלאה זו נעשה המשכת התורה. וזהו יהא שמו הגדול מבורך כי יש שם הוי\"ה בחי' מל' כי הוי\"ה הוא ז\"א ושמו של הוי\"ה דהיינו הגילוי הוא במל' ושם הגדול הוא בכתר (ופעם אמרו בזוהר דהיינו בבינה והכל א' כי התגלות עתיק בבינה) דהיינו מל' דא\"ק ולכן אומרים מברך לעלם בלשון יחיד שהוא עולם האצי' שהוא רה\"י דאיהו וחיוהי חד לפי ששם הגדול הוא למעלה מהאצילות ונמשך באצי' וזהו הקב\"ה מנענע בראשו. ⟦מג,ד⟧פי' בבחי' כתר שמנענע וממשיך למטה אך דוקא באיש\"ר דאגדתא כי אגדה היא בחי' חכמה שרוב סודות התורה גנוזין בה כמ\"ש האריז\"ל."],[59,"ואיש\"ר אומרים בצבור שאז דוקא מנענע בכל בחי' ראשו משא\"כ אחד העוסק בתורה אע\"פ שהקב\"ה קורא ושונה כנגדו מ\"מ אין המשכה זו רק בחלק נפשו אבל בצבור ממשיכים בחי' כללות כו'."],[59,"ובזה יובן ענין נ\"ח משמאל ומזוזה מימין. מזוזה הוא בחי' המצות שהמזוזה היא בחי' העלא'. שבית האדם וכל מה שבתוכו בטל לה' אחד שכותבין במזוזה אחד ואהבת. כי בכל לבבך הוא בחי' התפלה בלב."],[59,"ובכל נפשך היא בחי' התורה לקשר מחשבה במחשבה ודבור בדבור. ודברי אשר שמתי בפיך. ובכל מאדך היא המזוזה שהיא בסוף ביתו עם כל הרכוש שבתוכו. ועי\"ז נ\"ח משמאל היא תורה אור שהיונים רצו להשכיחם תורתך ותקנו להניחה על פתח הבית מבחוץ לר\"ה. כי המל' נק' פתח הבית שמשמש כניסה ויציאה וכך כתיב בזאת יבא אהרן אל הקדש כו'. וביציאתה לבי\"ע הנה מל' בכל משלה. וצריך להמשיך גם שם בטורי דפרודא. על הרי בתר בחי' אור התורה והיא משמאל בחי' גבורות וזה היה בזמן בית שני כו':"],[60,"⟦מג,ג⟧<b>ויגש אליו יהודה ויאמר בי אדוני וגו'.<\/b> הנה כתיב קורות בתינו ארזים וגו'. והנה י\"ל ההפרש בין המשכן לבית עולמים שהמשכן הי' מארזים כמ\"ש עצי שטים עומדים והמכסה הי' מיריעות עזים ועורות אילים ועורות תחשים כו' והבהמ\"ק הי' מאבנים ועפר דוקא (שאסור לעשות בו עץ בולט ואכסדראות של עץ כמ\"ש הרמב\"ם פ\"א מהל' בית הבחירה וע' בס' החינוך מצוה תצ\"ב) רק שהיו כלונסאות של ארז בתקרת האולם כו' וצ\"ל זה מפני מה במשכן היו הארזים עיקר בבנין והעפר הי' רק בקרקע המשכן למטה. ובמקדש נהפוך הוא שהיו האבנים והעפר העיקר שאפי' הגג הי' מהן ולא היו עצים רק כלונסאות של ארז הנ\"ל שהיו טפלים לעיקר הבנין."],[60,"והענין כי הנה ידוע שיש בכל עולם ד' בחי' דצח\"מ והדומם הוא למטה במדרגה מצומח והצומח למטה מן החי כו' והעילוי שבכולם הוא בחי' המדבר ולכאורה תמוה דא\"כ מפני מה הארץ דוקא תוציא צמחה שהצומח יהי' גדל ונולד ונמשך מעפר הארץ הלא הצומח הוא למעלה מהדומם שהוא העפר. אך הענין דלא ראי זה כראי זה שאע\"פ שהדומם למטה במדרגה מן הצומח עכ\"ז יש בו מעלה יתירה מצד שרשו שלמעלה מבחי' צומח וחי כו'. דהנה ידוע מחלוקת התנאים בגמ' (חגיגה יב.) חד אמר שמים קדמו לארץ כמ\"ש בראשית ברא כו' את השמים ואת הארץ וח\"א ארץ קדמה כמ\"ש ביום עשות כו' ארץ ושמים ואלו ואלו דא\"ח שבמחשבה ארץ קדמה לשמים וכשברא ברא השמים תחלה."],[60,"והענין כי סוף מעשה במח' תחלה פי' כי הארץ לפי שהיא סוף מעשה ע\"כ שרשה במח' היא בבחי' תחלת המחשבה אבל השמים שהם תחלת המעשה הם אחרוני' במחשבה כי זהו הכלל שהסוף מעשה עולה תחלה במחשבה ולכך הצומח למעלה מהדומם וכן החי למעלה מהצומח כו' שזהו כפי סדר ההשתלשלות דדצח\"מ בעולמות שבחי' הדומם ועפר הארץ הוא בחי' סוף מעשה וצומח וחי למעלה ממנו במדרגה והוא ענין שמים קדמו לארץ. ומ\"מ מצד שרשן במחשבה הקדומה הרי ארץ דוקא קדמה לכולם במחשבה. לכן דוקא בה יש הכח והיכולת להוציא צמחה מצד שרשה הנעלה ולכן הצומח והחי והמדבר כולם מקבלים ממנה כו':"],[60,"⟦מג,ד⟧<b>והנה<\/b> במשכן לא היה נמצא עדיין תכלית השלימות שהיה רק דירת עראי של הקב\"ה. כמ\"ש ואהיה מתהלך באהל ובמשכן כו'. לכך נעשה כפי אופן סדר השתלשלות העולמות איך שנבראו כסדרן שבזה שמים קדמו לארץ."],[60,"ולכן כותלי המשכן היו מקרשים שהן בחי' צומח. ורק קרקע המשכן הי' מעפר. שזהו כמו שהוא בהשתלשלות שהצומח למעלה מן הדומם ולכן נעשו הקרשים מארזים שהארז גדל בגובה מאד שזהו בחי' העליונה שבצומח כו' למעלה מעלה מבחי' הדומם שאין בו תוספת וגידול כלל."],[60,"והמכסה על המשכן היה מיריעות ומעורות אילים ותחשים כו' שהוא בחינת החי שלמעלה במדרגה גם מבחי' הצומח. לפיכך היריעות שהם בחי' המקיפים שהיו פרושי' על כותלי המשכן היו מבחי' חי שהוא למעל' מבחי' צומח שממנו נעשו כותלי המשכן. נמצא שכ\"ז נעש' כפי סדר מעלת ומדרגת ההשתלשלות בהשתלשלותן ובריאותן מלמעלמ\"ט שהוא בחי' שמים קדמו כו'. אבל במקדש היה נמצא בו תכלית השלימות כי היה דירת קבע של הקב\"ה כמ\"ש זאת מנוחתי עדי עד שהי' מעין עוה\"ב מה שיהי' באלף השביעי כשיהי' מנוחה לחיי העולמים שאז תתעלה הארץ עליונה שהיא בחי' מל' דאצי' להיות למעלה מכולם."],[60,"וכמ\"ש אשת חיל עט\"ב שתהי' עטרת לע\"ל לז\"א דאצילות. והיינו מצד שרשה שעלתה במחשבה הקדומה תחלה ארץ קדמה לשמים. לכן אף בבהמ\"ק שהי' מעין עוה\"ב נעשה עיקר הבית מאבנים ועפר שהם בחי' דומם שאף הגג והמעזיבה שהיא בחי' המקיף נעשה מאבנים ועפר ולא מארזים שהוא כפי מה שיהיה לע\"ל שבחי' ארץ קדמה א\"ח עט\"ב מצד שרשה כו' רק שכלונסאות של ארז שהיה בהתקרה הם היו בחי' תמכין לבד לעיקר התקרה הנעשה מבחי' דומם וכענין תמכין דאורייתא. (ועמ\"ש במ\"א ע\"פ מחר חדש במ\"ש יהונתן לדוד ואנכי אהיה לך למשנה כו'):"],[60,"<b>והנה<\/b> נראה בעליל ג\"כ בחי' זו שיש בהארץ מעלה יתירה והוא בחי' הבטול שיש בה שהיא מדרס תחת כפות רגלי הכל משא\"כ הצומח שגדלים בגובה והתנשאות כו'. ובטול זה נמשך מצד שרשה הנעלה במחשבה שהמחשבה היא בחי' חשב מ\"ה שהוא תכלית הבטול ⟦מד,א⟧כמ\"ש מרע\"ה ונחנו מ\"ה. ומשם נמשך ומתלבש בחי' הבטול בארץ ומצד זה תתעלה לע\"ל להיות עט\"ב לכן היה בהמ\"ק מאבנים דוקא (וכמ\"ש ג\"כ במ\"א ע\"פ מזמור שיר חנוכת הבית דלכך אמרו בגמרא על כורש שהחמיץ במה שחזר וצוה לערב בחי' צומח בבהמ\"ק נדבכין די אבן גלל תלתא ונדבך די אע חדת כו' כי צ\"ל כולו באבנים דוקא מטעם הנ\"ל. ובתפלה הוא בחי' השתחואות שבשמ\"ע קול דממה דקה. בחי' דומם ואותיות התפלה הם בחינת דומם) משא\"כ בהמשכן שנעשה כפי סדר ההשתלשלות דעכשיו שבחי' צומח למעלה מהדומם שמים קדמו כו' לכן היו הכותלי' מעצי שטים והעפר היה בקרקע המשכן וכנ\"ל:"],[60,"<b>והנה<\/b> זהו ג\"כ ענין יוסף ויהודה. שהוא ג\"כ בחי' ומדרגת שמים וארץ ובחי' צומח ודומם כו'. כי יוסף לשון תוספת ורבוי שמתוסף והולך בהגדלה והגבהה למעלה והוא ענין בחי' צומח ובפרט בחי' הארז שגדל והולך למעלה מעלה ברום המעלות. וכמ\"ש צדיק כתמר יפרח כארז בלבנון ישגה (והיינו בחי' ז\"א דאצי' שנק' צומח לגבי המל' שנק' דומם כמ\"ש במ\"א באריכות שהמדות יש בהם צמיחה וגידול אבל האותיות הן בחי' דומם כו' ובמדות יש בחי' קטנות וגדלות. וזהו בחי' עץ ארז ואזוב שהאזוב הוא בחי' הקטנות והארז בחי' הגדלות כו'. וז\"ש כארז בלבנון ישגה כו' ויוסף בפרט הוא בחי' יסוד שעולה עד הדעת ודעת עולה עד הכתר כו'. וכשמבריח מעלה מעלה נק' ארז בלבנון כו') ויהודה הוא בחי' ארץ מל' דאצילות שהיא בחי' הדומם דאצי'. ולכן יהודה ל' הודאה ובטול שהדומם יש בו בחי' הבטול ביותר כנ\"ל:"],[60,"<b>והנה<\/b> בסדר ההשתלשלות עתה יוסף הוא למעלה מיהודה שהרי המל' מקבלת שפעה וחיותה מן הז\"א ולכן יוסף היה המלך במצרים שהוא בחי' צומח בחי' גידול והתנשאות והוא היה המשביר והמשפיע לכולם."],[60,"ויהודה הוא המקבל. וז\"ש ויגש אליו יהודה ויאמר בי אדני. פי' שבו יומשך השפע מיוסף הצדיק וכמבואר בזוהר דויגש היינו תקרובתא עלמא בעלמא. דהיינו עלמא תתאה בחי' מל' מתייחדת ונגשת לגבי עלמא עלאה בחי' ז\"א לקבל השפע כו'. וזהו ע\"ד שהיה במשכן הצומח למעלה מהדומם כנ\"ל. אבל לע\"ל יתעלה יהודה להיות למעלה מבחי' יוסף כמ\"ש א\"ח עט\"ב מצד שרשו שעלה במחשבה תחלה כנ\"ל. כי הנה מחשבה הוא חשב מ\"ה דהיינו תכלית הבטול שהוא בחי' חכ' דאצי' כח מ\"ה."],[60,"והנה אבא יסד ברתא כי ח\"ע נק' ירא' עלאה. וח\"ת שהיא המל' היא יראה תתא' וזהו אבא יסד ברתא שמבחי' יראה עלא' דחכ' נמשכ' המל' יראה תתאה. ולע\"ל תתעלה בחי' יראה תתאה ביראה עלאה מקורה ע\"כ תהי' אז עט\"ב כי הבטול הוא למעלה במדרגה מאהוי\"ר דמדות הנמשכי' מבחי' חו\"ג דז\"א. ולכך גם עכשיו יש בהארץ בחי' הבטול יותר וכנ\"ל. ובחי' בטול דיראה עלאה היא בחינת ומדרגת משרע\"ה ונחנו מה כו' (וע' לקמן ע\"פ יהודה אתה ומ\"ש ע\"פ מאמר הזהר פ' אמור ע\"פ וגם אמנה אחותי בת אבי כו' מענין בחכמה יסד ארץ כונן שמים בתבונה. ועמש\"ל פ' בראשית ד\"ה להבין הטעם שנשתנה יצירת):"],[60,"<b>וזהו<\/b> מ\"ש בהפטרה דפ' ויגש קח לך עץ אחד וכתוב עליו ליהודה כו' ולקח עץ אחד וכתוב עליו ליוסף עץ אפרים כו' וקרב אותם אחד אל אחד כו' הנה אני לוקח את עץ יוסף כו' ונתתי אותם עליו את עץ יהודה כו'. עד ועבדי דוד מלך עליהם. פי' כי עתה יוסף הוא למעלה מיהודה שהוא נמשל לארז אשר גדל ⟦מד,ב⟧בגובה ומתוסף והולך. כך יוסף אליו שייכים עשרת השבטים. כמ\"ש שם ושבטי ישראל חביריו נמצא הוא מרובה בשבטים יותר מיהודה. שע\"ש זה נק' יוסף כי הוא הדעת עליון כו'. אך לעתיד לבא כשיתחברו שניהם יוסף ויהודה ביחד בתכלית היחוד האמיתי דהיינו מ\"ש ויגש אליו יהודה וכמ\"ש (איוב מ\"א) אחד באחד יגשו וזה יהיה לע\"ל אז יתעלה יהודה למעלה מיוסף כנ\"ל ע\"פ א\"ח עט\"ב. ולכן אז ועבדי דוד מלך על כל ישראל. וז\"ש ולא יכול יוסף להתאפק כו' בהתודע יוסף אל אחיו דהיינו שנתחברו יוסף ויהודה בתכלית החבור והיחוד למיהוי אחד באחד כו'. (וע' ע\"פ והיה מספר בנ\"י כו' בענין ונקבצו בני יהודה ובני ישראל יחדו ושמו להם ראש אחד כו'. וע' בדרוש ברכת הזמון בענין שדהע\"ה יברך על כוס יין המשומר שלע\"ל כו' וע' ע\"פ מחר חדש בענין יהונתן ודוד:) <b>ובכל<\/b> הנ\"ל יובן ויבואר מ\"ש בלקוטי הש\"ס מהאר\"י ז\"ל בביאור מארז\"ל בחלק (דק\"ב סע\"א) שתפשו הקב\"ה לירבעם בן נבט ואמר לו חזור בך כו' א\"ל מי בראש א\"ל בן ישי בראש א\"ל אי הכי לא בעינא. שהוא ממש הענין הנ\"ל שהקב\"ה רצה שירבעם יחזור בתשובה ואז יאיר בו מבחי' ומדרגת יוסף בחי' עץ אפרים כו'."],[60,"וזהו אני ואתה ובן ישי נטייל בג\"ע שיהי' מאיר בהם א\"ס ב\"ה בהאר' רבה. וזהו אנ\"י כו' א\"ל מי בראש כי הוא רצה כמו שהיה עכשיו שבחינת ומדרגת יוסף הוא למעלה מבחי' יהודה לכך רצה הוא להיות בראש לגבי דוד אבל הקב\"ה אמר לו שלע\"ל יתעלה יהודה לכן בן ישי בראש כו' א\"ל אי הכי לא בעינא שלא היה בו בחי' בטול ושפלות זה."],[60,"וזשארז\"ל גסות הרוח שבירבעם טרדתו כו'. ומעין זה נתבאר ג\"כ במ\"א בענין המרגלים שלא היה בהם ג\"כ שפלות זו לגבי בחי' ארץ העליונה שדימו בעצמם שא\"צ לזה להיותן מעלמא דדכורא כולם אנשים כו'. אבל יוסף הצדיק ויהודה יתחברו לע\"ל בתכלית היחוד למיהוי אחד באחד כנ\"ל:"],[61,"<b>וילקט יוסף את כל הכסף הנמצא בארץ מצרים ויבא יוסף את הכסף ביתה פרעה.<\/b> הנה ארז\"ל שלש מטמוניות הטמין יוסף. אחת נתגלה לקרח ואחת נגלה לאנטונינוס. ואחת גנוזה לצדיקים לע\"ל. ולהבין זה הנה כתיב אור זרוע לצדיק וידוע דהיינו בחי' אור קדמאה דהוה נהיר מסייפי עלמא עד סייפי עלמא דגניז קוב\"ה לצדיקייא."],[61,"וענין הגניזה הזאת יובן דהנה בעבודת ה' ימצא ב' בחי' ומדרגות באהבת ה'. הא' הוא בחי' האהבה הנולדת ונמשכת מן ההתבוננות בגדולת אוא\"ס ב\"ה כשיעמיק בשכלו ברוממות גדולתו ית' יולד מזה התפעלות בתשוקה והתלהבות אליו ית' כי לפי שכלו יהולל איש שהמדות נמשכים אחר השכל וההתבוננות. אהבה זו היא בחי' הולדה חדשה שנמצאת מחדש ע\"י השכל וההתבוננות."],[61,"ויש בחי' ב' באהבה והוא הנק' אהבה מסותרת שהיא האהבה שיש בטבע תולדת הנפש האלקית שהיא חפצה בטבעה להתכלל בא\"ס ב\"ה שהוא מקורה ושרשה אלא שהיא אצלו בחי' העלם והסתר גדול ויציאתה אל הגלוי הוא ע\"י התבוננות כמ\"ש בתניא ונמצא כשיוצאת אל הגלוי ע\"י ההתבוננות אין זו הולדה חדשה מן השכל ממש שממנו נולדה האהבה שהרי אהבה זו כבר היתה מתחלה בנפש' רק שהיתה בהעלם וע\"י ההתבוננות יצתה מן ההעלם אל הגילוי."],[61,"וזהו ענין מארז\"ל נכנס יין יצא סוד. פי' סוד הוא בחי' אהבה מוסתרת הנ\"ל ויציאת' אל הגלוי הוא ע\"י ההתבוננות הנק' בשם יין יינה של תורה כו'. ובאמת מעלת ומדרגת אהבה זו המסותרת היא גדולה ורבה מבחי' האהבה ⟦מד,ג⟧הנולד' מהתבוננות הנ\"ל. אף שזו היא הולדה חדשה וזו אינה התחדשות גמורה אעפ\"כ שרשה נעלה יותר כו' ואהבה הנולדה מהתבוננות היא למטה ממנה במדרגה רק שלא נשפלה כ\"כ כמו אהבה הנ\"ל המסותרת כו' (וכמ\"ש בתניא שבחי' אהבה מסותרת כשיוצאה אל הגלוי נק' אה\"ר שלמעלה מאהבת עולם שמבחי' ההתבוננות כו' וע' מ\"ש לקמן ע\"פ חכלילי מענין אה\"ר ואה\"ע). והנה בחי' ומדרגת יוסף הצדיק עליון הוא בחי' אה\"ר המסותרת שיש בכל נפש מישראל ששרשה גבוה מאד נעלה שזהו בחי' יוסף שהוא בחי' יסוד דהיינו בחי' י' סוד כו'. וזהו פי' אור זרוע לצדיק שהוא בחי' אור קדמאה שגנזו לצדיקים. ואור קדמאה הוא בחי' אה\"ר הנ\"ל שהיא למעלה מעלה מבחי' אה\"ע הנק' ג\"כ אור (כי אור הוא בחי' חסד ויש חסד עולם והוא בחי' האהבה הנמשכת מן השכל אבל אור קדמאה הוא בחי' אה\"ר שלמעלה מהשכל ונלקחה מבחי' ורב חסד וחסדי מאתך לא ימוש כו') אלא שגנזו לצדיקים בבחי' יוסף צ\"ע וממנו נזרע בכל א' מישראל בחי' אהבה הנ\"ל אלא שהיא מסותרת בבחי' גניזה וסוד והעלם ונכנס יין יצא סוד כנ\"ל:"],[61,"<b>ועפי\"ז<\/b> יובן ג\"כ מ\"ש בזהר תרומה (דקס\"ו ע\"ב ודקס\"ז ע\"א) האי אור זרע לי' קוב\"ה בגינתא דעדנוי ע\"י דהאי צדיק דאיהו גננא דגינתא ונטל להאי אור וזרע ליה זריעה דקשוט כו' ובגלותא גנתא לא עאל ביה גננא. וההוא אור דאיהו זרוע תדיר עביד איבין ומינין ומגרמיה אזדרע כקדמיתא. ופי' גנתא הוא בחי' המשכת הקו\"ח ממל' דא\"ס שהוא ראשית הקו עד סיומו נק' הכל בחי' גנתא שהוא בחי' מל'. (ע' במק\"מ בזהר פ' בא ד' ל\"ה ע\"א בשם הרח\"ו בפי' בחד צדיק כו'. דזרע בגנתא כו' ע\"ש) וכמארז\"ל מה הגן צריך לעדור ולהשקות ולזמור שהוא בחי' עבודת הבירורים שזה נעשה ע\"י יוסף הצדיק. והנה כמו בארץ הגשמית יש ב' מיני צמיחה הא' התבואות הנזרעים מדי שנה ועולים וצומחים."],[61,"והב' הם הנק' ספיחין דהיינו מה שצומח מאיליה שלא נזרע עכשיו כלל אלא מן הזריעה שנפל בה מכבר כו'. והם הנק' ספיחא דארעא דמקיימי ארעא שעיקר קיום הארץ הוא ע\"י הספיחין."],[61,"וכך נמצא למעלה בארץ העליונה הנקרא גנתא ב' בחי' ומדרגות אלו דהיינו בחי' המשכות הנמשכות בה בבחי' זריעה כמ\"ש אור זרוע כו' ויש בחי' שגדילים בה מבחי' ספיחין דהיינו ממה שנזרע כבר כו' והספיחים אף שאין זה ענין התהוות והמשכה חדשה ממש רק שהוא בחי' גידול ממה שהיה בהעלם בהארץ עכ\"ז יש בו מעלה יתירה ששרשו גבוה ביותר והוא כנ\"ל בענין האהבה המסותרת כשיוצאת אל הגלוי הגם שאינו התהוות חדשה כמו האהבה הנולדה מההתבוננות עכ\"ז שרשה גבוה יותר כו' ובחי' גלוי אהבה המסותרת זהו ענין הספיחים שהארץ מוציאה צמחה מעצמה. ומגרמיה אזדרע דהיינו מאותה האהבה שנזרע בה כבר שהיתה מסותרת כו' וזהו בחי' אור זרוע כו' (שנזרע כבר בנפש האלקית אבל האהבה הנולדת ונמשכת מההתבוננות הנק' אהבת עולם הוא כמשל הזריעה שזורעים עכשיו מחדש) וכל זריעות אהבות אלו הכל הוא מבחי' יוסף הצדיק שנק' גננא דגנתא שממנו נמשך האור בבחי' מל' הנק' גנתא (שהוא מקור נש\"י):"],[61,"<b>וזהו<\/b> ענין וילקט יוסף את כל הכסף כו' שהוא בחי' חסדים שכולם נמשכים בבחינת יוסף הצדיק וכנ\"ל בענין אור קדמאה דגנזי' לצדיקים שהוא נמשך בבחי' יוסף הנק' צ\"ע והוא ⟦מד,ד⟧גננא דגנתא שממנו נמשך בחי' אהבה מסותרת הנ\"ל בכ\"א מישראל. וזהו ויבא ביתה פרעה הוא בחי' המלכות הנק' גנתא ועלמא דאתגליא שהוא מקור נש\"י. וזהו ענין שלש מטמוניות הטמין יוסף כו'. דהנה ידוע בכתבי האר\"י ז\"ל שהחסד (מה\"ח הנמשכים בז\"א והחסד שבת\"ת) מתחלק לג' פרקין היינו השליש העליון הוא בבחי' העלם והסתר ונק' חסדים מכוסים וב' שלישי' מתגלין. והיינו ענין ג' מטמוניות הנ\"ל ששנים נתגלו שהם ב' שלישים המתגלים. והשליש עליון שהוא בחינת חב\"ד שבו הוא מכוסה ונעלם ויתגלה לצדיקים לע\"ל וכמ\"ש אור זרוע לצדיק והיינו ענין בחי' אור קדמאה שגנזו לצדיקים כו' וכל זה הטמין יוסף שהוא בחינת יסוד שבו נמשכים החסדים הנ\"ל. וכנודע לי\"ח (אפ\"ל ג\"כ דחסדים מכוסים ומגולים הם בחי' אה\"ר ואה\"ע הנ\"ל. וזהו וילקט יוסף את כל הכסף הן חסדים המכוסים הן המגולים. והכל הביא ביתה פרעה שמתגלים ביחוד זו\"נ. עוד י\"ל פרעה ל' פריעה שע\"י פריעה מתגלים ג' פרקי החסד כנז' בע\"ח והכל א'. ועמ\"ש בזהר בלק )(ד' ר\"ד) בענין בקר דיוסף דלשם מבואר ג\"כ דאור קדמאה הנ\"ל נמשך בבחי' יוסף ודוד אתקין לי' חופאה כמ\"ש בקר אערך לך ואצפה. והוא ענין וילקט יוסף את הכסף ויבא ביתה פרעה והמ\"י. ועמ\"ש במ\"א ע\"פ וימינך מקרב חיקך כלה דהענין שיתגלו החסדים מכיסויים יסוד דאימא כו'. ואפ\"ל ג\"כ דפי' כסף הנמצא באמ\"צ הם חסדים מכוסים ובארץ כנען הם חסדים מגולים:"],[62,"ביאור על הנ\"ל"],[62,"<b>ולתוספת<\/b> ביאור במש\"ל ע\"פ ויגש כו'. בענין שלעתיד יהיה עליית המלכות למעלה מז\"א כו'. יובן ממ\"ש בברכה אחרונה דנשואין מהרה ה' אלהינו ישמע בערי יהודה ובחוצות ירושלים כו'. בא\"י משמח חתן עם הכלה."],[62,"וצ\"ל הטעם לשינוי לשון הברכות. שמתחלה אמר משמח חתן וכלה ואח\"כ אמר עם הכלה. וגם צריך להבין ענין קול חתן וקול כלה. והענין הוא מ\"ש משמח חתן וכלה קאי אזמן הזה."],[62,"ומ\"ש עם הכלה קאי אלעתיד דהיינו אחר שכבר אמר מהרה ישמע דהיינו בביאת הגואל אז אח\"כ אומר עם הכלה. ולהבין הטעם מפני מה אמר על לעתיד דוקא עם הכלה. הענין כי יש אירוסין ונשואין. כי בזה\"ז הוא בחינת אירוסין כמ\"ש תורה צוה לנו משה מורשה. א\"ת מורשה אלא מאורשה."],[62,"וכמ\"ש ביום חתונתו זה מ\"ת בחי' אירוסין כי במ\"ת אף שהיה גילוי פב\"פ היינו רק בבחי' חיצוני' בלבד באיסור והיתר אבל פנימית התורה שהוא בחי' ענג האלהי שבתורה לא נתגלה אז עדיין ונשאר בבחי' מקיף מלמעלה וה\"ז דומה לבחי' אירוסין שגם שם אינו נמשך עדיין בבחינת פנימית רק הארה חיצוני' וכל עיקר האור בבחינת מקיף כמו טבעת קדושין שהוא עגול ומקיף ע\"ג היד אבל לעתיד שיהיה בחי' גילוי פנימי' התורה שהוא ענג העליון שבתורה אז יהיה בבחי' נשואין כי בועליך עושיך האשה נקנית כו' כי ענין נשואין הוא ג\"כ אחרי שכבר בא האור בבחי' פנימית:"],[62,"<b>והנה<\/b> ידוע דכעת בגלות המל' מקבלת האור ע\"י ז\"א שהוא מקבל בעצמו מאימא. וכמ\"ש בעטרה שעטרה לו אמו והוא משפיע אח\"כ למל' אבל לעתיד נאמר א\"ח עט\"ב שתהיה המל' עט\"ב ז\"א שתתעלה יותר למעלה הימנו כי נעוץ סופן בתחלתן כו'."],[62,"וזהו הטעם למשארז\"ל עתידים צדיקים שיאמרו ⟦מה,א⟧לפניהם קדוש. ולכן עתה בזה\"ז נאמר משמח חתן וכלה שהכלה היא המל' מקבלת האור ע\"י החתן ז\"א. ולעתיד אחרי שכבר תתעלה אז נאמר משמח חתן עם הכלה שעל ידי הכלה הוא משמח את החתן מפני שא\"ח היא עט\"ב כנ\"ל וז\"ש מהרה ישמע כו' קול כלה כו'. כי עתה בגלות נאמר נאלמתי דומיה שהיא בחי' שתיקה וכאלם לא ⟦מה,ב⟧יפתח פיו כו' ולכך החתן הוא אומר הרי את מקודשת לי והכלה שותקת אבל לעתיד כשתתעלה מעלה מעלה אז תהיה ג\"כ משפעת ונק' קול כלה."],[62,"וכמו\"כ יובן ענין שמו\"ע צלותא בחשאי הוא רק בזה\"ז שהנוק' היא בחי' מקבל ולא משפיע. אבל לעתיד כשתתעלה להיות בבחי' משפיע כמו הדכר עצמו אז יהיה שמו\"ע בקול רם ויהיה קול כלה וד\"ל:"],[63,"⟦מה,א⟧<b>יהודה אתה יודוך אחיך וגו'.<\/b> הנה יהודה נקרא ע\"ש הפעם אודה והוא בחי' הודי' שבכללות נש\"י מודים אנחנו לך ואנחנו כורעים ומשתחוים ומודים. אלא שלמטה לפי שהוא תחת הזמן נק' הפעם אודה שלא כל העתים שוות. אבל למעלה במקור חוצב נשמותיהם הוא למעלה מן הזמן ושם נק' יהודה כי היו\"ד מורה על ההוה כמו ככה יעשה איוב. ויהי' פי' המלה כמו יודה בתוס' ה' יהודה ((ובנחמי' י\"א) נכתב יהודה בסגול תחת הדל\"ת) וענין הפעם אודה היינו אחר לידה והתגלות בחי' ראובן שמעון ולוי שהם הם הגורמים לבחי' הודיה זו. וזהו יודוך אחיך. וביאור ענין זה הנה ראובן הוא ע\"ש ראו בן בחי' ראיה ובחי' ראיה זו היא הגורמת המשכת בחי' האהבה. כמ\"ש פני אריה אל הימין אריה אותיות ראיה וכן היה דגל מחנה ראובן תימנה כי ענין ראיה הוא ענין התקרבות דרך חיבה כמ\"ש כבכורה בתאנה בראשיתה ראיתי אבותיכם כו'."],[63,"וזהו כי ראה ה' וגו'. כי עתה יאהבני אישי וגו'. וענין המשכה זו בכנ\"י הוא בחי' לאסתכלא ביקרא דמלכא לעורר את האהבה עד שתחפץ לדבקה בו ית' ועד\"ז נתקנו פסוד\"ז ויוצר אור קודם ק\"ש כדי שיבוא לקיום ואהבת בק\"ש. כי עיקר הכוונה בספור שבחו של מקום הוא כי לא די בידיעה לבדה לפי שהיא בחי' העלם ואפי' גנבא אפום מחתרתא וכו' ולא יבוא לקיום ואהבת כ\"א כשיצא מההעלם אל הגלוי ומבחי' ידיעה לבחי' ראיה ממש שהוא בחי' גילוי לאסתכלא דוקא והיינו ע\"י שירבה לספר בשבחיו יתברך ולהעמיק דעתו איך שמלכותך מלכות כל עולמים. אלף אלפים ורבו רבבן כו' והוא לבדו ית' הוא יחיד ומיוחד כמו קודם שנברא העולם. כמאמר יחיד חי העולמים מלך כו'."],[63,"ואמתות שם יחיד הוא שהוא לבדו הוא וענין אחד הוא שנמשך בחי' א' בחי\"ת וד' שהם ז' רקיעים והארץ כו' שיהיו בטלים ליחודו ית' שהחיות של שמים וארץ עולה ונכלל במקורו וכך עולה אפילו החיות של הרוחניות כמ\"ש לך ה' הגדולה וכו' (ועיין מזה על פסוק וארא אל אברהם) ורק בשכמל\"ו שלהיות עולמות נפרדים הם רק מבחי' מלכותו ית'. וכשיאריך בענין זה בעומק בינתו בבחי' גילוי במוחו ולא בידיעה לבדה אזי מוליד מזה אהבה בהתגלות לבו להיות נכספה וגם כלתה נפשי וגו' ויבא לקיום ואהבת את ה' אלקיך ממש דהיינו לדבקה בו בא\"ס ב\"ה ממש וכמ\"ש מי לי בשמים כו':"],[63,"<b>והנה<\/b> כתיב בכל לבבך ואמרו רז\"ל בשני יצריך דהיינו שתהא האהבה בבחי' בעל תשובה כי התשובה אינו דוקא במי שיש בידו עבירות ח\"ו. אלא אפי' בכל אדם כי ענין תשובה הוא להשיב את הנשמה למקורה ושרשה שהיתה כלולה במאצילה ב\"ה וצרורה בצרור החיים את ה' ממש וירדה ממקום כבודה ונתלבשה בעוה\"ז הגשמי שאפילו כל השגות הרוחניים שמשגת ⟦מה,ב⟧בהתלבשותה בתוך הגוף הם נופלים תחת בחינת זמן ומקום וצריך להשיבה ע\"י ויצעקו אל ה' בצר להם כי צר לו המקום שהוא בחי' מצר וגבול ועל זה נאמר אשר הוצאתי אתכם מארץ מצרים מבחי' מצר כו' שע\"י המרירות אשר יהיה לו על ההיפוך תגדל האהבה לה' ביתר שאת להתכלל באוא\"ס ב\"ה כיתרון האור הבא מן החשך."],[63,"וע\"ז אמרז\"ל במקום שבע\"ת כו'. וכדאי' בזהר דמשכין ליה בחילא יתיר להיות גילוי אור א\"ס ב\"ה ממש על נפשו עד שגם חיות הגוף ונפש הבהמית וכחותיהם יתהפכו וישובו אל ה' ואתהפכא חשוכא לנהורא."],[63,"וזהו כי ראה ה' בעניי פי' שע\"י עניי ומרודי הוא מרירות הנפש שבאתעדל\"ת נמשך להיות אתעדל\"ע וכמים הפנים כו' יתרון האור בבחי' ראיה מלמעלמ\"ט כי יאהבני בבחי' אישי דהיינו כמ\"ש ביום ההוא תקראי לי אישי. ופי' אישי אש שלי ממש והיינו התשוקה שממטה למעלה בחי' ואל אישך תשוקתך שהוא הוא האש שלי תהיה בבחי' התכללות באוא\"ס ב\"ה ממש עד שהוא הוא יהיה אישי אש שלי ממש כי וימינו תחבקני בבחי' חבוק והתכללות להיות גילוי אוא\"ס ב\"ה ממש על נפשי בתשוקה זו:"],[63,"<b>והנה<\/b> זהו ענין ראובן שהוא ענין בחי' פ' ראשונה שבק\"ש שהוא בחי' רצוא. ופ' שניה שבק\"ש היא בחי' שמעון והיה אם שמוע תשמעו שהיא בחי' שוב כי ראיה היא מקרוב והיינו בחינת אהבה שמחמת הקירוב. אבל שמיעה היא מרחוק והיא הגורמת בחינת יראה וכמ\"ש ה' שמעתי שמעך יראתי כי היראה היא באה מחמת בחי' הריחוק הנמשך מבחי' שמאל דוחה. כי לפי שהוא דוחה ומשפיל עצמו לומר לנפשו מי הוא אשר ערב לבו לגשת כו' אזי תפול עליו יראה ופחד בלבו וכמ\"ש וירא העם וינועו ויעמדו מרחוק שבשביל וינועו שנפל עליהם אימה ופחד ולפיכך ויעמדו מרחוק בבחי' שמיעה וכענין אם רץ לבך שוב לאחד."],[63,"וזהו ענין פ' שניה שבק\"ש שהוא בחי' יראה כמ\"ש השמרו לכם פן יפתה כו'. וז\"ש כי שמע ה' כי שנואה אנכי וכענין נבזה בעיניו נמאס דהיינו שע\"י אתעדל\"ת מה שנחשב בעיניו לשנואה ע\"י שמאל דוחה נמשך להיות אתעדל\"ע כי שמע ה' בחי' שמיעה מרחוק כדי להמשיך בחי' יראה מלמעלה (ובזה יובן ענין שמע והא\"ש שהן חו\"ג והשמות מ\"ב וע\"ב אלא שהוא התכללות כי שמע חסד אהבה ראובן וכלול גם כן מגבורה בחי' ראה בעניי הנ\"ל וכן והא\"ש יראה כלול מאהבה) (עיין ביאור זה ע\"פ אלה מסעי וע\"פ ויחי). והנה אחר ק\"ש אומרים אמת ויציב וכו' ונחמד ונעים ונורא וכו' הדבר הזה עלינו והיינו בחי' לוי ילוה אישי אלי. והוא ענין ימינא ושמאלא ובינייהו כלה כי שמאלו תחת לראשי בחי' שמאל דוחה הוא שגורמת להיות נשיאות ראש וכו' וימינו תחבקני ימין מקרבת להתכלל כו'."],[63,"ובחי' ילוה אישי היינו מה ⟦מה,ג⟧שאומרים באמוי\"צ הדבר הזה היא התורה ששרשה מאד נעלה אלא שנתלבשה בדברים גשמיים שלכן נמשלה התורה למים שיורדים ממקום גבוה וכו'. וזאת ישיב אל לבו אמת הוא שאין אני ראוי מצד עצמי לעלות ולהתכלל באור ה' ולהשיב את הנפש ממטה למעלה לייחדה במאצילה ב\"ה כי מי יעלה בהר ה' כו' אבל מ\"מ הרי אא\"ס ב\"ה מצד עצמו ממילא ומאיליו נמשך גם למטה ששורה ומתגלה בתורה והרי מתגלה יחוד זה העליון למטה כמו למעלה ואי לזאת ע\"י עסק התורה יכול להמשיך אא\"ס ב\"ה ממש למטה על נפשו וזהו אם רץ לבך שוב לאחד שגם למטה בבחי' שוב נמשך בחי' אחד וזהו ילוה אישי אלי שיורד ונמשך אא\"ס ב\"ה מלמעלה למטה."],[63,"וזהו פי' אמוי\"צ כו' שמאריכין לאשר ולקיים את הדבר הזה עלינו ועל אבותינו כו' על הראשונים כו' וממשיכים מלמעלה אמת ויציב ונכון וכו' ונחמד ונעים כו' להיות המשכת אור א\"ס ב\"ה שורה ומתגלה באור תורה:"],[63,"<b>אך<\/b> הנה כל ג' בחי' הנ\"ל עדיין הם בבחי' ממכ\"ע שהם בחי' המשכות מאא\"ס ב\"ה לבחינת ממכ\"ע שבחי' ראובן היא לעורר את האהבה להיות נכספה וגם כלתה כו' ולהיות משתוקק' להתכלל ולהתייחד במאצילה ב\"ה מכלל שהיא עדיין אינה כלולה ומיוחדת באא\"ס ב\"ה הסוכ\"ע (בשמים ממעל ועל הארץ מתחת הכל בשוה ורוחניות וגשמיות כולא קמיה כלא ממש חשיבי) ועד\"ז שאר הבחי' אלא שהן בחי' המשכות להיות ממכ\"ע כו'. אבל בחי' יהודה שהוא בחי' הודאה הוא בחי' בטול והתכללות באא\"ס ב\"ה ממש הסוכ\"ע והן הן בחינות השתחואות שבתפלת שמ\"ע."],[63,"ולכן תפילה היא בלחש ובחשאי בבחי' סוכ\"ע למעלה מעלה מבחי' השתלשלות שאינה בגדר המשכה והשפעה כלל כו' ואינה עולה בשם אהבה כלל רק בחי' ביטול במציאות ממש לגמרי והיינו בחי' השתפכות אל חיק אביה ממש להיות כאין ואפס ממש שע\"ז מרמז ענין ההשתחואה כמו שמשתחוה לפני המלך שמבטל א\"ע כו' רק שכדי להיות בחי' זו שהוא בחי' יהודה בבחי' אתה דהיינו להיות בגילוי כאילו הוא לנוכח צ\"ל יודוך אחיך שצריך להקדים תחילה בחי' ראובן ושמעון ולוי שבהם ועל ידם יומשך גילוי בחי' הודאה זו כי בלי קדימת בחי' ראובן שמעון ולוי לא נמשך בחי' יהודה שהוא בחינת ביטול והתכללות כו' בבחי' גילוי אלא בבחי' העלם ומקיף. ולכן א\"א להתחיל תפילת ש\"ע בלי קדימת פסוד\"ז ויוצר אור וק\"ש כו' (ובמנחה שמתפללין רק תפילת ש\"ע היינו מפני שכבר הקדימו בשחרית ק\"ש וברכותיה. ובערבית צריך לחזור להתחיל ק\"ש וברכותיה קודם התפלה). וזהו ענין נעוץ תחלתן בסופן והמ\"י (וע' במ\"א ע\"פ ולשרקה בני אתונו דמשמע דשור\"ק שהוא הודאה הוא למטה מסגו\"ל שהוא בחי' אהוי\"ר כו'. וזהו לכאורה הפך ממ\"ש כאן דיהודה שהוא הודאה הוא למעלה מראובן שמעון ולוי שהם סגו\"ל. ובאמת לק\"מ דהודאה היא למטה מאהוי\"ר אבל הודאה דיהודה זהו בחי' בטול שלמעלה מאהוי\"ר וזה בחי' דוד אם לא שויתי ודוממתי וכמ\"ש ואחר האש קול דממה דקה הרי שהדממה והביטול הוא למעלה מהאש שהיא אהבה כי תמן קאתי מלכא אבל גבי אש כתיב לא באש הוי\"ה אלא שהאש הוא להוי\"ה כמ\"ש במ\"א. ועוד דזהו שאמר כאן יהודה אתה שיהיה יהודה בבחי' אתה דהיינו בבחי' גילוי כו' ולפעמים אינו בגילוי כ\"א רק בהעלם ואז היא הודאה שלמטה מאהוי\"ר. אבל כשההודאה בבחי' גילוי זהו בחי' ביטול ממש):"],[63,"⟦מה,ד⟧<b>והנה<\/b> עי\"ז ידך בעורף אויביך. אויביך הם עניני העולם וצרכי הגוף הגשמי. הגם שאדם צריך להם מ\"מ צריכין להיות בבחי' עורף ולא פנים (בחי' פנים היינו שעושה הדבר בלב ונפש ובחי' עורף היינו בחי' אחוריים כמאן דשדי בתר כתפי' בע\"כ וכאלו כפאו וכו'). וידך הוא בעורף אויביך א\"ת ידך אלא יודי\"ך והוא בחי' ידך ממש כי ימינך פשוטה לקבל שבים הוא בחי' ימין וחסד שנתפשט למטה מטה וכענין וירא ישראל את היד הגדולה אשר עשה ה' במצרים כי הנה הירידה הגדולה הזאת שהוא בבחי' אחוריים וכאלו כפאו. מי גרם להמשיך את האדם להיות מוכרח לזה ודאי מאת ה' ומידו היתה זאת כדי לאתהפכא חשוכא לנהורא שיתפלל בכח האכילה וכו' וכיוצא בזה רק שצריך שלא יומשך בבחי' פנימיות אלא בבחי' עורף ובחינת עורף זה יוכלל בבחי' ידך יודי\"ך."],[63,"והוא בחי' ידך של יהודה כו' לפי שהוא בחי' הודאה וביטול בבחי' סוכ\"ע השוה ומשוה כו' גם חשך לא יחשיך וכחשיכה כאורה גשמיות ורוחניות שוין שהרי כולם בחכ' עשית שהחכמה היא עשיה גשמיות וא\"כ גם האכילה ושארי ענינים הגשמיים הם לפניו ית' כמו רוחניות של חכמה מאחר שגם החכמה היא גשמיות וכו'. וזאת היא מעלת יהודה אתה היינו בחי' הודאה בגילוי שבתפלה שתהי' ידך בעורף אויביך בשעה שעוסק בעורף אויביך ואזי חולפת ועוברת ממנו האהבה מ\"מ נשאר רשימו וכו' אך היינו דוקא בבחי' עורף ולא פנים:"],[63,"<b>אך<\/b> עיקר הגורם לכל מעלת בחי' זו להיות יהודה אתה והגורם להיות יודוך אחיך ע\"ז נאמר ישתחוו לך בני אביך כי הנה ההשתחוואה הוא בחי' המשכה וזהו ענין ההשתחוואו' שבשמ\"ע שהן הן המשכות (ע' ר\"פ וישב והנה השמש וכו' משתחוי' לי) ובחי' אביך היינו בחי' כרחם אב על בנים אבינו אב הרחמן שהרחמנות הוא בחי' אב ותולדות הרחמנות הוא בחי' צדקה וחסד להחיו' רוח שפלים שכל העושה חסד במדה\"ר לרחם על עניים ויתומים ה\"ז בבחי' בני אביך. גם בחי' אביך היא התורה דאורייתא מחכמה נפקת שהוא בחי' אב וכמ\"ש שמע בני מוסר אביך זו תושב\"כ וכו' ובני אביך הם העוסקים בתורה וזהו וישתחוו לך בני אביך שבני אביך הם העוסקים בתורה ובגמ\"ח הם הם ישתחוו לך וימשיכו אותך להיות נעוץ תחב\"ס שהתורה והגמ\"ח הם הנותנים כח בנפש לעורר את האוי\"ר עד שתהי' בחי' הודאה וביטול וע\"י כן יודוך אחיך להיות יהודה אתה כנ\"ל:"],[64,"ביאור על הנ\"ל"],[64,"<b>הנה<\/b> השבטים הם ב' בחי' מלמטה למעלה ומלמעלה למטה עלמא דנוקבא ועלמא דדכורא (וכמש\"ל ע\"פ והנה אנחנו מאלמים אלומים שנשמות השבטים נמשכו מבריאה והן בבחי' מלמטה למעלה לעלו' מברי' לאצי' ושרשן הן י\"ב גבולי אלכסון שבז\"א דאצי' שנק' שבטי י\"ה שנמשכים מלמעלה למטה). והנה באתערותא דלתתא אתערותא דלעילא שע\"י בחי' ראובן שמלמטה למעלה ממשיך גילוי בחי' ראובן שמלמעלה למטה והוא כי בחי' ראובן הוא בחי' ראו ב\"ן בחי' ראיה אותיות ארי\"ה ומלמטה למעלה הוא בחי' לאסתכלא ביקרא דמלכא שמזה נמשך תוקף האהבה בחי' פני ארי' אל הימין וכו' ועי\"ז נמשך ג\"כ אתעדל\"ע מלמעלה למטה גלוי בחי' ראיה עליונה כי ראה ה' בעניי בחי' התקרבות כי עתה יאהבני אישי."],[64,"וימינו תחבקני. וכמו\"כ ע\"י בחי' שמעון שמלמטה למעלה אם שמע תשמעו מעורר בחי' אתעדל\"ע כי שמע ה' כו' וענין ראי' היא מקרוב ושמיע' היא מרחוק כמ\"ש ⟦מו,א⟧ה' שמעתי שמעך יראתי. בחי' אודנין כי חבקוק היה בבחי' הריחוק שהוא בחי' שוב כענין וינועו ויעמדו מרחוק ומזה נמשך מלמעלה למטה כי שמע ה' כי שנואה אנכי ויתן לי וגו' שמזה יהי' התקרבות מלמעלה (ושנואה שאינה אהובה כ\"כ שהרי כתיב ויאהב גם את רחל מלאה) מחמת שעושה א\"ע רחוק ושמאל דוחה ונק' שנואה כי שמאלו תחת לראשי ועי\"ז אח\"כ בחי' לוי ט\"ו ווי\"ן דאמוי\"צ. וג' בחי' אלו הן ג' קוין חח\"ן בג\"ה ודת\"י שהוא קו האמצעי הוא בחי' לוי. שע\"י ג' בחי' אלו נמשך בחי' יהודה יודוך אחיך להיות בחי' הודאה כתר מל' דהנה המל' היא בחי' מקבל ול\"ל מגרמה כלום ואעפ\"כ אחר שמקבלת הרי היא בחי' מלכות עליהם (ונק' כתר מל' שהיא בחי' כתר מלמטה למעלה) הגם שהם ממשיכים לה האורות ופרקין (וע' בזהר בלק ע\"פ גבורי כח עושי דברו לשמוע בקול דברו כו') וה\"ז כמשל המלך ב\"ו שהוא מקבל המס הכסף והזהב מאנשי מדינתו ואעפ\"כ הרי הוא מולך עליהם כו' כך המל' שרשה בכתר נעוץ סופן בתחלתן רק שצריך המשכת הכתר הנק' טמירו דכל טמירין שיהי' בגילוי בבחי' אתה ולכן יודוך אחיך מכתר למל' ע\"י ג' קוין הנ\"ל ראובן פ' ראשונה דק\"ש בחי' שם מ\"ב ושמעון פ' שניה ע\"ב (וע' במ\"א דלכאורה שם מ\"ב הוא גבורה ושם ע\"ב חסד אלא שהוא בחי' אור הגבורה בכלי החסד ואור החסד בכלי הגבורה) ולוי אמוי\"צ בחי' הממוצע ונק' היכל הרצון שלמעלה מהיכל האהבה שלפני ק\"ש וכו'. והיכל קד\"ק אדני שפתי כו' סמיכת גאולה לתפלה להיות בחי' יודוך אחיך בחי' הודאה בחי' בטול בחי' כתר. ותעמוד מלדת אין עמידה אלא תפילה (והוא ג\"כ לשון עמידה ושתיקה ובטול שהוא בחינת כתר שהוא לשון שתיקה כמו כתר לי זעיר כי הסייג דחכמה הוא שתיקה כמ\"ש במ\"א בענין יונת אלם וכו'):"],[64,"<b>ידך<\/b> בעורף אויביך. כי המל' יש לה עליות וירידות הפעם אודה ובלילה יורדת לברר בי\"ע כמ\"ש ותתן טרף ואין בירור אלא בבחי' אחוריים כי הפנימיות מתכלל כנר בפני אבוקה בלי בירור כו'. וענין ישתחוו לך בני אביך הוא בחי' המשכה מבחי' אבא למל' אבא יסד ברתא כי יודוך אחיך הוא המשכה מכתר שהוא ע\"י ג' קוין הנ\"ל. משא\"כ בני אביך המשכת אבא ב' קוין והם ראובן ולוי חח\"ן ע\"י גמ\"ח ודת\"י ע\"י תורה נובלות חש\"מ כו':"],[64,"<b>וענין<\/b> כי ראה ה' בעניי הנה בירורי' ותשובה הכל ענין א' שהי' יורד ממקום גבוה וצריך לעלות לשם נק' תשובה וכן הנשמה ירדה לצורך עליי'. והנה ההתקרבות שמחמת בחינת עניי שהוא מרירות הנפש על ריחוקה (עד שגם הנה\"ב והגוף יהיו בבחינת אתהפכא כו') היא יותר גדולה כיתרון האור הבא מן החשך וכנודע ממ\"ש במ\"א בענין ויברך יעקב את פרעה מה ההוא סט' וכו':"],[65,"<b>אסרי לגפן עירה ולשורקה בני אתונו.<\/b> כבס ביין לבושו וגו'. הנה מקרא זה נאמר לימות המשיח דקאי אדלעיל מני' לא יסור שבט מיהודה וגו'. עד כי יבא שילה ולו יקהת עמים ואז יהיה גם אסרי לגפן עירה:"],[65,"<b>וביאור<\/b> הענין הנה אמרז\"ל אין בין עולם הזה לימות המשיח אלא שעבוד בלבד כי ימות המשיח אינו עוה\"ב שלאחר התחיה. שזהו מתן שכרן של צדיקים. אבל ימות המשיח הוא בבחי' היום לעשותם ולא לקבל שכרן."],[65,"ועיקר היום לעשותם ותכלית השלימות של המעשה יהיה בימות המשיח. וכמו שהיה עיקר עבודת האדם בג\"ע לעבדה ולשמרה. לעבדה זו מצות עשה. ולשמרה זו מצות ל\"ת. ⟦מו,ב⟧שהי' אז בחי' היום לעשותם בתכלית השלימות אלא שאח\"כ ויגרש את האדם וגו'. ואח\"כ נכנסו אבותינו לארץ ג\"כ בשביל קיום מעשה המצות שכמה מצות התלוים בארץ דוקא כמעט ארבע הידות ואחר כך גלו משם ולא נתקיימו בידם עד ימות המשיח שיהיה במהרה בימינו שאז יהי' בחי' היום לעשותם בתכלית השלימות."],[65,"והנה אנו אומרים ושם נעשה לפניך את קרבנות חובותינו וכו' כמצות רצונך כו'. שעיקר המעשה היא עבודת הקרבנות שאין אנו יכולים לקיים בגלות אלא שבגלות נתקנה התפלה כנגד הקרבנות. ועדיין אין זה כמצות רצונך ממש:"],[65,"<b>ולהבין<\/b> זה דלכאורה התפלה במעלה העליונה יותר מהקרבנות שהתפלה היא נשיאת נפש האדם בספור שבחיו של מקום ברוך שאמר והיה העולם וכל הללויה וכו' עד שמגיע לואהבת בכל נפשך כו' משא\"כ הקרבנות הוא בנפש בהמה וביום השבת שני כבשים. ולמה יהיו הקרבנות במעלה העליונה כל כך שיקראו כמצות רצונך ושזה יהי' תכלית השלימות של ימות המשיח יותר מהתפלה שבגלות. הנה כתיב גפן ממצרים תסיע. שכנ\"י נמשלו לגפן שגדלים בה ענבי' שמהם יוצא היין ע\"י דריכה בגת."],[65,"והנה עיקר היין המשובח יוצא מהענבי' הסמוכי' לקרקע כמו שאמרו לגבי נסכים לא היו מביאין מן הדליות אלא מן הרגליות ששם יוצא יין משובח יותר. והנה היין נתחלק לכמה מינים יש יין המשמח ויש יין המשכר יש יין אדום ויש יין לבן וכך ככל המשל הזה נמשלו כנס\"י שיש בהם אהבה מסותרת למקום כו'."],[65,"וכדי להוציאה מהעלם אל הגלוי צריך להיות בבחי' רגליות דהיינו להיות בחי' נפשי כעפר לכל תהיה. וגם דריכה בגת להיות לב נשבר ונדכה וע\"י זה יוצא היין הוא בחי' האהבה מסותרת שהיתה בהעלם כי על יין אמרו נכנס יין יצא סוד והיינו לפי שהיין היה ג\"כ מתחלה בהעלם בענבים ואח\"כ נתגלה ויצא לחוץ."],[65,"והנה באהבה יש ב' בחי'. יש מתפעל להיות שמחת ה' בלבו היא בחינת יין המשמח ובחי' יין לבן מבחי' חמר חיווריין עתיק כו'. ויש מתפעל להיות לו מרירות הלב מפני היותו ממארי דחושבנא מכל מחשבותיו ודבוריו ומעשיו אשר לא לה' המה ולצעוק אל ה' ולדבקה בו הוא בחי' יין אדום ויין המשכר וכו'."],[65,"והנה אנו אומרים בשבת וינוחו בו ישראל מקדשי שמך. ולכאורה אינו מובן הלא הוא ית' מאליו קדוש וכתיב כי קדוש אני וקדושתי למעלה מקדושתכם. ואיך יהיה תלוי קדושתו ית' בישראל דייקא שיקראו הם המקדישים שמו. אך הענין דהנה אנו אומרים אתה קדוש ושמך קדוש וקדושים בכל יום יהללוך סלה. פי' קדושים בכל יום כו' כמאמר המחדש בטובו בכל יום תמיד מעשה בראשית שבכל יום ויום מתהווה מאין ליש כל מעשה בראשית."],[65,"וכשהם משיגים כל יום התהוותם וחיותם מבחי' קדוש ומובדל כי עליו ית' נאמר אדון הנפלאות פי' למעלה מעלה מבחי' נפלאות כמ\"ש עושה פלא. שבחי' הפלא הוא כעשיה גשמיות אצלו ית'. כי ענין הפלא היא פליאת ההתהוו' יש מאין וראשית ההתהוו' הוא בחכמה כמ\"ש והחכמה מאין תמצא."],[65,"וכתיב כולם בחכמה עשית שהחכמה נחשבת אצלו כעשיה גשמית שהיא בחי' סוף דרגין משכל ודבור ומחשבה ומעשה וכך החכמה נחשבת אצלו שהוא ית' למעלה מן החכמה ומרומם עד אין קץ. ולכן הם יהללוך סלה תמיד בעילוי אחר עילוי בלי הפסק וכל זה בבחי' ושמך קדוש כי הודו של שמו על ארץ ושמים. כמ\"ש כי ביה ה' צור עולמים פי' בי\"ה הוא שמו הוי\"ה כי הו\"ה היא ג\"כ י\"ה שהוי\"ו מושך היו\"ד כו'."],[65,"וביו\"ד נברא העוה\"ב כנ\"ל היינו עלמין סתימין דלא אתגליין עין לא ראתה אלהים זולתך ובה\"א נברא עוה\"ז היינו עלמין דאתגליין מה שהוא מושג ונתפס בהשגת ⟦מו,ג⟧הנבראים ואפי' ג\"ע העליון נק' עלמא דאתגלי' לגבי בחי' זו שהוא שם שהרי צדיקי' נהנים כו' אלא שלגבי עוה\"ז השפל הגשמי נק' עוה\"ב ג\"ע העליון. אבל לגבי עולמות עליוני' נקרא בשם עוה\"ז ועלמא דאתגליא מאחר שיש שם הנאה ותענוג הנשמות משא\"כ בחי' עלמין סתימין הוא מה שאינו מושג ונתפס כלל עין לא ראתה וכו' וכל בחי' הללו הם מבחינת שמו והודו של שמו כו'. אבל בא\"ס ב\"ה עצמו לא שייך כלל זה שהוא קדוש ומובדל מגדר עלמין לגמרי ולא שייך אפילו בחי' עלמין סתימין כו' ובחינת עלמין סתימין הם כעשיות גשמיות אצלו ית'."],[65,"וכמאמר אדון הנפלאות. וכמ\"ש עושה פלא. ומה שקדושים בכל יום יהללוך סלה הוא בבחי' ושמך קדוש בלבד והיינו כי משם נמשך קדושתם ומהללים להתכלל ולהבטל במקורם. אבל ישראל הם מקדשי שמך כי הנה באתעדל\"ת תלוי אתעדל\"ע להיות התלבשות א\"ס ב\"ה בחכמה וחסד להחיות ולהוות עלמין סתימין ועלמין דאתגליין והיינו אק\"ב ממש הקב\"ה מניח תפילין כו'."],[65,"וע\"י הנחת תפלין למטה מתעורר קדושה העליונ' שלמעל' להיות שורה ומתלבש בתוך עלמין. וקדושה זו היא מבחי' אוא\"ס ב\"ה בעצמו ובכבודו שלמעלה מגדר עלמין בחי' אתה קדוש שהוא אדון הנפלאות למעלה מעלה מבחינת פליאות חכמה שמאין תמצא כי המצות הן הן רצונו ית' ובחי' מדרגת הרצון הוא הגבה למעלה מאד מבחי' חכמה."],[65,"ולכן הם מקדישי' ומרוממים שמך שבהם ועל ידם נתעלה בחי' שמו בקדושת אור א\"ס ב\"ה עצמו. וזהו יפה שעה אחת בתשובה ומע\"ט בעוה\"ז מכל חיי עוה\"ב שהם מבחינת שמו ית' בלבד. אבל ע\"י המע\"ט ממשיכים קדושת אור א\"ס ב\"ה בעצמו כנ\"ל:"],[65,"<b>והנה<\/b> מן המצות נעשה לבושים לנפש כמ\"ש בזוהר ע\"פ ואברהם זקן בא בימים באינון יומין עילאין דאינון לבושין כנ\"ל. והיינו לפי שע\"י המצות ממשיך אור מקיף מבחי' סובב כל עלמין לכן נעשה לבוש לנשמתו שתהיה נפשו צרורה בצרור החיים את ה' וכו'. אך הנה אמרו אפילו פושעי ישראל מלאים מצות כרמון ומ\"מ אין ממשיכין כלום. אלא הענין הוא שהמשכת קדושה העליונה הוא ע\"י שמחה של מצוה דוקא וכדכתיב תחת אשר לא עבדת את ה' אלקיך בשמחה."],[65,"והשמחה היא מצד התבוננות מזה עצמו איך שהמצות הם בחינת אור א\"ס ב\"ה עצמו בחי' אדון הנפלאות וכו'. ולזה ישמח לבו בקיום המצות אשר קדשנו במצותיו ממש והוא בחי' חמר חווריין עתיק שהוא בחי' ענג העליון להתענג על ה' ממש. אך צריך לעורר מתחלה בנפשו בחי' יין אדום ויין המשכר שהוא בחי' גבורות קדושות כדי לאתהפכא חשוכא לנהורא ומרירו למיתקא שאז יתענגו על ה' בתענוג המשכת אוא\"ס ב\"ה כי התענוג הוא שייך אחר מילוי הרצון שכשנתמלא רצונו וחפצו מה שהיה חושק ומתאוה אז יתענג משא\"כ אם לא היה לו תשוקה כ\"כ אין התענוג אצלו כ\"כ גם בהיות אצלו הדבר ההוא ולכן צריך לעורר תחלה בחינת גבורות על הירידה אשר רחוק מה' בתכלית."],[65,"ובפרט כאשר יהי' ממארי דחושבנא מן המעשים ודבורים והמחשבות אשר לא לה' המה. וישוב אל ה' וירחמהו וכמאמר אלהי עולם ברחמיך הרבים כו' וכמ\"ש במ\"א ואזי תהי' שמחת הנפש בקיום המצות ביתר שאת כי כל שתגדל התשוק' והצמאון מחמת ריחוק מקום מצד הגוף כך תגדל שמחת הנפש מצד המשכ' אוא\"ס ב\"ה בקיום המצות והתענגו על ה' במילוי רצונה וחפצה וז\"ש זאת נחמתי בעניי כי אמרתך חייתני וכמאמר כי הם חיינו ואורך ימינו כו' ואין לערב שמחת הנפש בעצבון הגוף וכו'. אך כדי להוציא בחי' יין ⟦מו,ד⟧הנ\"ל צריך לשית עצות בנפשו להיות בבחינת ונפשי כעפר לכל תהיה מן הרגליות וכו'. ועל ידי דריכה ברגלים בגת שהיא בחינת לב נשבר ונדכה כו'."],[65,"והנה כנגד ב' בחינות יין הנ\"ל כך נמשך ב' בחינת לבושין. וזהו כבס ביין לבושו שיהיו לבושי המצות מכובסים עד\"מ כמו בגד המכובס מן הלכלוך כך הנה אפי' פושעי ישראל מלאים מצות כו'."],[65,"ואעפ\"כ את פושעי' נמנו שלבושי המצות שלהם הם מלובשי' בלבושים צואים שלהם משא\"כ ע\"י בחי' יין ושמחה של מצוה נעשה בחי' כבוס לבוש והתפשטות מלבושי' שבנוגה להתענג על ה' לבדו. וע\"י בחי' דם ענבים הוא בחי' יין אדום שהוא ענין התגברות הנפש לאהפכא חשוכא לנהורא והמרירות על ריחוקו מאור פני ה' ונק' דם לפי שצריך יגיעת הנפש ויגיעת בשר בנפשו דמו. אך מ\"מ נק' דם ענבים בחי' יין שצ\"ל ע\"י בחי' שמחה שהיא בחי' התבוננות מצד גדולת ה' א\"ס ב\"ה וישוב אל ה' וירחמהו."],[65,"וירחמהו דייקא דהיינו על ניצוץ אלהו' שבו איך ירד פלאים מטה מטה כמ\"ש במ\"א ועי\"ז נעשה בחי' סותו פי' סותו מלשון מסוה הוא כסוי הראש והפנים שיש ב' בחינות לבושין לבוש הגוף ע\"ד משל ולבוש הראש והפנים ע\"ד משל."]]);
